INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(11981, 'koKR', 'Odnajdź Kuruna!', 'Kamienna powierzchnia ziemnego wojownika pokryta jest pęknięciami i żłobieniami. Choć nie może krwawić, wyczuwasz, że wojownik jest bliski śmierci.$B$BZ ust konającego wojownika wydobywa się niski, chrapliwy głos.$B$B„Odnajdź... Kuruna... musisz odnaleźć... Kuruna”.$B$BGdy pytasz o jakąkolwiek wskazówkę, kim lub czym może być Kurun, wojownik patrzy na ciebie bezradnie.$B$B„Nasz... przywódca... stoi na... wzgórzu nad Thor Modan... dowodzi nami. Proszę... powiedz mu... że nie zdobędziemy... miasta...”', 'Porozmawiaj z Kurunem na wzgórzu górującym nad Thor Modan.', '', '', '', '', '', '', 0),
(11982, 'koKR', 'Deszcz zniszczenia', 'Pod nami leży starożytny bastion żelaza, Thor Modan. Tysiące lat temu kamienne olbrzymy rozdarły tu ziemię, zawalając część miasta i odsłaniając większość reszty.$B$BNawet teraz żelazne krasnoludy próbują odzyskać swoją dawną stolicę, ale nie pozwolimy na to. Moje olbrzymy zasypują rów głazami i gruzem, by go zamknąć i zabić sługi żelaza przy pracy. Weź głazy leżące przy rowie na północnym wschodzie i pomóż nam położyć kres ich staraniom.', 'Kurun na wzgórzu górującym nad Thor Modan chce, żebyś $gprzeszkodził:przeszkodziła; żelaznym krasnoludom w pracy, zrzucając głazy na odsłoniętą część Thor Modan.', '', 'Wróć do Kuruna na Głazowych Wzgórzach we Wzgórzach Grizli.', 'Zakłócone prace żelaznych krasnoludów', '', '', '', 0),
(11984, 'koKR', 'Napełnianie klatek', 'Stary Budd widział lepsze dni.$b$bOd naszego pobytu w Widmowych Ziemiach jest dla nas bezużyteczny. Musieliśmy radzić sobie sami, a dziś znaczy to sprzedawanie trolli temu, kto da najwięcej.$b$bNa szczęście niedawno znaleźliśmy dla Budda zajęcie. Coś w jego stanie pozwala mu wtapiać się w tłum miejscowych trolli, więc nauczyliśmy go pewnej zabawy, która przyniosła nam niezły zysk.$b$bPrzekonaj się. Porozmawiaj z Buddem, zaprowadź go na południowy zachód do Ruin Drak\'Zin i użyj tej klatki, gdy tylko ogłuszy jakiegoś trolla.', 'Samir w Granitowych Źródłach chce, żebyś $gużył:użyła; klatki łowcy nagród na trollu Drakkarów ogłuszonym przez Budda.', '', 'Wróć do Samira w Granitowych Źródłach we Wzgórzach Grizli.', 'Schwytany żywy lodowy troll', '', '', '', 0),
(11985, 'koKR', '', 'Jeśli nie pokonamy obrońców w Thor Modan, żelazne krasnoludy wytrzymają tam w nieskończoność. Ziemni dzielnie stawiają czoła konstruktom zbudowanym przez synów żelaza, ale nie potrafią wedrzeć się do miasta.$B$BTunele zbyt szybko się zwężają, by moi bracia olbrzymi mogli się na coś przydać, więc mamy niewiele możliwości. Czy $gzechciałbyś:zechciałabyś; zapuścić się do miasta i zabić krasnoluda, który dowodzi obroną?', 'Kurun na wzgórzu górującym nad Thor Modan chce, żebyś $gzabił:zabiła; żelaznego thana Argruma.', '', 'Wróć do Kuruna na Głazowych Wzgórzach we Wzgórzach Grizli.', '', '', '', '', 0),
(11986, 'koKR', 'Zniszczony dziennik', 'Ten poobijany, uwalany błotem dziennik widział lepsze dni. Kartkując go, znajdujesz dziesiątki notatek, rysunków i map.$B$BCharakter pisma autora wydaje się jakby znajomy, ale nie możesz go przypisać, dopóki nie trafiasz na wpis podpisany nazwiskiem Branna Miedziobrodego.$B$BTylna połowa książki, z najnowszymi wpisami, została wyrwana. Kartki walają się po całym polu bitwy i nie sposób się dowiedzieć, co Brann tu odkrył, dopóki dziennik nie będzie znów kompletny.', 'Odzyskaj 8 zaginionych kartek z dziennika, połącz je z niekompletnym dziennikiem i zanieś uzupełniony dziennik Torthenowi Głębokopowi w Obozowisku Brygady Zachodniego Skraju.', '', 'Wróć do Torthena Głębokopa w Obozowisku Brygady Zachodniego Skraju we Wzgórzach Grizli.', '', '', '', '', 0),
(11988, 'koKR', 'Runiczny zwornik', 'Dziennik Branna wspomina, że użył runicznego zwornika, by podświetlić ważne runy na odkrytej przez siebie płycie. Bez zwornika treść płyty byłaby niewiele więcej niż bełkotem.$B$BW ostatnim wpisie Brann opisuje, jak żelazne krasnoludy, broniące miasta, odebrały mu zwornik, rozbiły go i podzieliły się jego kawałkami. Zanim odczytamy runiczną płytę, musimy odnaleźć te fragmenty. Może je mieć każdy krasnolud w Thor Modan albo w okolicznych budynkach.', 'Przynieś 5 fragmentów runicznego zwornika Torthenowi Głębokopowi w Obozowisku Brygady Zachodniego Skraju.', '', 'Wróć do Torthena Głębokopa w Obozowisku Brygady Zachodniego Skraju we Wzgórzach Grizli.', '', '', '', '', 0),
(11989, 'koKR', 'Rozejm?', 'Uważaj na siebie, mon.$b$bDrakuru pomniejszył więcej głów takich jak ty, niż może spamiętać, a nawet jakby spamiętał, to by tak wysoko nie zliczył. Masz szczęście, że siedzę w tej klatce, bo inaczej dopisałbym do listy jeszcze jedną.$b$bAle skoro jest, jak jest, to może odłożymy na trochę nasze różnice, co?$b$bDrakuru wie różne rzeczy, mon. Rzeczy, które pomogą ci w walce tutaj.$b$b<Drakuru rozcina sobie dłoń o jeden z kłów i wyciąga ją przez kraty klatki.>$b$bTo co ty na to, mon... rozejm?', 'Drakuru w Granitowych Źródłach chce, żebyś $gużył:użyła; tępego noża do krojenia przy jego klatce, a potem z nim $gporozmawiał:porozmawiała;.', '', 'Wróć do Drakuru w Granitowych Źródłach we Wzgórzach Grizli.', 'Pakt krwi z Drakuru', '', '', '', 0),
(11990, 'koKR', 'Fiolka wizji', 'Najpierw najważniejsze, mon. Jest trochę roboty na przygotowanie.$b$bNie wiadomo, jak długo będą mnie tu trzymać. Potrzebny ci będzie mocny eliksir, żebyśmy mogli być w kontakcie.$b$bMasz szczęście, znam coś w sam raz! A wszystkie składniki są blisko.$b$bPotrzebuję fiolkę od tej ślicznej małej trollicy tam, trochę wodorostu z jeziora na północ stąd i kilka mglistych liści, co rosną wokół obozu.$b$bPośpiesz się, mon, zanim mnie stąd wywloką.', 'Drakuru w Granitowych Źródłach chce, żebyś $gprzyniósł:przyniosła; mu nasyconą fiolkę, liść wodorostu i 3 mgliste liście.', '', 'Wróć do Drakuru w Granitowych Źródłach we Wzgórzach Grizli.', '', '', '', '', 0),
(11991, 'koKR', 'Kwestia interpretacji', 'Legendarny zestaw artefaktów, zaginionych od tysięcy lat, stworzono, by uczynić Twierdzę Drak\'Tharon niezdobytą.$b$bWiększość myśli, że to mit, ale Drakuru wie lepiej, mon!$b$bPrawie odkryłem, gdzie jest jeden z nich, ale złapali mnie, jak odczytywałem hieroglify. Musisz przywołać tam z powrotem moją duszę, żebym skończył je czytać!$b$bUżyj mojego eliksiru przy kadzielnicy w Ruinach Drak\'Zin, na południowy zachód stąd. Musisz do niego dodać zamarznięte mojo, które mają moi bracia. Przykro patrzeć, jak moi bracia padają, ale to dla większego dobra.$B', 'Drakuru chce, żebyś $gzdobył:zdobyła; 5 zamarzniętych mojo od trolli Drakkarów w Ruinach Drak\'Zin, a następnie $gużył:użyła; eliksiru przy tamtejszej Kadzielnicy Drakuru.', '', '', '', '', '', '', 0),
(11993, 'koKR', 'Runiczne proroctwa', 'Nie ma czasu do stracenia! Teraz, gdy złożyliśmy runiczny zwornik – no, większość – możemy odczytać te same runiczne płyty, nad którymi pracował Brann, zanim uciekł.$B$BNie wiemy, czy zdołał odczytać wszystkie trzy płyty, ale musimy założyć, że dowiedział się dość, by ustalić swój następny cel.$B$BStań przed każdą z płyt i użyj zwornika, by odczytać ich treść. Brann może na nas liczyć!', 'Torthen Głębokop w Obozowisku Brygady Zachodniego Skraju chce, żebyś $godczytał:odczytała; trzy płyty runiczne.', '', 'Wróć do Torthena Głębokopa w Obozowisku Brygady Zachodniego Skraju we Wzgórzach Grizli.', 'Odczytana pierwsza przepowiednia', 'Odczytana druga przepowiednia', 'Odczytana trzecia przepowiednia', '', 0),
(11997, 'koKR', '', 'Brygadę Zachodniego Skraju wysłano w północno-wschodnią część Wzgórz Grizli, by zabezpieczyła przejście dla naszych wojsk. Założyła obóz bazowy na północny wschód od Siwopaszczy i na południowy zachód od Thor Modan.$B$BByć może rozpoznasz dowódcę brygady, kapitana Gryana Mocnopłaszcza, zasłużonego weterana wojny z Plagą w Lordaeronie. Mieszkańcy Zachodniego Skraju znają go jednak najlepiej z tego, że porzucił pole bitwy i wrócił do domu, by stawić czoła Nieskornym.', 'Porozmawiaj z kapitanem Gryanem Mocnopłaszczem w Obozowisku Brygady Zachodniego Skraju.', '', '', '', '', '', '', 0),
(11998, 'koKR', 'Złagodzić cios', 'Najlepiej szybko przerzucimy nasze siły na Lodowiec Lodowej Korony siecią tuneli pod starożytnym miastem żelaznych krasnoludów, Thor Modan.$B$BBrugar Skałorzez i jego chłopaki z Ligi Odkrywców nie będą zachwyceni, ale rozkaz to rozkaz.$B$BWieść może lepiej przejść, jeśli przyniesiesz mu baryłkę bimbru, który sprzedaje ten traper, Hugh Glass, w Faktorii Czerwonego Drewna, na południowy wschód stąd, wzdłuż skraju lasu.$B$BFacet nie ma równo pod sufitem, ale lepszego bimbru tu nie znajdziesz.', 'Zanieś Brugarowi Skałorzezowi w Obozowisku Brygady Zachodniego Skraju baryłkę Bimbru do wycia.', '', 'Wróć do Brugara Skałorzeza w Obozowisku Brygady Zachodniego Skraju we Wzgórzach Grizli.', '', '', '', '', 0),
(12002, 'koKR', 'Bracia w boju', 'Mam nadzieję, że Gryan wie, że wycofałem ludzi z Thor Modan, gdy zaczęła się bitwa. Nie ma mowy o żadnych wykopaliskach, dopóki tam się nie uspokoi.$B$BWyglądasz jednak na kogoś odważnego i masz zaufanie Mocnopłaszcza.$B$BThor Modan leży tuż na północny wschód od nas, a bitwa między naszymi braćmi ziemnymi a tworami tych przeklętych żelaznych krasnoludów wciąż trwa. Pomóż naszym braciom wyrównać szanse, a ja zacznę się zastanawiać, jak przeprowadzimy te badania Thor Modan.', 'Zabij 10 runicznych golemów bitewnych i wróć do Brugara Skałorzeza w Obozowisku Brygady Zachodniego Skraju.', '', 'Wróć do Brugara Skałorzeza w Obozowisku Brygady Zachodniego Skraju we Wzgórzach Grizli.', '', '', '', '', 0),
(12003, 'koKR', 'Odkrywanie tuneli', 'Wejść do systemu tuneli Thor Modan najpierw poszukamy w budynkach na obrzeżach.$B$BGdy odchodziłem stamtąd z moimi ludźmi, wyglądało na to, że krasnoludzcy obrońcy chowają się w budynkach. Uważaj, gdy będziesz je przeszukiwać.$B$BWejścia do tuneli są pewnie gdzieś w tylnej części budynków. Nie wiem, co Mocnopłaszcz spodziewa się tam znaleźć, ale wątpię, by żelazne krasnoludy ułatwiły nam poszukiwania.', 'Brugar Skałorzez w Obozowisku Brygady Zachodniego Skraju chce, żebyś $gzbadał:zbadała; Północny budynek, Wschodni budynek i Południowy budynek w Thor Modan.', '', 'Wróć do Brugara Skałorzeza w Obozowisku Brygady Zachodniego Skraju we Wzgórzach Grizli.', 'Zbadaj Północny budynek', 'Zbadaj Wschodni budynek', 'Zbadaj Południowy budynek', '', 0),
(12007, 'koKR', 'Trzeba ponieść ofiary', 'Mam to, mon!$b$bNa północy, na zigguracie w Zeb\'Halak, jest kamienna głowa z rubinowymi oczami. Jedno z nich to Oko Proroków! Zanieś je do tamtejszej kadzielnicy i wypij mój eliksir.$b$bZnowu potrzebne ci będzie trochę mojo, żeby mój eliksir zadziałał – tym razem od wodza, Zim\'bo. Chowa się w jednej z chat w Zeb\'Halak.$b$bSzkoda zabijać Zim\'bo, mon, ale on przysięgał na krew bronić Drak\'Tharon i zawiódł. Teraz przynajmniej jego mojo pomoże nam odzyskać Drak\'Tharon.', 'Drakuru chce, żebyś $gprzyniósł:przyniosła; mu Oko Proroków do Kadzielnicy Drakuru w Zeb\'Halak.$b$bBędzie ci potrzebne Mojo Zim\'bo, żeby użyć tam Eliksiru Drakuru.', '', 'Wróć do Wizerunku Drakuru w Zeb\'Halak we Wzgórzach Grizli.', '', '', '', '', 0),
(12010, 'koKR', 'Los Orlonda', 'Kiedy zaczęliśmy wykopaliska w mieście, wysłałem mierniczego Orlonda, żeby sprawdził stabilność tuneli w Thor Modan. Nie widziałem, żeby uciekł, gdy wycofywaliśmy się na początku bitwy, i martwię się, że wciąż może być uwięziony w mieście.$B$BJeśli mamy przeprowadzić armię przez Thor Modan, będziemy potrzebować informacji, które zbierał. Mocnopłaszcz i jego przełożeni obdarliby mnie ze skóry, gdyby tunele zawaliły się na którąś z ich brygad!', 'Odnajdź mierniczego Orlonda w Thor Modan.', '', '', '', '', '', '', 0),
(12014, 'koKR', 'Solidne jak skała?', 'Z notatek Orlonda wynika, że zabrał ze sobą urządzenie zwane przenośnym sejsmografem, ale nigdzie go nie widać.$B$BDziennik pomiarów pokazuje, że Orlond wykonał wszystkie odczyty w tunelu Thor Modan poza jednym, opisanym jako „wschodni koniec odsłoniętego tunelu”.$B$BOstatni wpis w dzienniku mówi, że Orlond próbował schronić się w wodzie i został zaatakowany przez podziemne młocarze. Mogły zabrać jego sprzęt. Musisz go odzyskać, zanim wykonasz ostatni odczyt.', 'Odzyskaj przenośny sejsmograf i użyj go do pomiarów stabilności w Thor Modan, a następnie wróć do Brugara Skałorzeza w Obozowisku Brygady Zachodniego Skraju.', '', 'Wróć do Brugara Skałorzeza w Obozowisku Brygady Zachodniego Skraju we Wzgórzach Grizli.', '', '', '', '', 0),
(12026, 'koKR', 'Zniszczony dziennik', 'Ten poobijany, uwalany błotem dziennik widział lepsze dni. Kartkując go, znajdujesz dziesiątki notatek, rysunków i map w języku krasnoludów.$B$BJedyny tekst, który potrafisz odczytać, to nazwisko Branna Miedziobrodego nabazgrane na końcu jednego z wpisów.$B$BTylna połowa książki, z najnowszymi wpisami, została wyrwana. Ktoś uznał te notatki za na tyle ważne, by spróbować je zniszczyć. Może zebranie zaginionych kartek z pola bitwy dostarczy jakichś wskazówek.', 'Odzyskaj 8 zaginionych kartek z dziennika, połącz je z niekompletnym dziennikiem i zanieś uzupełniony dziennik mędrczyni Palunie w Obozie Oneqwah.', '', 'Wróć do mędrczyni Paluny w Obozie Oneqwah we Wzgórzach Grizli.', '', '', '', '', 0),
(12027, 'koKR', 'Niebezpieczna przygoda Pana Kłapusia', 'Przepraszam, $gproszę pana:proszę pani;, zna $gpan:pani; drogę z powrotem do obozu żołnierzy?$B$BPan Kłapuś i ja postanowiliśmy pójść na spacer do lasu, i mój brat Walter miał iść z nami, ale potem musiał robić rzeczy giermka.$B$BWięc Pan Kłapuś i ja poszliśmy sami, ale zgubiliśmy się, i było tam mnóstwo głodnych wilków, ale znaleźliśmy tę wieżę.$B$BWilki sobie poszły, ale dalej jesteśmy zgubieni.$B$BZapytałam Pana Kłapusia, a on nie zna drogi z powrotem. Pomoże nam $gpan:pani;? Proszę?', 'Pomóż Emily i Panu Kłapusiowi wrócić do Obozowiska Brygady Zachodniego Skraju, a potem porozmawiaj z giermkiem Walterem.', 'Pomóż Emily i Panu Kłapusiowi wrócić do obozu', 'Wróć do giermka Waltera w Obozowisku Brygady Zachodniego Skraju we Wzgórzach Grizli.', '', '', '', '', 0),
(12029, 'koKR', 'Spalona Plaga', '<Hik>... trzeba szpalić te truchła, zanim znowu zaczną łazić.$b$bTatko zawsze mówił, że gorzej niż zabić trolla jeszt tylko zabić trolla dwa razy.$b$bSłuchaj,<hik>... jak już mowa o Pladze, nie wejdziemy do tej trollowej twierdzy na północy, dopóki trochę nie przerzedzimy tych trolli.$b$bMoże weźmiesz trochę mojego grogu i skrócisz męki tych drani?', 'Mack w Granitowych Źródłach chce, żebyś $gużył:użyła; jego grogu, by spalić 20 wygłodniałych trolli Plagi w Drak\'Tharon.', '', 'Wróć do Macka Fearsena w Granitowych Źródłach we Wzgórzach Grizli.', 'Spalone trolle Plagi', '', '', '', 0),
(12037, 'koKR', 'Poszukiwania i ratunek', 'Orczyce... one nigdy nie słuchają – hik. Wiesz, o co mi chodzi?$b$bKurzel jest z nami od lat. Można by pomyśleć, że już się połapała, jak tu działamy. Wciągasz głupców do niebezpiecznej roboty, a potem zbierasz nagrody, kiedy już jest bezpiecznie. Co w tym trudnego do zrozumienia?$b$bAle nie ona... niecierpliwa zielonoskóra poszła i wzięła sprawy w swoje ręce. Pewnie już nie żyje, ale czułbym się okropnie, gdybyśmy za nią nie poszli, a sam nie jestem w stanie – hik.$b$bTo co ty na to, $gkolego:koleżanko;?', 'Mack w Granitowych Źródłach chce, żebyś $gposzedł:poszła; do Drak\'Tharon i $gsprawdził:sprawdziła;, co się stało z Kurzel.', '', '', '', '', '', '', 0),
(12038, 'koKR', 'Spalona Plaga', 'Na co czekasz, $N? Te splugawione trolle same się nie zabiją!$b$bWiesz, co robić. Idź do Drak\'Tharon na północy... Weź trochę tego grogu i rzucaj nim w nie z daleka...<hik>. A potem szobie usiądź i patrz, jak płoną.', 'Mack w Granitowych Źródłach chce, żebyś $gużył:użyła; jego grogu, by spalić 30 wygłodniałych trolli Plagi.', '', 'Wróć do Macka Fearsena w Granitowych Źródłach we Wzgórzach Grizli.', 'Spalone trolle Plagi', '', '', '', 0),
(12042, 'koKR', 'Serce Pradawnych', 'Sekrety wieków, objawcie mi się teraz!$b$b<Drakuru spogląda przez Oko Proroków.>$b$bAch, wielkie jest moje przeznaczenie, $n. Masz szczęście, że mnie znasz...$b$bTam! Widzę je, mon. Serce Pradawnych. To aż za łatwe!$b$bZnajdziesz serce koło zwłok goblina na wschód stąd. Jest w komnacie na górze, przy rzece połamanych drzew.$b$bPośpiesz się, mon, zanim ktoś inny je znajdzie!', 'Drakuru chce, żebyś $gposzedł:poszła; do najwyższej komnaty w Tartaku „Błękitne Niebo” i $godnalazł:odnalazła; Serce Pradawnych.', '', '', '', '', '', '', 0),
(12054, 'koKR', 'Odczytanie dziennika', 'Vor\'takh ma rację – nie możemy pozwolić, by ta okazja przeciekła nam przez palce.$B$BNa szczęście chyba wiem, jak przetłumaczyć dziennik tego Branna.$B$BSzamani furbolgów Czerwonego Kła, którzy zbierają się w Kaplicy Krwi Serca na południe od obozu, uprawiają ziele zwane tchnieniem duchów. Doświadczony mistyk może użyć zrobionego z niego kadzidła, by szukać mądrości u duchów przodków.$B$BOdszukaj szamana znanego jako Grumbald Jednooki. Powinien mieć przy sobie to ziele do modłów ku czci Ursoca.', 'Przynieś gałązkę tchnienia duchów mędrczyni Palunie w Obozie Oneqwah.', '', 'Wróć do mędrczyni Paluny w Obozie Oneqwah we Wzgórzach Grizli.', '', '', '', '', 0),
(12058, 'koKR', 'Runiczne proroctwa', 'Dziennik Branna zawierał też klucz do symboli żelaznych krasnoludów. Wyryłam je na zworniku, który pomoże ci zrozumieć słowa wyryte na płytach runicznych.$B$BZ wpisów w dzienniku wynika, że Brann może szukać śladów pochodzenia swojego ludu. Miej oczy otwarte na wszelkie wskazówki co do celu jego podróży.$B$BWróć do Thor Modan, na północny wschód stąd, stań przed każdą z płyt i użyj kamienia, by odczytać ich treść. Nie możemy pozwolić, by Przymierze odnalazło go pierwsze.', 'Mędrczyni Paluna w Obozie Oneqwah chce, żebyś $godczytał:odczytała; trzy płyty runiczne.', '', 'Wróć do mędrczyni Paluny w Obozie Oneqwah we Wzgórzach Grizli.', 'Odczytana pierwsza przepowiednia', 'Odczytana druga przepowiednia', 'Odczytana trzecia przepowiednia', '', 0),
(12068, 'koKR', 'Głosy z prochu', '<Drakuru kładzie Oko Proroków na czole, a Serce Pradawnych na piersi.>$b$bJesteśmy blisko, mon, bardzo blisko!$b$bZostały do znalezienia już tylko Tablice Drakkarów. Nikt nie wie, jak są stare ani co mówią, ale z okiem i sercem Drakuru może je odczytać. Leżą głęboko w krypcie w Drakil\'jin, prosto na wschód stąd.$b$bJak już będziesz mieć tablice, zdobądź święte mojo od wyroczni i obrońców, żeby mnie tam przywołać. Będą dumni, że giną za taką sprawę.', 'Drakuru chce, żebyś $gzebrał:zebrała; Tablice Drakkarów w Ruinach Drakil\'jin i 5 świętych mojo od tamtejszych wyroczni i obrońców Drakkarów. Następnie masz użyć Eliksiru Drakuru przy Kadzielnicy Drakuru w ruinach, by przywołać jego wizerunek.', '', 'Wróć do Wizerunku Drakuru w Ruinach Drakil\'jin we Wzgórzach Grizli.', '', '', '', '', 0),
(12070, 'koKR', 'Zebranie wojsk', 'Synowie żelaza użyli swoich run, by zniewolić wielu moich braci, i wykorzystują ich do przełamania oblężenia Thor Modan. Wolałbym nie musieć z nimi walczyć, ale nie mamy wyboru.$B$BMoje olbrzymy nie wytrzymają długo w walce z nimi.$B$BNasyciłem ten ziemny odłamek błogosławieństwem, które wesprze naszych sojuszników. Zabierz go na bitwę na Głazowych Wzgórzach na północy i użyj go, by dodać otuchy i sił moim braciom.$B$BZabij wszystkie żelazne krasnoludy, które staną ci na drodze.', 'Użyj Odłamka ziemi, by dodać ducha olbrzymom ze Wzgórz Grizli walczącym na Głazowych Wzgórzach, zabij wszystkie żelazne krasnoludy, które staną ci na drodze, a następnie zamelduj się u Kuruna na wzgórzu górującym nad Thor Modan.', '', 'Wróć do Kuruna na Głazowych Wzgórzach we Wzgórzach Grizli.', 'Olbrzymy ze Wzgórz Grizli podniesione na duchu', 'Zabici mściciele żelaznych run', '', '', 0),
(12073, 'koKR', 'Kucie żelaza', 'Przymierze to nie jedyna siła, która nam się przeciwstawia we Wzgórzach Grizli. Żelazne krasnoludy mocno trzymają wschodnie wybrzeże, choć Thor Modan, na północnym wschodzie, jest oblegane przez kamienne olbrzymy.$B$BZręczny wojownik obraca słabość wroga przeciwko niemu i bylibyśmy głupcami, gdybyśmy zignorowali słaby punkt żelaznych krasnoludów w Thor Modan. Nie okazuj żelaznym krasnoludom litości. Zabij każdego, kto stanie ci na drodze.$B$B„Synowie żelaza” nauczą się bać Hordy.', 'Zabij 10 dowolnych żelaznych krasnoludów broniących Thor Modan i zamelduj się u zwiadowcy Vor\'takha w Obozie Oneqwah.', '', 'Wróć do zwiadowcy Vor\'takha w Obozie Oneqwah we Wzgórzach Grizli.', 'Zabici krasnoludzcy obrońcy', '', '', '', 0),
(12074, 'koKR', 'Doraźny sojusznik', 'Dawna stolica żelaznych krasnoludów, Thor Modan, daleko na północnym wschodzie, jest oblegana przez tajemniczą bandę kamiennych olbrzymów i ziemnych.$B$BDlaczego twory tytanów walczą ze sobą nawzajem, tego nie pojmuję i nie interesuje to Hordy, ale jest tu okazja, by osłabić wspólnego wroga.$B$BUdaj się do Thor Modan i odszukaj tego „Kuruna”, który dowodzi olbrzymami i ziemnymi. Zawrzyj z nim sojusz i użyj jego sił, by zmiażdżyć żelazne krasnoludy.', 'Porozmawiaj z Kurunem na wzgórzu górującym nad Thor Modan.', '', '', '', '', '', '', 0),
(12081, 'koKR', 'Gavrock', 'Bez twojej pomocy nie zdołalibyśmy odwrócić losów bitwy o Thor Modan. To starożytne miasto od dawna jest polem bitwy między siłami ziemi i kamienia. Mogę tylko mieć nadzieję, że uciszyliśmy je po raz ostatni.$B$BŻelazne krasnoludy wciąż potrafią swoją magią chwytać i zniewalać moich braci. Gavrock szuka sposobu, by uwolnić runiczne olbrzymy. Szukaj go na niewielkim skupisku wysp zwanym Ruinami Tethys, u środkowej części Brzegu Wschodniego Wiatru, na południu.', 'Porozmawiaj z Gavrockiem w Ruinach Tethys.', '', '', '', '', '', '', 0),
(12082, 'koKR', 'Tam-ta-da-dam!', 'Posłuchaj, dzieciaku. To nie jest miejsce do zabawy.$b$bZaraz stąd prysnę. Trzymaj się mnie, to cię stąd wyciągnę.', 'Eskortuj Harrisona z Ruin Drakil\'jin, a potem porozmawiaj z Harkorem w Obozie Harkora.', 'Harrison doprowadził cię w bezpieczne miejsce.', 'Wróć do Harkora w Obozie Harkora we Wzgórzach Grizli.', '', '', '', '', 0),
(12093, 'koKR', 'Runy przymusu', 'Nawet gdy Kurun atakuje Thor Modan, żelazne krasnoludy kierują swoją magię przeciwko naszym braciom. Przyzywają naszych braci z ziemi, a potem wiążą ich runami, i tak synowie żelaza zmuszają ich do walki przeciw dzieciom kamienia.$B$BNa Brzegu Wschodniego Wiatru używają run przymusu, by wysyłać zniewolone olbrzymy na pola bitew na północy.$B$BOdnajdź cztery runy przymusu i zmuś ich nadzorców, by się pojawili, pokonując tkaczy run, którzy obsługują każdą z nich. Bez nadzorców runy są bezużyteczne.', 'Gavrock w Ruinach Tethys chce, żebyś $gunieszkodliwił:unieszkodliwiła; cztery runy przymusu, pokonując nadzorcę Durvala, nadzorcę Korgana, nadzorcę Lochliego i nadzorcę Brunona.', '', 'Wróć do Gavrocka w Ruinach Tethys we Wzgórzach Grizli.', '', '', '', '', 0),
(12094, 'koKR', 'Uśpiona moc', 'Dopóki runy przymusu są uśpione, mamy szansę uwolnić runiczne olbrzymy.$B$BDam ci kawałek kamienia, który jest częścią mnie od chwili mojego stworzenia. Właściwie nasycony może posłużyć do uwolnienia spętanych olbrzymów.$B$BDwa pradawne kamienne znaczniki stoją w miejscach mocy między Żelaznym Szlakiem a skrajem lasu – w miejscach, które twój lud nazwałby skrzyżowaniami linii mocy. Trzeci jest na wyspie na południowym krańcu tych ruin. Naładuj odłamek przy każdym kamieniu i wróć.', 'Naładuj Odłamek Gavrocka przy pierwszym, drugim i trzecim pradawnym kamieniu, a następnie wróć do Gavrocka w Ruinach Tethys.', '', 'Wróć do Gavrocka w Ruinach Tethys we Wzgórzach Grizli.', 'Moc pobrana z pierwszego pradawnego kamienia', 'Moc pobrana z drugiego pradawnego kamienia', 'Moc pobrana z trzeciego pradawnego kamienia', '', 0),
(12099, 'koKR', '', 'Nasycony przez ciebie odłamek skały powinien mieć dość mocy, by złamać runiczną magię, która spętała moich braci.$B$BZabierz go i odszukaj runiczne olbrzymy, które idą na północ wzdłuż Brzegu Wschodniego Wiatru. Uwolnij moc zgromadzoną w kamieniu i obserwuj, co się stanie.$B$BJeśli się uda, runiczne olbrzymy powinny odzyskać zmysły i przestać słuchać żelaznych krasnoludów. Jeśli kamień zawiedzie, olbrzymy mogą zaatakować osłabione. Ale czy mamy wybór? Jeśli nie spróbujemy, pozostaną zniewolone bez nadziei.', 'Użyj Łamacza run Gavrocka, by uwolnić 4 runiczne olbrzymy, a następnie wróć do Gavrocka w Ruinach Tethys.', '', 'Wróć do Gavrocka w Ruinach Tethys we Wzgórzach Grizli.', 'Uwolnione runiczne olbrzymy', '', '', '', 0),
(12105, 'koKR', 'Zejście w ciemność', 'Dziennik napisał mieszkaniec Srebrnego Potoku imieniem Mikhail. Opisuje w nim przybycie czczącej cień grupy zwanej „Kultem Wilka”.$B$BMieszkańcy wioski początkowo niechętnie przyjmowali kult, ale z czasem wśród mieszkańców miasteczka pojawiało się coraz więcej sympatyków.$B$BZaniepokojony tym Mikhail odesłał córkę Sashę ze Srebrnego Potoku, a sam próbował przemówić do rozsądku pozostałym mieszkańcom.$B$BOstatni wpis Mikhaila wspomina o spotkaniu starszyzny miasteczka, na którym miano omówić bliżej nieokreślone wydarzenia w Kopalni Wydrążonego Kamienia.', 'Zanieś Dziennik Mikhaila porucznikowi Dumontowi w Chacie Bursztynowej Sosny.', '', 'Porozmawiaj z porucznikiem Dumontem w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12109, 'koKR', 'Zamelduj się u Gryana Mocnopłaszcza... znowu', 'Chłopaków z Zachodniego Skraju wysłano na wschód, żeby szukali drogi na ziemie północne. Ich drugorzędnym zadaniem jest zabezpieczanie strategicznych złóż, więc na pewno nie będą mieli nic przeciwko zbadaniu kopalni.$B$BSzukaj obozowiska Brygady Zachodniego Skraju daleko na północnym wschodzie i odszukaj Gryana Mocnopłaszcza. Może go pamiętasz, jeśli $gspędziłeś:spędziłaś; kiedyś trochę czasu w Zachodnim Skraju. Koniecznie powiedz mu, że to ja cię przysłałem.$B$BZ radością pozwoli ci zająć działającą kopalnię dla króla.', 'Porozmawiaj z kapitanem Gryanem Mocnopłaszczem w Obozowisku Brygady Zachodniego Skraju.', '', '', '', '', '', '', 0),
(12113, 'koKR', 'Mięsne powitanie', 'Dzień dobry, $N! Siadaj przy moim ognisku, co?$b$bPoczęstowałbym cię gorącym posiłkiem, tylko że żadnego nie mam. Utknąłem tu, czekając na wspólnika, bo inaczej sam bym poszedł zaradzić tej sytuacji.$b$bSłuchaj, wyglądasz, jakbyś $gmiał:miała; mnóstwo wolnego czasu, a w okolicy jest pełno mięsa. Może pomożesz i nazbierasz trochę żarcia?', 'Harkor w Obozie Harkora chce, żebyś $gzebrał:zebrała; 10 kawałków żylastego mięsa worga od drapieżców Wycia o Zmroku i 10 steków z łopatoroga od długokopytych trawożerców.', '', 'Wróć do Harkora w Obozie Harkora we Wzgórzach Grizli.', '', '', '', '', 0),
(12114, 'koKR', 'Terapia', 'Trolle... nienawidzę ich wszystkich! <Harkor spluwa.>$b$bRaz dałem się złapać bandzie tych bestii... o włos, a pomniejszyliby mi głowę!$b$bKumple mówią, żebym dał sobie spokój i zostawił to za sobą, ale coś mi to nie pasuje.$b$bChcesz wiedzieć, co by mi poprawiło humor? Widok stosu ich trupów tak wysokiego, że przesłoni słońce! Mam dobre złoto do wydania, jeśli zdołasz to załatwić.', 'Harkor w Obozie Harkora chce, żebyś $gzabił:zabiła; 10 obrońców Drakkarów i 10 wyroczni Drakkarów przed Ruinami Drakil\'jin.', '', 'Wróć do Harkora w Obozie Harkora we Wzgórzach Grizli.', '', '', '', '', 0),
(12116, 'koKR', 'Trzeba mieć flaki...', 'Witaj, $N. To miło z twojej strony, że $gzatrzymałeś:zatrzymałaś; się, by wysłuchać opowieści Kraza.$b$bOd wielu lat Kraz wytęża słuch, by usłyszeć duchy i spełniać ich wolę.$b$bOstatnio z tych ruin woła do Kraza wiele głosów. Szukają spokoju, którego same nie mogą znaleźć.$b$bJeśli chcesz pomóc duchom tych, którzy byli tu przed nami, wejdź do tej krypty i zbierz coś, co niegdyś należało do tych udręczonych dusz.', 'Kraz w Obozie Harkora chce, żebyś $gwszedł:weszła; do Ruin Drakil\'jin i $gzebrał:zebrała; 5 urn kanopskich Drakkarów.', '', 'Wróć do Kraza w Obozie Harkora we Wzgórzach Grizli.', '', '', '', '', 0),
(12120, 'koKR', 'Pałka Drak\'aguula', 'Splugawienie...$b$bKraz wyczuwał je, zanim jeszcze $gprzyniosłeś:przyniosłaś; te urny. To splugawienie napełnia pradawne duchy Drakkarów wielką udręką i nie pozwala im zaznać spoczynku, którego szukają.$b$bKraz nie będzie kłamał, $N. Oczyszczenie tego miejsca będzie wymagało wielkiej ofiary, ale o tym pomówimy innym razem.$b$bJest tu wśród żywych ktoś, kto ma klucz do oczyszczenia. Odszukaj Drak\'aguula i wróć do Kraza z pałką, którą nosi.', 'Kraz w Obozie Harkora chce, żebyś $gzabił:zabiła; Drak\'aguula przed Ruinami Drakil\'jin i $gwrócił:wróciła; z Pałką z Drakil\'jin.', '', 'Wróć do Kraza w Obozie Harkora we Wzgórzach Grizli.', '', '', '', '', 0),
(12121, 'koKR', 'Do zobaczenia po drugiej stronie', 'Ci Drakkarowie przyjęli cię wyłącznie dziką wrogością. Nic im nie jesteś $gwinny:winna;. Doprawdy niewielu podjęłoby się zadania, o które Kraz prosi cię dzisiaj.$b$bBy oczyścić to miejsce i posłać duchy na wieczny spoczynek, musisz dołączyć do nich w śmierci.$b$bW krypcie czeka na ciebie ktoś – po drugiej stronie. Ma wiedzę, której szukamy, $n.$b$bUżyj pałki na gongach. Duch tego, który plugawi to miejsce, z pewnością odeśle cię do świata duchów.$b$bKraz czeka na twój powrót.', 'Kraz w Obozie Harkora chce, żebyś $gużył:użyła; Pałki z Drakil\'jin na gongach przed Ruinami Drakil\'jin. Gdy zginiesz, masz wejść do ruin i jako duch porozmawiać z duchem Gan\'jo.', '', 'Porozmawiaj z Gan\'jo w Ruinach Drakil\'jin we Wzgórzach Grizli.', 'Śmierć z ręki wodza Jin\'arraka', '', '', '', 0),
(12128, 'koKR', 'Sprawdź, co u Raegara', 'Przy całym tym zamieszaniu z armią, która próbuje przejść przez Thor Modan, prawie zapomniałem o ekipie Raegara w Punkcie Poszukiwacza.$B$BWysłałem Raegara i jego asystentów, razem z przyjacielem, górskim strażnikiem, żeby założyli niewielki posterunek w pobliżu Dun Argol, na południowym krańcu Brzegu Wschodniego Wiatru.$B$BMieli zbadać obecność żelaznych krasnoludów na południowych wzgórzach, ale nie dostałem jeszcze żadnych raportów. Możesz sprawdzić, co u nich, jeśli będziesz tamtędy przechodzić?', 'Porozmawiaj z Raegarem Łamibrwią w Punkcie Poszukiwacza.', '', '', '', '', '', '', 0),
(12129, 'koKR', 'Doskonały plan', 'Żelazne krasnoludy nie kryją się z tym, że szykują się do wojny. Z olbrzymami, golemami i żywiołakami błyskawic miałyby przewagę technologiczną nad Brygadą Zachodniego Skraju. Jeśli brygada nie znajdzie na czas przejścia na północ, żelaźni mogą ją zaskoczyć.$B$BMusimy ich tu związać walką, a ja wiem, jak to zrobić. W Dun Argol roi się od kowali run, którzy taśmowo produkują golemy bojowe. Noszą plany poszczególnych części, więc musisz je znaleźć i złożyć wszystkie w całość.', 'Przynieś uzupełniony Plan golema bojowego Raegarowi Łamibrwi w Punkcie Poszukiwacza.', '', 'Wróć do Raegara Łamibrwi w Punkcie Poszukiwacza we Wzgórzach Grizli.', '', '', '', '', 0),
(12130, 'koKR', 'Po co wytwarzać, skoro można przywłaszczyć?', 'Mamy plany, ale bez części nic z nimi nie zrobimy! Nie mamy dostępu do odlewni, a co dopiero do materiałów, ale w Dun Argol jest cała masa części.$B$BTwoje zadanie?$B$BZnaleźć im nowy dom.$B$BPewnie są porozrzucane po budynkach, w których pracują żelaźni kowale run, i nie zdziwię się, jeśli żelaźni się wściekną, gdy spróbujesz podwędzić ich wyroby. Im więcej części przyniesiesz, tym lepszego golema zbudujemy.', 'Przynieś 8 części golema bojowego Raegarowi Łamibrwi w Punkcie Poszukiwacza.', '', 'Wróć do Raegara Łamibrwi w Punkcie Poszukiwacza we Wzgórzach Grizli.', '', '', '', '', 0),
(12131, 'koKR', 'Mamy moc', 'Już prawie, ale golem bojowy nie ruszy bez ogniw zasilających. Z informacji, które zdołałem zebrać w Dun Argol, zanim nas wykryto, wynika, że kowal run Durar i kowal run Kathorn wytwarzają po jednym ogniwie.$B$BPotrzebujemy po jednym ogniwie od każdego z kowali run, żeby nasz golem zadziałał.$B$BKażdego z kowali run znajdziesz w jego warsztacie na środkowym poziomie Dun Argol.', 'Przynieś Ogniwo zasilające Durara i Ogniwo zasilające Kathorna Raegarowi Łamibrwi w Punkcie Poszukiwacza.', '', 'Wróć do Raegara Łamibrwi w Punkcie Poszukiwacza we Wzgórzach Grizli.', '', '', '', '', 0),
(12134, 'koKR', 'Łowy Sashy', 'To coś... ta klątwa... która dotknęła Srebrny Potok i Wioskę Przesilenia... zamienia ludzi w bestie.$B$BMój ojciec próbował ich ostrzec, ale wszyscy woleli słuchać Kultu Wilka.$B$BZaszli już za daleko, czas ich dobić... dla ich własnego dobra.', 'Sasha chce, żebyś $gzabił:zabiła; 12 łowców z Wioski Przesilenia.', '', 'Wróć do Sashy w Faktorii Białej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12137, 'koKR', 'Wyluzuj, mon', 'Jest tak, jak mówiły przepowiednie, mon. Przyjdzie ktoś taki jak ty i da naszym duchom spokój. Długo już czekaliśmy!$b$bDrakkarowie stali się zagubionym ludem, dzikim i okrutnym.$b$bAle my cierpimy tu nie z własnej winy, mon. To miejsce trzeba oczyścić i tylko żywi mogą to zrobić.$b$bPomów ze mną, kiedy będziesz $ggotów:gotowa; wrócić do swojego ciała. Potem weź śnieg ze skrzyni tu obok mnie i uśpij moich braci.$b$bZanieś ich szczątki swojemu duchowemu przewodnikowi. On będzie wiedział, co dalej.', 'Gan\'jo chce, żebyś $gwyjął:wyjęła; Śnieg wiecznego snu z jego skrzyni w Ruinach Drakil\'jin.$b$bMasz użyć śniegu na pradawnych duchach Drakkarów i zanieść ich Cząstki duchów Drakkarów Krazowi w Obozie Harkora.', '', 'Wróć do Kraza w Obozie Harkora we Wzgórzach Grizli.', '', '', '', '', 0),
(12138, 'koKR', '...A może jednak nie', 'Można by pomyśleć, że ci, co robią ogniwa, pomyślą o ich naładowaniu, ale nie, muszą nam wszystko utrudniać.$B$BDobra, naładujemy te ogniwa w trudniejszy sposób. Jest w nich dość mocy, żeby golem przez chwilę działał, ale nie licz na to, że na wiele się przyda w walce.$B$BWidzisz wartowników błyskawic, których żelaźni rozstawili wokół Dun Argol? Weź golema ze sobą, podprowadź go blisko nich i użyj go, by wchłaniał moc, gdy wartownicy giną.', 'Naładuj swojego golema bojowego energią z 10 wartowników błyskawic i wróć do Raegara Łamibrwi w Punkcie Poszukiwacza.', '', 'Wróć do Raegara Łamibrwi w Punkcie Poszukiwacza we Wzgórzach Grizli.', 'Poziom naładowania', '', '', '', 0),
(12152, 'koKR', 'Koniec Jin\'arraka', 'Dobrze znów widzieć cię wśród żywych. Wielu z tych, którzy wędrują ścieżką umarłych, nie wraca, by o tym opowiedzieć.$b$bGdy cię nie było, Krazowi objawiła się wizja, która pokazała, co jeszcze pozostało do zrobienia.$b$bGdzieś w krypcie leży święta ofiara. Weź ten pył duchów, sporządzony ze szczątków, które $gzebrałeś:zebrałaś;, i użyj go na ofierze.$b$bNasycona ofiara położy kres splugawionemu wodzowi i uwolni wiele udręczonych dusz.$b$bNiech duchy prowadzą twoje czyny, $n.', 'Kraz w Obozie Harkora chce, żebyś $gzabrał:zabrała; Świętą ofiarę Drakkarów z Ruin Drakil\'jin i $gużył:użyła; na niej Pyłu duchów Drakkarów. Nasyconej ofiary Drakkarów musisz użyć przy gongach przed Ruinami Drakil\'jin.', '', 'Wróć do Kraza w Obozie Harkora we Wzgórzach Grizli.', 'Zniszczony wódz Jin\'arrak', '', '', '', 0),
(12153, 'koKR', 'Żelazny than i jego Kowadło', 'Skoro już $gnaładowałeś:naładowałaś; golema bojowego, dobrze wykorzystamy całą tę energię. Aktywuj golema w Dun Argol, żeby przejąć nad nim kontrolę.$B$BZ naszych informacji o przywódcy Dun Argol, żelaznym thanie Furiomłocie, wynika, że jego ochroniarz chroni go przed wszelką krzywdą.$B$BTym ochroniarzem jest konstrukt, z którym than podróżuje, zwany Kowadłem. Unieszkodliw konstrukt, a ochrona zniknie.$B$BThan przebywa w budynku na szczycie Dun Argol i nadzoruje produkcję z najniższego poziomu.', 'Wykorzystując zdolności swojego golema bojowego, pokonaj żelaznego thana Furiomłota, a następnie wróć do Raegara Łamibrwi w Punkcie Poszukiwacza.', '', 'Wróć do Raegara Łamibrwi w Punkcie Poszukiwacza we Wzgórzach Grizli.', '', '', '', '', 0),
(12154, 'koKR', 'Zaciemnienie', 'W wielkiej sali na szczycie Dun Argol mieści się źródło mocy dla całej okolicy. Jeśli zniszczysz rdzeń mocy, sparaliżujesz Dun Argol na jakiś czas.$B$BBrak mocy oznacza brak golemów, brak wartowników i koniec z uzbrojeniem na błyskawice.$B$BGdy nas tu wysłano, powiedziano nam, że te materiały wybuchowe są do wykopalisk, ale dzięki żelaznemu thanowi Furiomłotowi z badań nici. Równie dobrze możemy je jakoś wykorzystać. To jedyna rzecz, jaką mamy pod ręką, zdolna zniszczyć rdzeń mocy.', 'Użyj Materiałów wybuchowych Raegara, by zniszczyć runiczny rdzeń mocy w Dun Argol, a następnie zamelduj się u Raegara Łamibrwi w Punkcie Poszukiwacza.', '', 'Wróć do Raegara Łamibrwi w Punkcie Poszukiwacza we Wzgórzach Grizli.', 'Zniszczony rdzeń mocy Dun Argol', '', '', '', 0),
(12158, 'koKR', 'Kopalnia Wydrążonego Kamienia', 'Od dawna zamierzam wysłać paru naszych chłopaków, żeby sprawdzili Kopalnię Wydrążonego Kamienia. Nie było jeszcze okazji – mamy pełne ręce roboty z Hordą na zachodzie i żelaznymi krasnoludami na wschodzie.$B$BSkoro jednak przysłał cię Dumont, mogę przynajmniej wskazać ci drogę.$B$BWejście do kopalni znajdziesz na północnym zachodzie, niedaleko stąd. Oceń, czy da się tam jeszcze uratować wydobycie. Przydałyby się nam dodatkowe surowce, dopóki nasza kopalnia w Dalekich Włościach znów nie ruszy.', 'Poszukaj wskazówek w Kopalni Wydrążonego Kamienia na północny zachód od Obozowiska Brygady Zachodniego Skraju.', '', '', '', '', '', '', 0),
(12159, 'koKR', 'Niespokojne dusze', '<Petrov wygląda na głęboko wstrząśniętego, oddycha ciężko i nerwowo wodzi wzrokiem po kopalni.>$B$BMoi towarzysze... musimy dać spokój ich duszom! Zabijam ich i zabijam, ale... oni wciąż wracają!$B$BOd jakiegoś czasu mam pewien pomysł, ale nie mam serca, żeby zrobić to sam.$B$BMoże ty to dla mnie zrobisz? Weź tę lampę i spal jej olejem ich szczątki, żeby już nigdy nie wstali.$B$BNa twoje pytania odpowiem później. Najpierw pomóż moim przyjaciołom!', 'Petrov w Kopalni Wydrążonego Kamienia chce, żebyś $gużył:użyła; lampy górniczej, by spalić zwłoki 8 górników z Kopalni Wydrążonego Kamienia.', '', 'Wróć do Petrova w Kopalni Wydrążonego Kamienia we Wzgórzach Grizli.', 'Górnik zaznał spokoju', '', '', '', 0),
(12160, 'koKR', 'Imię z przeszłości', 'Udało się! Udało się! Moi towarzysze mogą wreszcie zaznać zasłużonego odpoczynku...$B$BZostanę tu i dokończę robotę. My, górnicy z Wydrążonego Kamienia, zawsze kończymy robotę – nigdy się nie poddajemy!$B$BDlatego Arugal zrobił z nas przykład. Nie chcieliśmy się podporządkować, rozumiesz? Nie chcieliśmy przyłączyć się do jego Kultu Wilka!', 'Wróć do kapitana Gryana Mocnopłaszcza w Obozowisku Brygady Zachodniego Skraju.', '', '', '', '', '', '', 0),
(12161, 'koKR', 'Ruuna Ślepa', 'Hej. Słyszałem, co mówisz kapitanowi, i chcę, żebyś $gwiedział:wiedziała;... w Północnej Grani sprawy nie są takie proste.$B$BTo, że ktoś nie żyje, nie znaczy, że zniknął ze sceny.$B$BNa południowy zachód stąd, niedaleko Przełęczy Vordrassila, mieszka niewidoma kobieta, którą nazywają Ruuną Ślepą. Podobno rozmawia z umarłymi i ma wizje przeszłości i przyszłości.$B$BNie znam całej twojej historii, ale wygląda na to, że to coś akurat dla ciebie.', 'Porozmawiaj z Ruuną Ślepą w Obozie Ruuny niedaleko Przełęczy Vordrassila.', '', '', '', '', '', '', 0),
(12162, 'koKR', 'Wioska Przesilenia', '', '', '', '', '', '', '', '', 0),
(12163, 'koKR', 'Zło w głębinach', '', '', '', '', '', '', '', '', 0),
(12164, 'koKR', 'Godzina worga', 'Więc nadszedł czas, $N. Arugal musi zostać pokonany.$B$BWeź paru ludzi, którym ufasz, i ruszajcie na Wyspę Krwawego Księżyca. Leży tuż przy wybrzeżu, na wschód stąd.$B$BUderzymy szybko. Zlikwiduj poruczników Arugala – dołączę do ciebie, gdy przyjdzie czas rozprawić się z samym potworem.', 'Sasha w Faktorii Białej Sosny chce, żebyś $gudał:udała; się na Wyspę Krwawego Księżyca i $gzabił:zabiła; Selasa, Varlama, Krwawopaszcza i Cień Arugala.', '', 'Wróć do Sashy w Faktorii Białej Sosny we Wzgórzach Grizli.', '', '', '', 'Pokonany Cień Arugala', 0),
(12165, 'koKR', 'Intrygujący plan', 'Poszukiwacz Rokar postanowił nam pomóc. Obmyślił plan, jak obrócić siłę żelaznych krasnoludów przeciwko nim samym.$B$BMuszę przyznać, że nasz nowy „przyjaciel” jest bardziej przenikliwy, niż sądziłem. Ma rację, że jest nas za mało na bezpośredni atak.$B$BUdaj się do Dun Argol, w zaśnieżonych rejonach na południowym wschodzie, i zdobądź od tamtejszych żelaznych kowali run wszystkie części planów ich golema bojowego. Zanieś złożony plan Rokarowi, a zobaczymy, czy jego pomysł jest coś wart.', 'Przynieś uzupełniony Plan golema bojowego poszukiwaczowi Rokarowi w Obozie Oneqwah.', '', 'Wróć do poszukiwacza Rokara w Obozie Oneqwah we Wzgórzach Grizli.', '', '', '', '', 0),
(12170, 'koKR', 'Bijatyka nad Czarną Rzeką', 'Spółka Gitgeszeft porzuciła prace wkrótce po naszym przybyciu. Najwyraźniej bali się, co zrobimy z ich chciwymi skórami.$B$BSkoro ich nie ma, ich obozy drwali są do wzięcia. Nasza machina wojenna to głodna bestia... bez uzupełniania zapasów nie dotrzemy do Lodowej Korony.$B$BNiestety Przymierze chyba wpadło na ten sam pomysł, a my musimy dopilnować, żeby to nasza strona wygrała. Idź do obozu drwali i pomóż nam walczyć z tym ścierwem z Przymierza.', 'Kapitan grabieżców Kronn chce, żebyś $gzabił:zabiła; 10 żołnierzy lub graczy Przymierza w Obozie Drwali Czarnej Rzeki.', '', 'Wróć do kapitana grabieżców Kronna we Wzgórzach Grizli.', 'Zabici członkowie Przymierza nad Czarną Rzeką', '', '', '', 0),
(12175, 'koKR', 'Skóry szarych worgów', 'Coś ci powiem, mon. Jak dostajesz zadanie wyposażenia armii Hordy, to zużywasz masę skór!$B$BZdobywczyni Krenna, ta wilczyca, co tu rządzi, dała mi krótki termin. Jak do końca tygodnia nie wyposażę całego jej pułku, każe mi siłować się z niedźwiedziami na arenie.$B$BPomóż mi, a zapłacę ci najlepszą cenę. Będę potrzebował skór szaromglistych łowców.$B$BZnajdziesz ich w grupkach na północy, polują na jelenie. Pamiętaj, mon. Najlepsza cena!', 'Handlarz skór Jun\'ik w Warowni Podboju chce, żebyś $gzdobył:zdobyła; 3 skóry szarego worga od szaromglistych łowców w lasach na północy.', '', 'Wróć do handlarza skór Jun\'ika w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12176, 'koKR', 'Drobna podmiana', 'Krenna chce skór worgów na wszystkie stroje. Ale dla jej armii skór worgów nie starczy. Ani teraz, ani nigdy.$B$BTe worgi – one chude, mon! Zrobimy tak... jeśli umiesz dochować tajemnicy.$B$BNa wschód od Voldrune są niedźwiedzie grizli tłuste jak ogr. Te wielkie skóry – te się nadadzą!$B$BPośpiesz się, $gbracie:siostro;. Krenna nie słynie z cierpliwości.', 'Handlarz skór Jun\'ik chce, żebyś $gprzyniósł:przyniosła; mu 6 skór grizli.', '', 'Wróć do handlarza skór Jun\'ika w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12177, 'koKR', 'Tuszowanie Jun\'ika', 'Ach, mamy mały problem. Skóry grizli... one brązowe, mon!$B$BMyśl... myśl!$B$BMam, mon! To tak: szary to czarny i biały, wszystko razem wymieszane. Przynieś mi trochę węgla i trochę mąki, zmielę to wszystko i posypię tym skóry. Nikt się nie połapie!$B$BKowale sprzedają węgiel do wytapiania, a mąkę dostaniesz u zaopatrzeniowca.', 'Przynieś 1 kawałek węgla i 5 porcji zwykłej mąki handlarzowi skór Jun\'ikowi w Warowni Podboju we Wzgórzach Grizli.', '', 'Wróć do handlarza skór Jun\'ika w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12178, 'koKR', 'Dostawa dla Krenny', 'No to jest, mon. Zanieśmy te skóry Krennie i zobaczmy, czy przejdą próbę.$B$BMiejmy nadzieję, dla dobra nas obu, że Krenna niczego nie zauważy.', 'Zanieś Wiązkę skór Krennie w Warowni Podboju.', '', 'Wróć do zdobywczyni Krenny w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12180, 'koKR', 'Uwięzieni poszukiwacze', 'Raegar wysłał do Dun Argol zespół poszukiwaczy, żeby szukali artefaktów i informacji o historii osady. Zespół Raegara nigdy by się nie spodziewał, że w Dun Argol będzie aż tylu mieszkańców.$B$BSą przetrzymywani w niewoli, podczas gdy żelazne krasnoludy szykują się do wojny. Nie mamy ludzi, by po nich ruszyć, a Raegar jest zbyt zajęty marzeniami o pokonaniu żelaznych, by się na coś przydać.$B$BTo zadanie spada na ciebie, $N. Klucze do klatek, w których trzymają naszych ludzi, może mieć przy sobie każdy z żelaznych albo ich sług.', 'Uwolnij poszukiwacza Ganna, poszukiwacza Torgana i poszukiwaczkę Varanę, a następnie wróć do górskiego strażnika Kiliana w Punkcie Poszukiwacza.', '', 'Wróć do górskiego strażnika Kiliana w Punkcie Poszukiwacza we Wzgórzach Grizli.', 'Uratowany poszukiwacz Gann', 'Uratowany poszukiwacz Torgan', 'Uratowana poszukiwaczka Varana', '', 0),
(12183, 'koKR', 'Odpowiedni wygląd', 'Jeśli, jak mówiła poszukiwaczka Varana, tylko niektórzy żelaźni mogą porozumiewać się z tym Lokenem, to ten przywilej mają pewnie nadzorcy.$B$BMusimy cię tam wprowadzić, żeby sprawdzić, o co w tym wszystkim chodzi, ale łatwo nie będzie. Pierwszym krokiem będzie zdobycie dla ciebie odpowiedniego munduru.$B$BPotem zajmiemy się twoją charakteryzacją.$B$BZnajdź w Dun Argol któregoś z nadzorców, zabij go i przynieś jego mundur. Jak go zakrwawisz, to będzie tylko twoja wina.', 'Przynieś Mundur nadzorcy górskiemu strażnikowi Kilianowi w Punkcie Poszukiwacza.', '', 'Wróć do górskiego strażnika Kiliana w Punkcie Poszukiwacza we Wzgórzach Grizli.', '', '', '', '', 0),
(12184, 'koKR', 'Kształtowanie wizerunku', 'Skoro mamy już mundur, musimy zebrać dość informacji, żeby dokończyć twoje przebranie.$B$BRaegar przywiózł ten aparat, żeby dokumentować znaleziska zespołu, ale ja mam dla niego inne zastosowanie. Chcę, żebyś $gzabrał:zabrała; go do Dun Argol i $gzrobił:zrobiła; nim zdjęcia żelaznych krasnoludów.$B$BRzecz jasna twoi modele nie będą zbyt skłonni do współpracy, więc być może będziesz $gmusiał:musiała;, ehm... najpierw ich obezwładnić. Gdy skończysz, przynieś aparat i zdjęcia.', 'Użyj Aparatu Kiliana, by zrobić zdjęcia 8 żelaznym krasnoludom w Dun Argol, a następnie wróć do górskiego strażnika Kiliana w Punkcie Poszukiwacza.', '', 'Wróć do górskiego strażnika Kiliana w Punkcie Poszukiwacza we Wzgórzach Grizli.', 'Zdjęcia żelaznych krasnoludów', '', '', '', 0),
(12185, 'koKR', 'Pokaż Lokenowi swoje najlepsze oblicze', 'Na podstawie zrobionych przez ciebie zdjęć przygotowałem wszystko, czego potrzebujesz do zestawu przebrania nadzorcy. Będzie z ciebie świetny żelazny krasnolud, choć to ja tak mówię.$B$BZabierz zestaw do Dun Argol, przebierz się za jego pomocą, a potem idź do najbardziej wysuniętego na wschód budynku na szerokim środkowym poziomie miasta.$B$BPowinien tam stać piedestał, przy którym than i nadzorcy otrzymują rozkazy od tego Lokena. Uruchom go w przebraniu i dowiedz się z tej wiadomości wszystkiego, co się da.', 'Przebierz się za nadzorcę żelaznych run, przechwyć wiadomość od Lokena, a następnie zamelduj się u górskiego strażnika Kiliana w Punkcie Poszukiwacza.', '', 'Wróć do górskiego strażnika Kiliana w Punkcie Poszukiwacza we Wzgórzach Grizli.', 'Odebrana wiadomość od Lokena', '', '', '', 0),
(12190, 'koKR', 'Przywitaj się z moim małym przyjacielem', 'Harkor padnie z wrażenia, jak zobaczy te wyborne składniki. Zostało tylko mu je dostarczyć.$b$bObozuje na wschodnim wybrzeżu koło tych nawiedzonych ruin – Drakil\'jin się nazywają.$b$bPewnie dotrzesz tam, zanim skończę z tymi zwłokami... chyba że wolisz spróbować sił w balsamowaniu?', 'Prigmon chce, żebyś $gzaniósł:zaniosła; Składniki Harkora Harkorowi w Obozie Harkora.', '', 'Odszukaj Harkora w Obozie Harkora we Wzgórzach Grizli.', '', '', '', '', 0),
(12195, 'koKR', 'Niespodziewany „gość”', 'Niedawna wyprawa myśliwska przyniosła nie tylko zwierzynę.$B$BMyśliwi natknęli się na rannego krasnoluda, który uciekał z twierdzy żelaznych krasnoludów, Dun Argol. Może mieć informacje, które przydadzą się nam do uderzenia na naszego odwiecznego wroga, ale zanim na coś się nam przyda, musimy zbić mu gorączkę.$B$BPoroża srebrnosierstnych jeleni, które przemierzają pobliski las, od dawna służą do sporządzania leczniczych okładów. Jeśli przyniesiesz mi dość poroży, zobaczymy, czy okład postawi naszego „gościa” na nogi.', 'Przynieś 5 poroży dorosłych jeleni Tormakowi Pokiereszowanemu w Obozie Oneqwah.', '', 'Wróć do Tormaka Pokiereszowanego w Obozie Oneqwah we Wzgórzach Grizli.', '', '', '', '', 0),
(12196, 'koKR', 'Od podstaw', 'Nie mamy dość czasu, żebym sam wykuł części, ale odlewnie w Dun Argol, na południowym wschodzie, pracują dzień i noc, produkując części golemów.$B$BMyślę, że $gpowinieneś:powinnaś; tam wrócić i zebrać ich tyle, żebym mógł zbudować golema według tego planu.$B$BPewnie są porozrzucane po budynkach, w których pracują żelaźni kowale run.$B$BProszę, pośpiesz się, $N. Ten Tormak wygląda, jakby tylko czekał na pretekst, żeby spełnić swoją groźbę!', 'Przynieś 8 części golema bojowego poszukiwaczowi Rokarowi w Obozie Oneqwah.', '', 'Wróć do poszukiwacza Rokara w Obozie Oneqwah we Wzgórzach Grizli.', '', '', '', '', 0),
(12197, 'koKR', 'Mamy moc', 'No, mamy skorupę golema, ale to Tormakowi nie wystarczy. Nie rozumie, że te rzeczy nie składają się same i nie zaczynają cudownie działać! Potrzebujemy ogniw zasilających, żeby go ożywić.$B$BKiedy byłem w Dun Argol, zauważyłem, że ogniwa wytwarzają kowal run Durar i kowal run Kathorn. Potrzebujemy po jednym od każdego, żeby zasilić naszego golema.$B$BKażdego z kowali run znajdziesz w jego warsztacie na środkowym poziomie Dun Argol.', 'Przynieś Ogniwo zasilające Durara i Ogniwo zasilające Kathorna poszukiwaczowi Rokarowi w Obozie Oneqwah.', '', 'Wróć do poszukiwacza Rokara w Obozie Oneqwah we Wzgórzach Grizli.', '', '', '', '', 0),
(12198, 'koKR', '...A może jednak nie', 'Ogniwa golema mają akurat tyle mocy, żeby działał na najniższych obrotach, ale nie zasilą żadnego z jego systemów bojowych.$B$BDobra wiadomość jest taka, że wokół Dun Argol patrolują wartownicy błyskawic. Powinniśmy móc wykorzystać ich moc do naładowania systemów uzbrojenia golema.$B$BWeź golema ze sobą i podprowadź go blisko nich – wchłonie moc, gdy wartownicy będą ginąć.', 'Naładuj swojego golema bojowego energią z 10 wartowników błyskawic i wróć do poszukiwacza Rokara w Obozie Oneqwah.', '', 'Wróć do poszukiwacza Rokara w Obozie Oneqwah we Wzgórzach Grizli.', 'Poziom naładowania', '', '', '', 0),
(12199, 'koKR', 'Obalenie żelaznego thana', 'Skoro golem jest w pełni naładowany, można go użyć przeciwko przywódcy Dun Argol.$B$BGdy obserwowałem żelaznego thana Furiomłota, zawsze strzegł go osobisty golem, który osłaniał go przed wszelką krzywdą.$B$BTen konstrukt, zwany Kowadłem, można zakłócić, przez co than straci osłonę. Użyj do tego zdolności EMP swojego golema. Golema aktywujesz i przejmiesz nad nim kontrolę w Dun Argol.$B$BThan przebywa w głównym zakładzie na szczycie i nadzoruje produkcję z najniższego poziomu.', 'Wykorzystując zdolności swojego golema bojowego, pokonaj żelaznego thana Furiomłota, a następnie wróć do Tormaka Pokiereszowanego w Obozie Oneqwah.', '', 'Wróć do Tormaka Pokiereszowanego w Obozie Oneqwah we Wzgórzach Grizli.', '', '', '', '', 0),
(12201, 'koKR', 'Cień nadzorcy', 'Wygląda na to, że to ten Loken stoi za nagłymi przygotowaniami żelaznych krasnoludów do wojny.$B$BDostęp do niego mają pewnie tylko najwyżsi rangą żelaźni, więc będziemy musieli zrobić z ciebie nadzorcę, żeby się dowiedzieć, co się tam dzieje.$B$BMam na to plan, ale potrzebujemy trochę zaopatrzenia.$B$BZnajdź któregoś z nadzorców żelaznych run w Dun Argol, na południowym wschodzie, zabij go i przynieś jego mundur.', 'Przynieś Mundur nadzorcy zwiadowcy Vor\'takhowi w Obozie Oneqwah.', '', 'Wróć do zwiadowcy Vor\'takha w Obozie Oneqwah we Wzgórzach Grizli.', '', '', '', '', 0),
(12202, 'koKR', 'Kształtowanie wizerunku', 'Teraz musimy dokończyć dzieła i uczynić cię tak $godrażającym:odrażającą; jak te żelazne krasnoludy.$B$BNajlepiej będzie oprzeć twoje przebranie na paskudnych gębach prawdziwych żelaznych krasnoludów.$B$BGdy myśliwi Tormaka znaleźli tego zbłąkanego poszukiwacza, zabrali mu aparat, który miał przy sobie. Teraz, jak sądzę, będziemy mieli okazję go użyć.$B$BZabierz go do Dun Argol, zabij kilka żelaznych krasnoludów i utrwal ich podobizny tym urządzeniem. Przynieś go z powrotem, gdy zbierzesz dość przykładów.', 'Użyj Aparatu Rokara, by zrobić zdjęcia 8 żelaznym krasnoludom w Dun Argol, a następnie wróć do zwiadowcy Vor\'takha w Obozie Oneqwah.', '', 'Wróć do zwiadowcy Vor\'takha w Obozie Oneqwah we Wzgórzach Grizli.', 'Zdjęcia żelaznych krasnoludów', '', '', '', 0),
(12203, 'koKR', 'Rozkazy Lokena', 'Przygotowałem wszystko, czego jeszcze potrzebujesz do zestawu przebrania nadzorcy. Postaraj się nie zwymiotować, gdy go założysz. Bardzo się starałem, żeby wyglądał jak najbardziej realistycznie.$B$BZabierz zestaw na południowy wschód do Dun Argol, przebierz się za jego pomocą, a potem idź do najbardziej wysuniętego na wschód budynku na szerokim środkowym poziomie miasta.$B$BPowinien tam stać piedestał, przy którym than i nadzorcy otrzymują rozkazy od tego Lokena. Uruchom go w przebraniu i dowiedz się z tej wiadomości wszystkiego, co się da.', 'Przebierz się za nadzorcę żelaznych run, przechwyć wiadomość od Lokena, a następnie zamelduj się u zwiadowcy Vor\'takha w Obozie Oneqwah.', '', 'Wróć do zwiadowcy Vor\'takha w Obozie Oneqwah we Wzgórzach Grizli.', 'Odebrana wiadomość od Lokena', '', '', '', 0),
(12204, 'koKR', 'W imię Lokena', 'Żelazne krasnoludy to jedni z najgroźniejszych i najlepiej zorganizowanych wrogów w Północnej Grani. Gdziekolwiek się udaliśmy, walczyły z nami z imieniem Lokena na ustach.$B$BMusimy się dowiedzieć, kim jest ten Loken i czego szuka. Miejscowi mogą nam pomóc.$B$BNa północnym wschodzie, w Faktorii Czerwonego Drewna, człowiek imieniem Hugh Glass sprzedaje swoje towary. Dalej na wschodzie, w Ruinach Tethys, znajdziesz kamiennego olbrzyma imieniem Gavrock. Zapytaj ich o tego Lokena. Muszą wiedzieć coś przydatnego.', 'Porozmawiaj z Hugh Glassem i Gavrockiem o Lokenie, a następnie zdaj relację ze swoich ustaleń zwiadowcy Vor\'takhowi w Obozie Oneqwah.', '', 'Wróć do zwiadowcy Vor\'takha w Obozie Oneqwah we Wzgórzach Grizli.', 'Wypytany Hugh Glass', 'Wypytany Gavrock', '', '', 0),
(12207, 'koKR', 'Upadek Vordrassila', 'Dawno temu potężni druidzi zasadzili drzewo na północny wschód stąd.$B$BNazywało się Vordrassil i miało zostać drzewem świata. Nie wiadomo dlaczego, ale gdy drzewo w pełni wyrosło, druidzi postanowili je zniszczyć.$B$BOd kiedy tu przybyliśmy, przemawia do mnie ziemia, $N. Jej krzyki bólu dochodzą z miejsc, w których szczątki Vordrassila spadły na ziemię.$B$BW tych miejscach pełza plugawiący szlam. Przynieś mi jego próbki, abyśmy mogli zacząć uzdrawiać tę ziemię.', 'Wieszczka wiatru Szary Róg w Warowni Podboju chce, żebyś $gudał:udała; się na Konar Vordrassila, do Serca Vordrassila lub do Łez Vordrassila i $gzdobył:zdobyła; 6 próbek szlamu z entropicznych szlamów.', '', 'Wróć do wieszczki wiatru Szary Róg w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12208, 'koKR', 'Udanych łowów na trolle', 'Nicponie do niczego!$b$bMogli mieć łatwo. Wyciągnęliśmy do nich rękę na zgodę. Wystarczyło, żeby przepuścili nas przez Drak\'Tharon, a dalibyśmy im spokój.$b$bAle nie, dumne małe lodowe trolle postanowiły, że chcą po złości. Teraz zostaną zniszczone, a my i tak przejdziemy przez ich cenną twierdzę do Zul\'Draku.$b$bWynajęliśmy bandę, która dostarcza nam schwytane trolle. Porozmawiaj z Samirem, jeśli chcesz się przyłączyć. Znajdziesz go na północny zachód stąd, prosto na południe od Zeb\'Halak.', 'Sierżant Thurkin kazał ci porozmawiać z Samirem w Granitowych Źródłach.', '', '', '', '', '', '', 0),
(12210, 'koKR', 'Sezon na trolle!', 'Ty tam! Nie ma co tu stać, kiedy jest robota do zrobienia!$b$bTwierdza Drak\'Tharon to najkrótsza droga do Zul\'Draku. MUSIMY ją zdobyć, by zapewnić Przymierzu bezpieczne przejście. Ale dopóki nie zbierzemy dość ludzi do szturmu, musimy się zadowolić przerzedzaniem lodowych trolli i zbieraniem informacji.$b$bW tym celu zwerbowaliśmy bandę zbirów, którzy mają łapać żywe trolle i dostarczać je na przesłuchania. Udaj się na północny zachód i porozmawiaj z Samirem w Granitowych Źródłach. On powie ci, co dalej.', 'Porucznik Dumont w Chacie Bursztynowej Sosny chce, żebyś $gporozmawiał:porozmawiała; z Samirem w Granitowych Źródłach.', '', '', '', '', '', '', 0),
(12212, 'koKR', 'Uzupełnianie spiżarni', 'Dzień dobry, $N.$b$bNasz dobry porucznik mówi, że Horda napadła na nasz magazyn i zapasy żywności niebezpiecznie się skurczyły.$b$bBez wątpienia każemy tym kretynom zapłacić, ale najpierw musimy się skupić na uzupełnieniu zapasów. Moi ludzie robią, co mogą, ale jeśli mamy uniknąć kryzysu, każdy zdolny do pracy musi się dołożyć.$b$bNie powinno ci sprawić trudności zdobycie dziczyzny z tutejszych jeleni. Udanych łowów!', 'Mistrz drwali Anderhol w Chacie Bursztynowej Sosny chce, żebyś $gzabijał:zabijała; jelenie wysokorogie i $gzebrał:zebrała; 8 kawałków soczystej dziczyzny.', '', 'Wróć do mistrza drwali Anderhola w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12213, 'koKR', 'Ciemność w głębi', 'Coś... mrocznego... stało się z drzewem Vordrassil. Gdy druidzi postanowili je zniszczyć, jego wydrążone szczątki zapuściły korzenie głęboko w ziemię.$B$BChcę, żebyś $gudał:udała; się w trzy miejsca na północnym wschodzie, gdzie roztrzaskał się pień drzewa, i $gzszedł:zeszła; tak głęboko pod ziemię, jak tylko zdołasz.$B$BGdy tam dotrzesz, użyj tej kuli, by uchwycić odcisk energii otaczającej to miejsce. Może to rzuci trochę światła na to, co stało się z Vordrassilem i dlaczego nie został drzewem świata.', 'Wieszczka wiatru Szary Róg w Warowni Podboju chce, żebyś $gudał:udała; się do Serca Vordrassila, do Łez Vordrassila i na Konar Vordrassila i $gużył:użyła; Kuli geomanty w głębinach pod powierzchnią.', '', 'Wróć do wieszczki wiatru Szary Róg w Warowni Podboju we Wzgórzach Grizli.', 'Kula użyta pod Sercem Vordrassila.', 'Kula użyta pod Konarem Vordrassila.', 'Kula użyta pod Łzami Vordrassila.', '', 0),
(12215, 'koKR', 'Albo oni, albo my!', 'Jakbyśmy mieli za mało zmartwień...$b$bPrzy obecnym kryzysie żywnościowym musimy konkurować o pożywienie z tutejszymi worgami. Sytuacja staje się coraz poważniejsza i obawiam się, że jeśli natychmiast się tym nie zajmiemy, wkrótce nie będziemy mieli na co polować.$b$bPrzeczesz las. Zabij każdego szaromglistego, którego znajdziesz. Według ostatnich raportów wiele z nich widziano po drugiej stronie rzeki, na zachód stąd.', 'Anderhol w Chacie Bursztynowej Sosny chce, żebyś $godnalazł:odnalazła; i $gzabił:zabiła; 6 szaromglistych łowców we Wzgórzach Grizli.', '', 'Wróć do mistrza drwali Anderhola w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12216, 'koKR', 'Bierz je od tyłu!', 'Wszyscy ciężko pracowaliśmy i zaczyna to przynosić efekty, ale wciąż daleko nam do celu. Potrzebujemy znacznie więcej mięsa, niż mamy, i coraz wyraźniej widać, że same tutejsze jelenie nie wystarczą.$b$bObawiam się, że musisz się zająć groźniejszą zwierzyną – niedźwiedziami grizli, od których ta kraina wzięła nazwę. Jest ich pełno i są dobrze odżywione obfitością ryb, które pływają w tych strumieniach.$b$bUważaj na siebie, $N!', 'Anderhol w Chacie Bursztynowej Sosny chce, żebyś $gzebrał:zebrała; 8 combrów grizzly od niedźwiedzi grizli we Wzgórzach Grizli.', '', 'Wróć do mistrza drwali Anderhola w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12217, 'koKR', 'Orle oczy', 'Cóż, $n, ustaliliśmy, jak Horda zdołała namierzyć nasze ukryte zapasy żywności.$b$bOkazuje się, że łączyli swój wzrok z niczego niepodejrzewającymi orłami, które szybują tu nad drzewami. Dzięki orlemu wzrokowi mogli skutecznie śledzić każdy nasz ruch.$b$bNa rozkaz porucznika musimy wytropić te majestatyczne ptaki, by pokrzyżować plany wroga.', 'Anderhol w Chacie Bursztynowej Sosny chce, żebyś $gzabił:zabiła; 5 cesarskich orłów, a potem $gzłożył:złożyła; mu raport.', '', 'Wróć do mistrza drwali Anderhola w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12219, 'koKR', 'Nieudane drzewo świata', 'Moi przodkowie zasadzili kiedyś drzewo pośrodku Wzgórz Grizli.$B$BNazywało się Vordrassil i miało stać się drzewem świata.$B$BZ dawno zapomnianych powodów, gdy drzewo w pełni wyrosło, postanowili je zniszczyć. Jego olbrzymi pień rozszczepił się w trzech miejscach na północy.$B$BTam, gdzie drzewo dotknęło ziemi, zaczął pełzać plugawy szlam. Przynieś mi próbki szlamu, żebym mogła zacząć pracę, a ziemia mogła zostać uzdrowiona.', 'Hierofantka Thayreen w Chacie Bursztynowej Sosny chce, żebyś $gudał:udała; się na Konar Vordrassila, do Serca Vordrassila lub do Łez Vordrassila i $gzdobył:zdobyła; 6 próbek szlamu z entropicznych szlamów.', '', 'Wróć do hierofantki Thayreen w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12220, 'koKR', 'Mroczny wpływ', 'Gdy drzewo Vordrassil upadło, jego wydrążone szczątki zapuściły korzenie głęboko w ziemię.$B$BChcę, żebyś $gudał:udała; się na północ stąd, w trzy miejsca, gdzie roztrzaskał się pień, i $gzszedł:zeszła; tak głęboko pod ziemię, jak tylko zdołasz. Znajdziesz je na zachód od Siwopaszczy.$B$BGdy tam dotrzesz, użyj tej kuli, by uchwycić odcisk energii otaczającej to miejsce. Jeśli mamy uzdrowić ziemię, musimy najpierw się dowiedzieć, dlaczego przed laty Vordrassil nie stał się drzewem świata.', 'Hierofantka Thayreen w Chacie Bursztynowej Sosny chce, żebyś $gudał:udała; się do Serca Vordrassila, do Łez Vordrassila i na Konar Vordrassila i $gużył:użyła; Kuli geomanty w głębinach pod powierzchnią.', '', 'Wróć do hierofantki Thayreen w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', 'Kula użyta pod Sercem Vordrassila', 'Kula użyta pod Konarem Vordrassila', 'Kula użyta pod Łzami Vordrassila', '', 0),
(12222, 'koKR', 'Sekrety wiążących płomienie', 'Podczas gdy my próbujemy odeprzeć Hordę, plemię Smokołupców gromadzi siły w swojej wiosce Voldrune, niedaleko wybrzeża na południu.$B$BNajpotężniejsi wojownicy wioski dostają talizmany nasycone płomieniem, które pozwalają im panować nad potężnymi, dzikimi protosmokowcami. Jeśli zdołamy przejąć kontrolę nad jednym z tych smokowców, może użyjemy go, by zażegnać zagrożenie ze strony Voldrune.$B$BWiążące płomienie Smokołupców tworzą te talizmany i nasycają je mocą. Zabij je i zabierz talizmany.', 'Przynieś 3 talizmany nasycone płomieniem drwalowi Drake\'owi w Chacie Bursztynowej Sosny.', '', 'Wróć do drwala Drake\'a w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12223, 'koKR', '', 'W wiosce Voldrune na południu panuje gorączkowy ruch. Than Torvald Eriksson i jego huskarlowie szykują się do wojny. Większość naszych ludzi walczy w polu z wiarołomną Hordą, więc Bursztynowa Sosna będzie bezbronna.$B$BUdaj się do Voldrune, niedaleko południowego wybrzeża, i pokaż tym Smokołupcom, że nie jesteśmy łatwym celem.$B$BZabij tylu huskarlów, ilu zdołasz znaleźć. Niech się dwa razy zastanowią, zanim wykorzystają nasz konflikt z Hordą.', 'Zabij 12 huskarlów Smokołupców i wróć do drwala Drake\'a w Chacie Bursztynowej Sosny.', '', 'Wróć do drwala Drake\'a w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12225, 'koKR', 'Mmm... Bursztynowe nasiona!', 'W brzuchu ci burczy, gdy ostry zapach pożywnych orzechów zwraca twoją uwagę na wiadro z nasionami.$b$bJakaś troskliwa dusza najwyraźniej zostawiła tu te darmowe kąski, by pokrzepić zmęczonych wędrowców. Z wdzięcznością bierzesz tych kilka, które zostały, i pochłaniasz je.$b$bNasiona nie zawodzą. Masz ochotę na więcej, więc wyruszasz, by odkryć, skąd pochodzą...', 'Porozmawiaj z mistrzem drwali Anderholem w Chacie Bursztynowej Sosny.', '', '', '', '', '', '', 0),
(12226, 'koKR', 'Na wylot', 'Musimy działać szybko! Nie możemy ryzykować, że te cenne nasiona zostaną całkiem strawione. Muszą wyjść, i to NATYCHMIAST.$b$bNazbieraj trochę czarnego korzenia na brzegu rzeki na zachód stąd, a zrobię ci środek przeczyszczający, który powinien ruszyć sprawy z miejsca.$b$bSzybko! I pamiętaj, $gsam:sama; się o to $gprosiłeś:prosiłaś;...', 'Anderhol w Chacie Bursztynowej Sosny chce, żebyś $gprzyniósł:przyniosła; mu 5 łodyg czarnego korzenia.', '', 'Wróć do mistrza drwali Anderhola w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12227, 'koKR', 'Potrzeba wzywa', 'Dobra. Oto sok.$b$bDziała natychmiast, więc nie używaj go, dopóki nie będziesz $gbezpieczny:bezpieczna; w wychodku.$b$bA teraz idź i zdobądź mi te nasiona!', 'Anderhol w Chacie Bursztynowej Sosny chce, żebyś $gwypił:wypiła; Przeczyszczający cydr Anderhola i $gskorzystał:skorzystała; z pobliskiego wychodka, by odzyskać częściowo przetrawione bursztynowe nasiona.', '', 'Wróć do mistrza drwali Anderhola w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12229, 'koKR', 'Możliwy związek', 'Niedawno wysłaliśmy na wschód wyprawę, którą zaatakowały obłąkane furbolgi. Jeden z ocalałych opowiadał, że zabił jednego z nich, a z jego ciała wypłynęła ciemna, oślizła substancja.$B$BOd tysięcy lat furbolgi w tej okolicy były pokojowe. Możliwe, że ich zachowanie ma związek z mroczną energią, którą wykryliśmy wcześniej.$B$BPrzynieś mi próbki krwi furbolgów. Znajdziesz je na wschodzie, w Kaplicy Wściekłego Kła i Kaplicy Krwi Serca.', 'Wieszczka wiatru Szary Róg w Warowni Podboju chce, żebyś $gzdobył:zdobyła; 8 porcji krwi obłąkanego furbolga od furbolgów z Kaplicy Krwi Serca i Kaplicy Wściekłego Kła.', '', 'Wróć do wieszczki wiatru Szary Róg w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12231, 'koKR', 'Potomstwo niedźwiedziego boga', 'Możliwe, że furbolgi ze Wzgórz Grizli dotknęło to samo skażenie, które nękało Vordrassila. Po latach pokojowego współistnienia toczą ostatnio między plemionami krwawą wojnę.$B$BW kaplicach, których strzegą na wschodzie, mieszka potomstwo Ursoca.$B$BJeśli skażenie dotknęło furbolgi, możliwe, że dzięki swojemu pochodzeniu Kodian i Orsonn pozostali nietknięci.$B$BJeśli tak jest, odszukaj ich i wysłuchaj, co mają do powiedzenia.', 'Wieszczka wiatru Szary Róg w Warowni Podboju chce, żebyś $gporozmawiał:porozmawiała; z Orsonnem w Kaplicy Wściekłego Kła i z Kodianem w Kaplicy Krwi Serca.', '', 'Wróć do wieszczki wiatru Szary Róg w Warowni Podboju we Wzgórzach Grizli.', 'Opowieść Orsonna', 'Opowieść Kodiana', '', '', 0),
(12233, 'koKR', '', 'Nie, nie... Ty je sobie zatrzymaj.$b$bChyba nie $gmyślałeś:myślałaś;, że po tym wszystkim wezmę je do ręki?$b$bOto co zrobisz...', '', '', '', '', '', '', '', 0),
(12236, 'koKR', 'Ursoc, niedźwiedzi bóg', 'Nadszedł czas, $N. Teraz przekonamy się, czy nasze wysiłki dadzą to, czego potrzebujemy, czy nic.$B$BWeź te popioły i odszukaj furbolga, o którym mówił ci Kodian – Tura Wściekłołapa – w pobliżu Nory Ursoca. Norę znajdziesz na północ od Siwopaszczy.$B$BPrzekonaj Tura, by ci pomógł, bo będziesz potrzebować każdej pomocy.$B$BGdy pokonasz niedźwiedziego boga, rozsyp te popioły nad jego ciałem.$B$BNawet jeśli jego ziemska postać zostanie zniszczona, jego duch musi zostać ocalony.', 'Wieszczka wiatru Szary Róg w Warowni Podboju chce, żebyś $godnalazł:odnalazła; Tura Wściekłołapa w pobliżu Nory Ursoca i z jego pomocą $gpokonał:pokonała; Ursoca. Gdy tego dokonasz, użyj Oczyszczonych popiołów Vordrassila na zwłokach Ursoca.', '', 'Wróć do wieszczki wiatru Szary Róg w Warowni Podboju we Wzgórzach Grizli.', 'Oczyszczony Ursoc', '', '', '', 0),
(12238, 'koKR', 'Oczyszczenie Drak\'Tharon', 'W końcu nadszedł czas, dobry przyjacielu.$b$bDrak\'Tharon wkrótce zostanie oczyszczona z tych plugawych nieumarłych i przywrócona do swojego szlachetnego celu. Moja dusza zazna spokoju, a w zamian za twoją pomoc najcenniejsze skarby twierdzy będą twoje, mon!$b$bTwierdza wznosi się w świętym zigguracie. Kiedy dotrzesz na jego szczyt, musisz przywołać mnie ostatni raz, a ja odprawię rytuał.$b$bNiestety, mon, moje przywołanie znowu będzie miało swoją cenę. Musisz zebrać mojo od ocalałych w twierdzy,', 'Drakuru chce, żebyś $gużył:użyła; Eliksiru Drakuru przy jego kadzielnicy w Drak\'Tharon. Aby użyć tam Eliksiru Drakuru, potrzebujesz 5 wytrwałych mojo.', '', '', '', '', '', '', 0),
(12241, 'koKR', 'Zniszcz sadzonkę', 'Dzieło furbolgów trzeba cofnąć, $N. Najlepsze intencje niewiele znaczą, gdy ich owoc skaża tak silne zepsucie.$B$BSadzonkę trzeba zniszczyć, bo to ona jest źródłem tego mrocznego wpływu. Weź tę pochodnię, podpal nią skażoną sadzonkę i przynieś mi jej popioły.$B$BGdy ogień je oczyści, użyję całej mocy, jaką mam, by usunąć z nich skażenie. Popioły będą ci potrzebne, by oczyścić Ursoca ze złej mocy, która nim zawładnęła.', 'Wieszczka wiatru Szary Róg w Warowni Podboju chce, żebyś $gużył:użyła; Zielonej pochodni, by spalić Sadzonkę Vordrassila. Przynieś Popioły Vordrassila wieszczce wiatru Szary Róg.', '', 'Wróć do wieszczki wiatru Szary Róg w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12242, 'koKR', 'Nasiona Vordrassila', 'Musimy dopilnować, żeby Vordrassil nigdy nie odrósł. Furbolgi musiały zebrać jego nasiona.$B$BUdaj się do Siwopaszczy, w środkowej części Wzgórz Grizli, i zdobądź wszystkie nasiona, jakie znajdziesz. Dopilnuję, żeby zostały należycie zniszczone.', 'Wieszczka wiatru Szary Róg w Warowni Podboju chce, żebyś $gudał:udała; się do Siwopaszczy i $gzdobył:zdobyła; 8 Nasion Vordrassila.', '', 'Wróć do wieszczki wiatru Szary Róg w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12244, 'koKR', 'Naprawa rozdrabniaczy', 'Słuchaj no, kolego. Może byś tak zakasał rękawy i złapał klucz? Jest robota do zrobienia! Trzeba odnowić te rozdrabniacze i wysłać je do Zatoki Gitgeszeft, i to na wczoraj...$b$bNie masz klucza? To na co mi się przydasz? Równie dobrze możesz zejść na dół z resztą tych osiłków i bawić się z Hordą!$b$bSkoro już tam będziesz, zobacz, czy dasz radę przyprowadzić tu parę tych zepsutych rozdrabniaczy do naprawy. Uważaj! Są w dość kiepskim stanie.', 'Synipus w Tartaku „Błękitne Niebo” chce, żebyś $gprzyprowadził:przyprowadziła; mu 3 zepsute rozdrabniacze.', '', 'Wróć do Synipusa w Tartaku „Błękitne Niebo” we Wzgórzach Grizli.', 'Dostarczony rozdrabniacz', '', '', '', 0),
(12246, 'koKR', 'Możliwy związek', 'Furbolgi, które żyją na wschód stąd, są bardziej agresywne i dzikie niż te, do których przywykliśmy. Nasze siły starły się z nimi nie raz, a ocaleni zawsze mówią o ciemnej, oślizłej substancji, która cieknie z ich zwłok.$B$BIch stan może mieć związek ze skażeniem, które znaleźliśmy na szczątkach Vordrassila.$B$BPrzynieś mi próbki krwi furbolgów. Znajdziesz je w Kaplicy Wściekłego Kła i Kaplicy Krwi Serca, daleko na wschodzie.', 'Hierofantka Thayreen w Chacie Bursztynowej Sosny chce, żebyś $gzdobył:zdobyła; 8 porcji krwi obłąkanego furbolga od furbolgów z Kaplicy Krwi Serca i Kaplicy Wściekłego Kła.', '', 'Wróć do hierofantki Thayreen w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12247, 'koKR', 'Dzieci Ursoca', 'Furbolgi ze Wzgórz Grizli z pewnością noszą w sobie jakieś skażenie. Po latach pokojowego współistnienia wybuchła między ich plemionami wojna.$B$BPozostaje się przekonać, czy niedźwiedzie, które czczą jako bogów, również zostały skażone.$B$BDwoje dzieci Ursoca, Orsonn i Kodian, mieszka w Kaplicy Krwi Serca i Kaplicy Wściekłego Kła, na południe i południowy wschód od Siwopaszczy.$B$BSprawdź, czy zechcą ci powiedzieć, co tu się wydarzyło.', 'Hierofantka Thayreen w Chacie Bursztynowej Sosny chce, żebyś $gporozmawiał:porozmawiała; z Orsonnem w Kaplicy Wściekłego Kła i z Kodianem w Kaplicy Krwi Serca.', '', 'Wróć do hierofantki Thayreen w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', 'Opowieść Orsonna', 'Opowieść Kodiana', '', '', 0),
(12248, 'koKR', 'Sadzonka Vordrassila', 'Wygląda na to, że dawni druidzi mieli dobre powody, by zniszczyć Vordrassila. Nie możemy pozwolić, by furbolgi go odhodowały.$B$BZ drugiej strony ocalenie ducha Ursoca zależy od magii zawartej w sadzonce.$B$BWeź tę pochodnię i spal nią drzewko. Znajdziesz je pośrodku Siwopaszczy, wewnątrz starego pnia Vordrassila.$B$BPrzynieś mi popioły Vordrassila. Mam nadzieję, że gdy ogień je oczyści, użyjemy ich magii, by oczyścić ducha Ursoca z mrocznego skażenia.', 'Hierofantka Thayreen w Chacie Bursztynowej Sosny chce, żebyś $gużył:użyła; Zielonej pochodni, by spalić Sadzonkę Vordrassila. Przynieś Popioły Vordrassila hierofantce Thayreen.', '', 'Wróć do hierofantki Thayreen w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12249, 'koKR', 'Ursoc, niedźwiedzi bóg', 'Już czas, $N. Weź te popioły i poszukaj furbolga, o którym mówił Kodian. Jeśli wyruszył na poszukiwanie Ursoca, będzie w pobliżu jego nory, na północ od Siwopaszczy.$B$BBędziesz potrzebować jego pomocy. $gSam:Sama; nie zdołasz pokonać Ursoca.$B$BGdy pokonasz Ursoca, użyj tych popiołów, by oczyścić jego ducha. Dopiero wtedy się dowiemy, czy nasze wysiłki poszły na marne.', 'Hierofantka Thayreen w Chacie Bursztynowej Sosny chce, żebyś $godnalazł:odnalazła; Tura Wściekłołapa w pobliżu Nory Ursoca i z jego pomocą $gpokonał:pokonała; Ursoca. Gdy tego dokonasz, użyj Oczyszczonych popiołów Vordrassila na zwłokach Ursoca.', '', 'Wróć do hierofantki Thayreen w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', 'Oczyszczony Ursoc', '', '', '', 0),
(12250, 'koKR', 'Nasiona Vordrassila', 'Nie możemy pozwolić, by Vordrassil znów wyrósł. Skoro furbolgi odhodowały go raz, mogą to zrobić ponownie.$B$BUdaj się do Siwopaszczy, w środkowej części Wzgórz Grizli, i zdobądź nasiona Vordrassila. Dopilnuję, żeby zostały należycie zutylizowane.', 'Hierofantka Thayreen w Chacie Bursztynowej Sosny chce, żebyś $gudał:udała; się do Siwopaszczy i $gzdobył:zdobyła; 8 Nasion Vordrassila.', '', 'Wróć do hierofantki Thayreen w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12255, 'koKR', 'Than Voldrune', 'Skoro już $gzdobyłeś:zdobyłaś; talizmany nasycone płomieniem i $gosłabiłeś:osłabiłaś; obronę Voldrune, możemy uderzyć w jego przywódcę, thana Torvalda Erikssona.$B$BUlubionym wierzchowcem thana jest nieokiełznany protosmokowiec, którego nazywa Płomieniodzierżcą. Trzymają go skutego łańcuchami w zachodniej części Voldrune, ale dzięki talizmanom $gpowinieneś:powinnaś; zdołać panować nad nim dość długo, by użyć go przeciw thanowi.$B$BGdy Płomieniodzierżca będzie pod twoją kontrolą, przeszukaj szczyty wież Voldrune, znajdź thana i nie okazuj mu litości.', 'Użyj Płomieniodzierżcy, by pokonać thana Torvalda Erikssona, i zamelduj się u drwala Drake\'a w Chacie Bursztynowej Sosny.', '', 'Wróć do drwala Drake\'a w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12256, 'koKR', 'Sekrety wiążących płomienie', 'Podczas gdy tchórze z Przymierza atakują nasze pozycje, placówka wrykułów Smokołupców w Voldrune, na południowym wschodzie, szykuje się do wojny. Wrykule nie są bynajmniej najsilniejszym wrogiem, z jakim się tu mierzymy, ale musimy ich wyeliminować, zanim naprawdę staną się zagrożeniem.$B$BIch najpotężniejsi wojownicy mogą dosiadać w bitwie na wpół wytresowanych protosmokowców. Aby panować nad tymi bestiami, ich wiążące płomienie tworzą potężne talizmany. Jeśli nasz plan ma się udać, musisz je zabić i zabrać talizmany.', 'Przynieś 3 talizmany nasycone płomieniem sierżantowi Nazgrimowi w Warowni Podboju.', '', 'Wróć do sierżanta Nazgrima w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12257, 'koKR', 'Pokaz siły', 'W wiosce wrykułów Voldrune, na południowym wschodzie, trwają przygotowania do wojny. Than Voldrune nie wystawi wielkiej armii, ale nasze siły są rozproszone, więc wciąż grozi nam niebezpieczeństwo.$B$BNie możemy ryzykować, że than i jego ludzie dostaną okazję do ataku, więc to my musimy zanieść im bitwę. Jeśli naprawdę walczysz za Hordę, z radością wykorzystasz okazję, by pokazać naszą siłę.$B$BWytnij huskarlów i udowodnij temu klanowi Smokołupców, że z Hordą nie ma żartów!', 'Zabij 12 huskarlów Smokołupców i wróć do sierżanta Nazgrima w Warowni Podboju.', '', 'Wróć do sierżanta Nazgrima w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12259, 'koKR', 'Than Voldrune', 'Dzięki talizmanom nasyconym płomieniem możemy wreszcie rzucić wyzwanie thanowi.$B$BJego ulubionym wierzchowcem jest dziki protosmokowiec zwany Płomieniodzierżcą. Trzymają go skutego łańcuchami w zachodniej części Voldrune, ale dzięki mocy talizmanów $gpowinieneś:powinnaś; zdołać nagiąć go do swojej woli i użyć przeciw thanowi.$B$BGdy Płomieniodzierżca będzie pod twoją kontrolą, przeszukaj szczyty wież Voldrune, znajdź thana i zniszcz go za pomocą Płomieniodzierżcy.', 'Użyj Płomieniodzierżcy, by pokonać thana Torvalda Erikssona, i zamelduj się u sierżanta Nazgrima w Warowni Podboju.', '', 'Wróć do sierżanta Nazgrima w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12268, 'koKR', 'Części i częścinki', 'Ech! Ale to rozklekotane!$b$bGoblińska inżynieria pozostawia wiele do życzenia, możesz mi wierzyć. Tylko spójrz na to! Cud, że to w ogóle kiedykolwiek działało.$b$bPomożesz mi? Żeby to choć zbliżyć do stanu używalności, muszę wymienić parę kół zębatych, zębatek i sprężyn. Bez trudu znajdziesz je w okolicy tartaku.', 'Pipthwack w Tartaku „Błękitne Niebo” chce, żebyś $gzebrał:zebrała; 4 żłobkowane koła zębate, 3 nacięte zębatki i 2 sprężyny wysokiego naprężenia.', '', 'Wróć do Pipthwacka w Tartaku „Błękitne Niebo” we Wzgórzach Grizli.', '', '', '', '', 0),
(12270, 'koKR', 'Rozdrobnić Przymierze', 'Czytaj z ruchu warg, $N – potrzebuję tych rozdrabniaczy! I równie ważne – nie mogą wpaść w ręce Przymierza!$b$bOdnawiają rozdrabniacze i używają ich przeciw naszym braciom w Zatoce Gitgeszeft. Teraz odpłacimy im pięknym za nadobne!$b$bWidzisz tam rozdrabniacz – bierz go! Widzisz na nim jakąś szumowinę z Przymierza – zabij ją i bierz rozdrabniacz! Jak już jakiś zdobędziesz, przyprowadź go tu do mnie, a my się nim zajmiemy.$b$bOdmaszerować!', 'Grekk w Tartaku „Błękitne Niebo” chce, żebyś $gzdobył:zdobyła; 3 rozdrabniacze i $gprzyprowadził:przyprowadziła; je do niego.', '', 'Wróć do Grekka w Tartaku „Błękitne Niebo” we Wzgórzach Grizli.', 'Dostarczony rozdrabniacz', '', '', '', 0),
(12279, 'koKR', 'Niedźwiedzi apetyt', 'Całe szczęście, że wróciłeś, Kuternogo! Bałem się, że Griselda i ja zostaniemy zupełnie sami.$B$BGotuję tu dla nas coś do jedzenia, ale Griselda nie chce tego tknąć.$B$BLubi ryby, które żyją u wybrzeży Brzegu Wschodniego Wiatru, na wschodzie. Ja ich nie znoszę, ale ona zawsze była wybredna. Sześć porządnych ryb powinno ją na jakiś czas zadowolić.$B$BA teraz biegnij... to jest... kuśtykaj, Joe. Nie chcesz chyba kazać dziewczynie czekać, co?', 'Przynieś 6 łososi północnych Hugh Glassowi w Faktorii Czerwonego Drewna.', '', 'Wróć do Hugh Glassa w Faktorii Czerwonego Drewna we Wzgórzach Grizli.', '', '', '', '', 0),
(12280, 'koKR', 'Naprawy', 'Dwadzieścia rozdrabniaczy do jutra do południa!$b$bKto w ogóle układa te harmonogramy? Na pewno nikt, kto kiedykolwiek składał do kupy któryś z tych kubłów na śmieci, ot co...$b$bJeśli mam wyrobić normę, potrzebuję pomocy. Pomóż mi, a podzielę się z tobą prowizją – może być?$b$bPotrzebuję kół zębatych, zębatek i sprężyn. Walają się po ziemi na dole, przy rozdrabniaczach.', 'Lurz w Tartaku „Błękitne Niebo” chce, żebyś $gzebrał:zebrała; 4 żłobkowane koła zębate, 3 nacięte zębatki i 2 sprężyny wysokiego naprężenia.', '', 'Wróć do Lurza w Tartaku „Błękitne Niebo” we Wzgórzach Grizli.', '', '', '', '', 0),
(12284, 'koKR', 'Nie dajmy im odetchnąć', 'Ponieśliśmy tu ciężkie straty.$b$bJedyna dobra wiadomość to taka, że oddaliśmy tyle samo, ile dostaliśmy. Poprosiłem o posiłki, ale większość naszych sił ugrzęzła w Zatoce Gitgeszeft. Wygląda na to, że na razie jesteśmy zdani na siebie.$b$bBez względu na to, jak źle będzie, MUSIMY utrzymać pozycje! Cenne surowce tego regionu są kluczowe dla długofalowego sukcesu Hordy w Północnej Grani.$b$bMusimy trzymać Przymierze w defensywie, dopóki nie nadejdzie pomoc. Ruszaj tam i daj im do myślenia.', 'Komendant Bargok chce, żebyś $gzabił:zabiła; 15 żołnierzy lub graczy Przymierza w Tartaku „Błękitne Niebo”.', '', 'Wróć do komendanta Bargoka w Tartaku „Błękitne Niebo” we Wzgórzach Grizli.', 'Wyeliminowani żołnierze Przymierza', '', '', '', 0),
(12288, 'koKR', 'Za dużo rannych!', 'Hej, ty! Pomóż mi!$b$bTracimy cenne życia! Rannych jest po prostu za dużo, żebym sama mogła się nimi zająć. Jeśli nie wyleczymy naszych żołnierzy, mogą nas całkiem wyprzeć ze Wzgórz Grizli!$b$bWeź tę opaskę uciskową i użyj jej na rannych na polu bitwy.$b$bSzybko, $N! Oni umieeerają!!', 'Aumana w Tartaku „Błękitne Niebo” chce, żebyś $gużył:użyła; Odnawiającej opaski uciskowej na 10 rannych harcownikach.', '', 'Wróć do Aumany w Tartaku „Błękitne Niebo” we Wzgórzach Grizli.', 'Opatrzeni ranni harcownicy', '', '', '', 0),
(12289, 'koKR', 'Dobij leżącego', 'To czarny dzień dla Przymierza. Wielu dobrych ludzi leży tu martwych lub konających. Jedyną pociechą jest to, że dobrze walczyli i zabrali ze sobą wielu wrogów.$b$bWiększość naszych sił rzucono do Zatoki Gitgeszeft, więc musimy przetrwać tę burzę sami. Surowce tego regionu są dla Przymierza niezwykle ważne i mogą przesądzić o wyniku naszej walki z Hordą. Nie możemy zawieść!$b$bIdź, $N. Uderz w nich, póki liżą rany. Pomścij poległych braci i podtrzymaj naszą nadzieję!', 'Sierżant Hartsman chce, żebyś $gpokonał:pokonała; 15 żołnierzy lub graczy Hordy w Tartaku „Błękitne Niebo”.', '', 'Wróć do sierżanta Hartsmana w Tartaku „Błękitne Niebo” we Wzgórzach Grizli.', 'Wyeliminowani żołnierze Hordy', '', '', '', 0),
(12292, 'koKR', 'Miejscowe wsparcie', 'Utknęliśmy w martwym punkcie z Hordą we Wzgórzach Grizli. Nasze siły są niemal wyrównane i wszystko dotąd wskazywało na pat.$B$BAż do dzisiejszego ranka. Miejscowi traperzy poprosili nas o pomoc. Podobno Horda zabrała im coś, co do nich należy... jakąś relikwię.$B$BJeśli im to odzyskamy, dadzą nam przewagę, której potrzebujemy. Udaj się do Faktorii Wiecznej Zieleni, na zachód od Warowni Podboju, i poszukaj cedrowej skrzyni.', 'Porucznik Dumont w Chacie Bursztynowej Sosny chce, żebyś $gudał:udała; się do Faktorii Wiecznej Zieleni i $gzdobył:zdobyła; Cedrową skrzynię.', '', 'Wróć do porucznika Dumonta w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12293, 'koKR', 'Dobicie targu', 'Mamy to, czego chcą traperzy. Teraz musimy ich przeciągnąć na naszą stronę.$B$BZanieś skrzynię traperowi imieniem Ivan w Posterunku Osikowego Gaju, tuż na północ stąd.$B$BJeśli wszystko pójdzie dobrze, w mig będziemy mieli miejscowych leśnych ludzi na zwiadowców dla armii króla.', 'Zanieś Cedrową skrzynię Ivanowi w Posterunku Osikowego Gaju.', '', 'Wróć do Ivana w Posterunku Osikowego Gaju we Wzgórzach Grizli.', '', '', '', '', 0),
(12294, 'koKR', 'Wstępny pakt', 'Dobrze, $N. Twoi ludzie dotrzymali swojej części umowy.$B$BPowiedz Dumontowi, że dotrzymamy słowa.', 'Wróć do porucznika Dumonta w Chacie Bursztynowej Sosny.', '', '', '', '', '', '', 0),
(12295, 'koKR', 'Ćwiczenie z dyplomacji', 'Od tygodni próbowaliśmy się dogadać z traperami, ale nic nie wskóraliśmy, dopóki nie $gznalazłeś:znalazłaś; tej przeklętej skrzyni.$B$BTo powinna być dobra wiadomość dla naszego wysłannika w Srebrnym Potoku. Wysłaliśmy tam Ducala mniej więcej tydzień temu, a z jego ostatniego listu wynikało, że niewiele wskórał.$B$BUdaj się do Srebrnego Potoku i pomóż mu w jego dyplomatycznych staraniach. Ruszaj drogami na północny zachód stąd, a znajdziesz go po przejściu kilku mostów.', 'Porozmawiaj z wysłannikiem Ducalem w Srebrnym Potoku.', '', '', '', '', '', '', 0),
(12296, 'koKR', 'Życie albo śmierć', 'Och, co za rzeź...$b$bPrzeżyłam wiele bitew, $N, a ta była brutalniejsza niż wszystkie, które widziałam. Nasza walka z Hordą jest zacieklejsza niż kiedykolwiek. Tu, w Północnej Grani, chodzi o to: oni albo my – życie albo śmierć.$b$bJeśli mamy przetrwać tu kolejny dzień, musimy opatrzyć rannych. Jest ich zbyt wielu, żebym sama mogła ich ratować.$b$bPrzygotowałam specjalne bandaże, dzięki którym $gbędziesz mógł:będziesz mogła; mi pomóc. Weź jeden i zajmij się tymi, którzy jeszcze nie ulegli ranom.', 'Rheanna w Tartaku „Błękitne Niebo” chce, żebyś $gużył:użyła; Odnawiającego bandaża na 10 rannych piechurach z Zachodniego Skraju.', '', 'Wróć do Rheanny w Tartaku „Błękitne Niebo” we Wzgórzach Grizli.', 'Opatrzeni piechurzy z Zachodniego Skraju', '', '', '', 0),
(12299, 'koKR', 'Północna gościnność', 'Miło cię poznać. Uczcijmy nasz pakt starym, dobrym zabijaniem Hordy.$B$BTuż za naszym miasteczkiem, na zachodzie, znajdziesz maruderów z Warowni Podboju. Może wybierzesz się tam i zapolujesz na nich jak na plugawe zwierzęta, którymi są?$B$BZobaczmy, czy nasi nowi sojusznicy potrafią poprzeć gadanie czynami.', 'Sergei w Srebrnym Potoku chce, żebyś $gzabił:zabiła; 8 maruderów z Warowni Podboju.', '', 'Wróć do Sergeia w Srebrnym Potoku we Wzgórzach Grizli.', '', '', '', '', 0),
(12300, 'koKR', 'Próba hartu', 'No dobrze, $gprzyjacielu:przyjaciółko;. $GWyświadczyłeś:Wyświadczyłaś; nam przysługę czy dwie, ale to nie jest prawdziwy sprawdzian odwagi.$B$BW tych stronach nie jesteś prawdziwym łowcą, dopóki nie nosisz skóry swojej ofiary.$B$B<Sergei wyciąga z pochwy nóż do skórowania i wręcza ci go.>$B$BPrzywódca tych przeklętych orków, które atakują nasze miasteczko, nazywa się Kościołam. Znajdziesz go w obozie dalej na północnym zachodzie.$B$BTak jest. Obedrzesz tego potwora ze skóry.', 'Odnajdź sierżanta Kościołama na północny zachód od Srebrnego Potoku i przejdź Próbę hartu.', '', 'Wróć do pojmanej traperki na Wzgórzach Srebrnego Potoku we Wzgórzach Grizli.', 'Próba hartu', '', '', '', 0),
(12302, 'koKR', 'Słowa ostrzeżenia', 'Dzięki za pomoc, $N. Mam na imię Sasha. Słuchaj, muszę się stąd wynosić, i to już.$B$BLudzie, którzy cię tu przysłali... moi ludzie... zmienili się. To już nie są dobrzy ludzie... i chcą cię zmienić w jednego... w jednego z nich.$B$BTa... „próba”, na którą cię wysłali, to dopiero początek.$B$BIdź na północno-zachodni kraniec Srebrnego Potoku. Znajdziesz tam coś, co cię zainteresuje.$B$BPowodzenia... i nikomu nie ufaj.', 'Udaj się na północno-zachodni kraniec Srebrnego Potoku.', '', '', '', '', '', '', 0),
(12307, 'koKR', 'Korzeń tojadu', '$GSłyszałeś:Słyszałaś; o tojadzie? To okropne zielsko... niszczy nasze uprawy.$B$BCały zeszły tydzień go wycinaliśmy, ale korzenie znowu zaczynają puszczać pędy.$B$BMoże to nie wygląda na pilną sprawę, ale gdyby ta roślina znów się rozpleniła, byłaby to prawdziwa... katastrofa. Pomożesz nam i wyrwiesz je z ziemi, gdzie tylko znajdziesz je w pobliżu wioski?', 'Katja w Srebrnym Potoku chce, żebyś $gwyrwał:wyrwała; 8 korzeni tojadu.', '', 'Wróć do Katji w Srebrnym Potoku we Wzgórzach Grizli.', '', '', '', '', 0),
(12308, 'koKR', 'Ucieczka ze Srebrnego Potoku', 'Ty... nie jesteś jednym z nich? Szybko! Wypuść mnie!$B$BMusimy natychmiast dotrzeć do Chaty Bursztynowej Sosny! Kiedy porucznik Dumont się dowie, kim naprawdę są ci ludzie, z tego miasteczka zostanie kupa gruzu!', 'Otwórz Drewnianą klatkę i pomóż uwolnionemu zwiadowcy Przymierza uciec ze Srebrnego Potoku. Gdy dotrzesz do Chaty Bursztynowej Sosny, zamelduj się u porucznika Dumonta.', '', 'Wróć do porucznika Dumonta w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', 'Ucieczka ze Srebrnego Potoku', '', '', '', 0),
(12310, 'koKR', 'Szybka odpowiedź', 'Musimy odpowiedzieć natychmiast. Stanowczo. Musimy nauczyć tych dzikusów, że z nami się nie zadziera.$B$BNasi zwiadowcy znaleźli to, co zostało z traperów ze Srebrnego Potoku... no wiesz, tych, których nie $gzdążyłeś:zdążyłaś; potraktować ogniem. Podobno blokują drogę na południowy wschód... może próbują nas otoczyć.$B$BUdaj się do Posterunku Skraju Lasu i zajmij się nimi. Ich przywódcą jest podobno człowiek imieniem Vladek... dopilnuj, żeby się z nim rozprawić.', 'Porucznik Dumont chce, żebyś $gudał:udała; się do Posterunku Skraju Lasu i $gzabił:zabiła; Vladeka oraz 7 łowców ze Srebrnego Potoku.', '', 'Wróć do porucznika Dumonta w Chacie Bursztynowej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12314, 'koKR', 'Precz z kapitan Zorną!', 'Siły Hordy szykują się, by przełamać nasze linie i dokończyć podbój Zatoki Gitgeszeft, jeśli nic nie zrobimy. Siłami Hordy w porcie dowodzi kapitan Zorna, przy statku po drugiej stronie zatoki.$B$BJeśli ją pokonasz, ofensywa Hordy się załamie, a my wykorzystamy okazję, by zdobyć port. Uważaj, $N, bo Zorna to zaciekła wojowniczka. Pokonanie jej może wymagać kilku osób, a jeśli masz dostęp do naprawionego rozdrabniacza, możesz spróbować obrócić go na swoją korzyść.', 'Zabij kapitan Zornę i zamelduj się u barona Freemana w Zatoce Gitgeszeft.', '', 'Wróć do barona Freemana w Zatoce Gitgeszeft we Wzgórzach Grizli.', '', '', '', '', 0),
(12315, 'koKR', 'Zmiażdż kapitana Jasną Wodę!', 'Przy każdym natarciu nasi ludzie napotykają świeże posiłki Przymierza. Jakby ich dowódca przewidywał każdy mój ruch!$B$BNadszedł czas, by dobry kapitan Jasna Woda spotkał swój koniec. Dowodzi swoimi oddziałami z pokładu niszczyciela Przymierza na drugim krańcu zatoki.$B$BTo nie będzie łatwa walka, $N. Weź ze sobą paru zaufanych przyjaciół, a jeśli masz kluczyk do jednego z tych naprawionych rozdrabniaczy, użyj go, żeby wypatroszyć Jasną Wodę! Tak czy inaczej, musi zginąć!', 'Zabij kapitana Jasną Wodę i zamelduj się u generała Khazgara w Zatoce Gitgeszeft.', '', 'Wróć do generała Khazgara w Zatoce Gitgeszeft we Wzgórzach Grizli.', '', '', '', '', 0),
(12316, 'koKR', 'Trzymajcie ich z dala od zatoki!', 'Nie możemy pozwolić, by Horda przejęła Zatokę Gitgeszeft. Port jest kluczowy dla naszych działań we Wzgórzach Grizli i dalej.$B$BKapitan Mocnopłaszcz zabrał resztę Brygady Zachodniego Skraju na wschód, by szukać przejścia przez góry, więc nie będziemy mieli posiłków.$B$BRuszaj w pole, $N, i zabijaj berserkerów z Warowni Podboju, których Horda wysłała przeciw nam. Wycinaj ich, aż żaden nie zostanie na nogach. Przymierze musi mieć ten port!', 'Pokonaj 10 żołnierzy lub graczy Hordy w Zatoce Gitgeszeft i wróć do porucznika Stuarta.', '', 'Wróć do porucznika Stuarta w Zatoce Gitgeszeft we Wzgórzach Grizli.', 'Zabici członkowie Hordy w Zatoce Gitgeszeft', '', '', '', 0),
(12317, 'koKR', 'Trzymajcie ich z dala od zatoki', 'Ta nędzna Brygada Zachodniego Skraju okazuje się twardszym przeciwnikiem, niż sądziliśmy. Choć jest ich niewielu, walczą dobrze i dzielnie, ale nie możemy sobie pozwolić na czekanie, aż się wykruszą.$B$BZdobywczyni Krenna rozkazała szybko zdobyć port. Musisz przełamać ten impas, $N. Znajdź piechurów morskich wroga i wyrzynaj ich, dopóki opór nie ustanie. Dopiero wtedy będziemy mogli zająć port.$B$BRuszaj szybko. Nie chcemy kazać zdobywczyni Krennie czekać.', 'Pokonaj 10 żołnierzy lub graczy Przymierza w Zatoce Gitgeszeft i wróć do centuriona Kaggruma.', '', 'Wróć do centuriona Kaggruma w Zatoce Gitgeszeft we Wzgórzach Grizli.', 'Zabici członkowie Przymierza w Zatoce Gitgeszeft', '', '', '', 0),
(12323, 'koKR', 'Wykurzyć ich', 'W niektórych budynkach w środku Zatoki Gitgeszeft wciąż ukrywają się grupki tchórzliwych ludzi ze spółki Gitgeszeft. Potrzebuję tam każdego człowieka, jakiego mogę wysłać do walki z Hordą, ale nie możemy też pozwolić, by tych maruderów ze spółki Gitgeszeft koczowały w tych budynkach.$B$BMoże uda nam się ich „przekonać”, żeby ruszyli na swój statek. Weź tę bombę dymną i wykurz nią maruderów z ich kryjówek w baraku, tartaku albo stajniach. Tylko nie podchodź za blisko – pewnie gryzą.', 'Użyj Bomby dymnej, by wykurzyć z budynków 20 zbłąkanych pracowników spółki Gitgeszeft, a następnie zamelduj się u sierżanta Downeya.', '', 'Wróć do sierżanta Downeya w Zatoce Gitgeszeft we Wzgórzach Grizli.', 'Wykurzeni zbłąkani pracownicy spółki Gitgeszeft', '', '', '', 0),
(12324, 'koKR', 'Wykurzyć ich', 'Nie dość, że ten port roi się od skamlących tchórzy z Przymierza, to na domiar złego w niektórych budynkach wciąż ukrywają się pracownicy spółki Gitgeszeft. Nie są warci czasu, jaki zajęłoby ich zabicie, a zresztą nie mogę oddelegować żadnych wojowników.$B$BMoże uda nam się ich „przekonać”, żeby ruszyli na swój statek. Weź tę bombę dymną i wykurz nią maruderów z ich kryjówek w baraku, tartaku albo stajniach. Tylko nie podchodź za blisko – nie wiadomo, jakie choroby roznoszą.', 'Użyj Bomby dymnej, by wykurzyć z budynków 20 zbłąkanych pracowników spółki Gitgeszeft, a następnie zamelduj się u kamiennego strażnika Wściekłego Totemu.', '', 'Wróć do kamiennego strażnika Wściekłego Totemu w Zatoce Gitgeszeft we Wzgórzach Grizli.', 'Wykurzeni zbłąkani pracownicy spółki Gitgeszeft', '', '', '', 0),
(12327, 'koKR', 'Doświadczenie poza ciałem', 'Ach, szukasz wizji przeszłości. To mądre z twojej strony.$B$BKażdy, kto do mnie zagląda po wróżbę, zawsze pyta o przyszłość. Kiedy dożyjesz moich lat, przekonasz się, że wglądanie w przeszłość jest zwykle bardziej przydatne.$B$BWypij ten eliksir i zajrzyj w moją kryształową kulę. Zobaczmy, jaką wiedzę uda nam się zdobyć.', 'Wypij Zwiewną miksturę przy Kryształowej kuli Ruuny i zobacz wizję z przeszłości.', 'Wizja z przeszłości', 'Porozmawiaj z Ruuną Ślepą w Obozie Ruuny we Wzgórzach Grizli.', '', '', '', '', 0),
(12328, 'koKR', 'Prośba Ruuny', 'Nie wezmę od ciebie złota za moje usługi, bo przewiduję, że twoje czyny są konieczne i wiele zależy od tego, czego się dziś dowiesz.$B$BPoproszę cię jednak o zebranie dla mnie pewnego składnika. Zdobądź zwiewny pył od paprociożernych ciem na północny wschód stąd. Zrób to, a przygotuję miksturę, która zabierze cię w czas i miejsce wydarzeń, których musisz być świadkiem.', 'Ruuna Ślepa chce, żebyś $gzdobył:zdobyła; 4 garści zwiewnego pyłu.', '', 'Wróć do Ruuny Ślepej w Obozie Ruuny we Wzgórzach Grizli.', '', '', '', '', 0),
(12329, 'koKR', 'Los i przypadek', 'Na tym świecie są dwa rodzaje ludzi, $N. Ci, którzy wierzą w przypadek, i ci, którzy nie wierzą.$B$BTego dnia, gdy straciłam wzrok, otrzymałam dar jasnowidzenia. Chyba się domyślasz, do których należę.$B$BDziś rano młoda kobieta imieniem Sasha miała tę samą wizję co ty. Warto, żebyś z nią $gporozmawiał:porozmawiała;.$B$BZnajdziesz ją prosto na wschód stąd, w Faktorii Białej Sosny, po drodze do Wioski Przesilenia.', 'Porozmawiaj z Sashą w Faktorii Białej Sosny.', '', '', '', '', '', '', 0),
(12330, 'koKR', 'Anatoly zacznie mówić', 'Moja siostra gdzieś tu jest, a nie mogę zmusić tego potwora do mówienia.$B$BNie dba o własną skórę, ale mam pewien pomysł. Znałam żonę Anatoly\'ego, Tatjanę, jeszcze sprzed przybycia Kultu Wilka – zajmowała się końmi.$B$BWeź tę strzałkę usypiającą. Przyprowadź ją żywą, będzie nam potrzebna, jeśli mamy mieć na Anatoly\'ego jakiś haczyk.$B$BKiedy uratujemy moją siostrę, pomogę ci znaleźć tego, kto za tym wszystkim stoi.', 'Sasha w Faktorii Białej Sosny chce, żebyś $gużył:użyła; Strzałki usypiającej na Tatjanie w Wiosce Przesilenia. Przyprowadź Tatjanę do Faktorii Białej Sosny.', 'Dostarczona Tatjana', 'Wróć do Sashy w Faktorii Białej Sosny we Wzgórzach Grizli.', '', '', '', '', 0),
(12411, 'koKR', 'Przysięga siostry', 'Proszę, $N. Wiem, że chodzi ci o Arugala. Przysięgam na pamięć ojca, że pomogę ci go dopaść.$B$BAle muszę cię błagać... Anya jest zupełnie niewinna, nie możemy jej zostawić z tymi dzikusami.$B$BPomóż mi uratować siostrę, a będę u twojego boku, kiedy staniesz przed Arugalem.$B$BZnam norę, o której mówił Anatoly. Znajdziemy ją po drugiej stronie tego wzgórza. Chodźmy, moja siostra jest w niebezpieczeństwie.', 'Poszukaj Anyi w Norze Wycia o Zmroku niedaleko Wioski Przesilenia.', '', '', '', '', '', '', 0),
(12412, 'koKR', 'Przyjaciel mojego wroga', 'Jeśli mam ci coś wbić do głowy, niech to będzie to: Przymierze zostanie zmiażdżone we Wzgórzach Grizli.$B$BJest tu o wiele za dużo drewna, rudy, zwierzyny i strategicznego terenu, byśmy mogli odpuścić którykolwiek front.$B$BJak dotąd odnosimy sukcesy... ale jest coś, co mogłoby przechylić szalę na korzyść wroga.$B$BDaleko na wschód stąd, w Posterunku Skraju Lasu, miejscowi traperzy chcą dołączyć do Przymierza. Wyrżnij ich, zanim zdążą to zrobić.', 'Zdobywczyni Krenna w Warowni Podboju chce, żebyś $gzabił:zabiła; 8 łowców ze Srebrnego Potoku i ich przywódcę, Vladeka, w Posterunku Skraju Lasu.', '', 'Wróć do zdobywczyni Krenny w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12413, 'koKR', 'Atak na Srebrny Potok', 'Jeszcze kilka godzin temu traperzy byli tylko chłopstwem, które groziło, że zasili szeregi Przymierza.$B$BTeraz stali się czymś innym... niewiadomą. Nie lubię niewiadomych. Udaj się na wzgórza pod ich głównym miasteczkiem na północy Wzgórz Grizli, Srebrnym Potokiem, i pomóż moim ludziom ich zmiażdżyć.', 'Zdobywczyni Krenna w Warowni Podboju chce, żebyś $gzabił:zabiła; 8 obrońców Srebrnego Potoku na Wzgórzach Srebrnego Potoku.', '', 'Wróć do zdobywczyni Krenny w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12414, 'koKR', 'Na koń!', 'Kapitan Mocnopłaszcz zostawił większość naszej kalwe... kawel... eee, konnicy w bitwie o Zatokę Gitgeszeft.$B$BWybraliśmy dobre miejsce na obóz, bo tu w okolicy i na Głazowych Wzgórzach na północnym wschodzie biega mnóstwo górskich mustangów. Kapitan kazał mi schwytać parę z nich.$B$BPomożesz? Mam kij i trochę sznurka, a przy obozie rośnie cała masa dzikiej marchwi. Nazrywaj marchwi, użyj jej z kijem, żeby zwabić mustanga, a potem przyjedź na nim tutaj.', 'Przyprowadź 5 górskich mustangów giermkowi Percy\'emu w Obozowisku Brygady Zachodniego Skraju.', '', 'Wróć do giermka Percy\'ego w Obozowisku Brygady Zachodniego Skraju we Wzgórzach Grizli.', 'Przyprowadzone górskie mustangi', '', '', '', 0),
(12415, 'koKR', 'Zakrzykiwacz koni', '„Brygada Zachodniego Skraju” Przymierza obozuje daleko na północy, niedaleko Thor Modan. Głupio podzielili swoje siły, by podważyć naszą władzę nad Zatoką Gitgeszeft, i zostali bez konnicy.$B$BTeraz próbują schwytać i oswoić dzikie górskie mustangi, które wędrują w okolicy Obozowiska Brygady Zachodniego Skraju i Głazowych Wzgórz. Musimy ich powstrzymać, zanim zdołają zastąpić utracone wierzchowce. Weź to i rzuć w pobliżu koni, żeby je rozpędzić.', 'Przestrasz 15 górskich mustangów i wróć do Souloka Burzowej Furii w Obozie Oneqwah.', '', 'Wróć do Souloka Burzowej Furii w Obozie Oneqwah we Wzgórzach Grizli.', 'Przestraszone górskie mustangi', '', '', '', 0),
(12422, 'koKR', 'Taktyczna łaska', 'Słuchaj, $N. Musisz działać dyskretnie i szybko.$B$BJeden z najlepszych sierżantów Krenny pojmał wygnaną traperkę pod Srebrnym Potokiem. Jeśli wszystko potoczy się jak zwykle, więźniarka zostanie stracona, zanim skończy się dzień.$B$BNie możemy do tego dopuścić. Widzisz, więźniarka pasuje do opisu starszej córki Mikhaila z jego dziennika.$B$BJeśli ją wypuścimy i będziemy uważnie za nią iść, doprowadzi nas do tego, kto kontroluje traperów. Zanieś jej ten list.', 'Dostarcz Akt amnestii pojmanej traperce na Wzgórzach Srebrnego Potoku.', '', 'Wróć do pojmanej traperki na Wzgórzach Srebrnego Potoku we Wzgórzach Grizli.', '', '', '', '', 0),
(12423, 'koKR', 'Dziennik Mikhaila', 'Z tego, co udaje ci się ustalić, dziennik napisał mieszkaniec Srebrnego Potoku imieniem Mikhail.$B$BNapisano go w jakiejś odmianie wspólnej mowy ludzi. Może warto zanieść go zdobywczyni Krennie.', 'Zanieś Dziennik Mikhaila zdobywczyni Krennie w Warowni Podboju.', '', 'Wróć do zdobywczyni Krenny w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12424, 'koKR', 'Gorgonna', 'Ta książka jest napisana w świńskiej mowie, której używają ludzie. Trzeba ją natychmiast spalić.$B$BOddaj ją mojej siostrze Gorgonnie i nie marnuj mojego czasu.', 'Zanieś Dziennik Mikhaila Gorgonnie w Warowni Podboju.', '', 'Porozmawiaj z Gorgonną we Wzgórzach Grizli.', '', '', '', '', 0),
(12425, 'koKR', 'Ruuna Ślepa', 'Ta sprawa z traperami może być ważniejsza, niż zakładaliśmy.$B$BJeśli nie są z Przymierzem, to całkiem możliwe, że są z Plagą, a to mogłoby oznaczać kłopoty.$B$BNasze wcześniejsze starania mogły się jednak opłacić. Zauważyliśmy, jak nasza była branka spotyka się z jakąś wróżbitką, zanim straciliśmy ją z oczu.$B$BJestem teraz niemal pewna, że jeśli znów ją znajdziemy, zaprowadzi nas do ich przywódcy. Odszukaj Ruunę Ślepą i zobacz, czego się dowiesz.', 'Porozmawiaj z Ruuną Ślepą w Obozie Ruuny niedaleko Przełęczy Vordrassila.', '', '', '', '', '', '', 0),
(12427, 'koKR', 'Dół Podboju: zapasy z niedźwiedziem!', 'Więc interesują cię walki, co? Cóż, Krenna zakazała walk w dole wszystkim zaciągniętym wojownikom. Ale ty, mój przyjacielu, formalnie działasz na własną rękę i ten zakaz cię nie obejmuje.$B$BNiezła furtka, co?$B$BW każdym razie, jeśli chcesz, mogę zacząć od czegoś łatwego – od marnego niedźwiedzia. Pozwolę ci nawet przyprowadzić przyjaciół!', 'Pokonaj Żelaznoskórego w Dole Podboju i porozmawiaj z bukmacherem Vel\'jenem, by odebrać nagrodę.', 'Pokonany Żelaznoskóry', 'Wróć do bukmachera Vel\'jena w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12428, 'koKR', 'Dół Podboju: walka z szalonym furbolgiem', 'Nieźle sobie radzisz. Naprawdę nieźle.$B$BMyślisz, że dasz radę furbolgowi? A co powiesz na jednego z tych ekstra dużych, obłąkanych furbolgów z Północnej Grani?$B$BDobrze, dobrze. Zbierz swoją ekipę i ruszaj na ring. Dajmy tym ludziom widowisko... może przy okazji zarobimy trochę więcej grosza.', 'Pokonaj Torgga Gromowego Totema w Dole Podboju i porozmawiaj z bukmacherem Vel\'jenem, by odebrać nagrodę.$B', 'Pokonany Torgg Gromowy Totem', 'Wróć do bukmachera Vel\'jena w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12429, 'koKR', 'Dół Podboju: krew i metal', 'Miło mieć tu w okolicy prawdziwego wojownika... przez ostatnie kilka tygodni mieliśmy tylko więźniów i bestie z klatek. Ludzie się nudzą, wiesz?$B$BW każdym razie twoim następnym wyzwaniem jest prawdziwy żelazny golem, wykradziony z głębin Thor Modan... myślisz, że dasz radę?', 'Pokonaj Rdzawokrwistego w Dole Podboju i porozmawiaj z bukmacherem Vel\'jenem, by odebrać nagrodę.$B', 'Pokonany Rdzawokrwisty', 'Wróć do bukmachera Vel\'jena w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12430, 'koKR', 'Dół Podboju: śmierć prawdopodobna', 'Powiem ci wprost, $gmały:mała;. Następny zawodnik to morderca.$B$BDosłownie.$B$BMiał być stracony w zeszłym tygodniu, ale udusił kata lewą ręką, więc strażnicy Krenny jakby mi go odstąpili.$B$BMożesz spokojnie odpuścić tę walkę. Nie miałbym ci tego za złe.', 'Pokonaj Horgrenna Piekłoręba w Dole Podboju i porozmawiaj z bukmacherem Vel\'jenem, by odebrać nagrodę.$B', 'Pokonany Horgrenn Piekłorąb', 'Wróć do bukmachera Vel\'jena w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12431, 'koKR', 'Dół Podboju: ostateczne starcie', '$GMusiałeś:Musiałaś; nieźle wkurzyć Krennę. Pokłóciła się z Gorgonną, a ty masz się natychmiast stawić w dole.$B$BKrążą dzikie plotki, że to walka na śmierć i życie! Dla ciebie to kiepska wiadomość, ale dla naszego interesu świetna!$B$BTak czy inaczej, przed losem nie uciekniesz... lepiej wskakuj tam szybko i miej to z głowy.', 'Pokonaj Krennę w Dole Podboju i porozmawiaj z Gorgonną, by odebrać nagrodę.', '', 'Wróć do Gorgonny w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12432, 'koKR', 'Przejażdżka na czerwonej rakiecie', 'Hej, ty! Rusz tu swoje nędzne cielsko!$b$bPrzymierze ma ładunek drewna gotowy do transportu tuż na północny wschód stąd. Skoro nie ma mowy, żebyśmy położyli na nim łapy, zostaje tylko jedno – zniszczyć go!$b$bGoblin na końcu tego pomostu ma kilka torped gotowych do drogi. Całe paliwo do nich trzyma na goblińskim statku zacumowanym na północy.$b$bZdobądź trochę paliwa, a potem przejmij jedną z torped i wjedź nią w ich statek.$b$bOdmaszerować!', 'Generał Gorlok przy latarni morskiej w Zatoce Gitgeszeft chce, żebyś $gzniszczył:zniszczyła; łódź z drewnem Przymierza.$b$bGenerał Gorlok jest przy latarni tylko wtedy, gdy znajduje się ona w rękach Hordy.', '', 'Wróć do generała Gorloka w Zatoce Gitgeszeft we Wzgórzach Grizli.', 'Zniszczony ładunek drewna Przymierza', '', '', '', 0),
(12433, 'koKR', 'W poszukiwaniu rozpuszczalnika', 'Ech! Znowu. Kolejna przepalona uszczelka...$b$bZa każdym razem, gdy któraś pada, smar zakleja wszystkie tryby. Bez rozpuszczalnika czyszczenie trwa godzinami.$b$bWiesz co? Na barce spółki Gitgeszeft w tamtym doku jest wymyślne paliwo rakietowe – chyba nazywają je pierwiastkiem 115. To świetny rozpuszczalnik.$b$bPrzynieś mi go trochę, a nie pożałujesz.', 'Gurtor w bazie Hordy w Zatoce Gitgeszeft chce, żebyś $gprzyniósł:przyniosła; mu kanister Pierwiastka 115.', '', 'Wróć do Gurtora w Zatoce Gitgeszeft we Wzgórzach Grizli.', '', '', '', '', 0),
(12434, 'koKR', 'Wciąż w poszukiwaniu rozpuszczalnika', '', '', '', 'Wróć do Gurtora we Wzgórzach Grizli.', '', '', '', '', 0),
(12436, 'koKR', 'Dodatkowy dochód', 'Witaj. Przekonasz się, że tu, w Warowni Podboju, kupujemy i sprzedajemy to, co Krenna chce, żebyśmy kupowali i sprzedawali... po cenie, po jakiej Krenna chce, żebyśmy kupowali i sprzedawali.$B$BTo wszystko dławi interesy. Liczę, że zarobię trochę grosza na boku i przy okazji nakarmię naszych siepaczy. Może byś tak $gzapolował:zapolowała; na jelenie i $gprzyniósł:przyniosła; mi dziczyznę?$B$BJest ich w okolicy mnóstwo, więc przynoś mi tylko najlepsze mięso.', 'Zaopatrzeniowiec Lorkran w Warowni Podboju chce, żebyś $gzdobył:zdobyła; 5 kawałków soczystej dziczyzny z pobliskich jeleni wysokorogich.', '', 'Wróć do zaopatrzeniowca Lorkrana w Warowni Podboju we Wzgórzach Grizli.', '', '', '', '', 0),
(12437, 'koKR', 'Przejażdżka na czerwonej rakiecie', 'Słuchaj, $N. W tej bitwie chodzi tyleż o surowce, co o przewagę taktyczną.$b$bMam misję, która może odwrócić losy naszej walki z Hordą.$b$bNa końcu pomostu są torpedy, których możemy użyć, by zatopić statek Hordy z drewnem na północnym zachodzie.$b$bMusisz zdobyć trochę paliwa ze statku goblinów zacumowanego tuż na północ stąd, a potem wjechać jedną z torped w ich transportowiec!', 'Komendant Howser przy latarni morskiej w Zatoce Gitgeszeft chce, żebyś $gzniszczył:zniszczyła; ładunek drewna Hordy.$b$bKomendant Howser jest przy latarni tylko wtedy, gdy znajduje się ona w rękach Przymierza.', '', 'Wróć do komendanta Howsera w Zatoce Gitgeszeft we Wzgórzach Grizli.', 'Zniszczona łódź z drewnem Hordy', '', '', '', 0),
(12443, 'koKR', 'W poszukiwaniu rozpuszczalnika', 'Ech! Znowu. Kolejna przepalona uszczelka...$b$bZa każdym razem, gdy któraś pada, smar zakleja wszystkie tryby. Bez rozpuszczalnika czyszczenie trwa godzinami.$b$bWiesz co? Na barce spółki Gitgeszeft w tamtym doku jest wymyślne paliwo rakietowe – chyba nazywają je pierwiastkiem 115. To świetny rozpuszczalnik.$b$bPrzynieś mi go trochę, a nie pożałujesz.', 'Barblefink w bazie Przymierza w Zatoce Gitgeszeft chce, żebyś $gprzyniósł:przyniosła; mu kanister Pierwiastka 115.', '', 'Wróć do Barblefinka w Zatoce Gitgeszeft we Wzgórzach Grizli.', '', '', '', '', 0),
(12444, 'koKR', 'Potyczka nad Czarną Rzeką', 'Spółka Gitgeszeft wynosi się ze Wzgórz Grizli. Prowadzili tu wyręby, ale zrobiło się dla nich trochę za niebezpiecznie.$B$BIch porzucone obozy są do wzięcia, a my, do diabła, nie możemy pozwolić, żeby Horda położyła na nich łapy.$B$BObóz Drwali Czarnej Rzeki to najmniejszy z trzech obozów drwali w tej krainie, ale i tak go potrzebujemy. Zrób swoje i odeprzyj siły Hordy. Każde drewno, które tu zdobędą, zamienią w broń, której użyją przeciw nam gdzie indziej.', 'Kapitan zwiadowców Carter chce, żebyś $gzabił:zabiła; 10 żołnierzy lub graczy Hordy w Obozie Drwali Czarnej Rzeki.', '', 'Wróć do kapitana zwiadowców Cartera we Wzgórzach Grizli.', 'Zabici członkowie Hordy nad Czarną Rzeką', '', '', '', 0),
(12446, 'koKR', 'Wciąż w poszukiwaniu rozpuszczalnika', '', '', '', 'Wróć do Barblefinka w Zatoce Gitgeszeft we Wzgórzach Grizli.', '', '', '', '', 0),
(12451, 'koKR', 'Naprzód, do Obozu Oneqwah', 'Kiedy budowaliśmy Warownię Podboju, wysłałem zwiadowcę Vor\'takha, by nawiązał kontakt z naszymi sojusznikami taunka na wschodzie. Ich bazą jest Obóz Oneqwah we wschodnim krańcu Wzgórz Grizli, za Siwopaszczą.$B$BWybierz się tam, wysłuchaj raportu Vor\'takha i zaoferuj pomoc we wszystkim, czego mogą potrzebować on i miejscowy wódz. Twój wkład w Warownię Podboju był wzorowy i wiem, że Vor\'takh będzie wdzięczny za pomoc.', 'Porozmawiaj ze zwiadowcą Vor\'takhiem w Obozie Oneqwah.', '', '', '', '', '', '', 0),
(12453, 'koKR', 'Oczy z góry', 'Poproszono mnie o wsparcie naszych działań przeciw Przymierzu. Obecnie nasze siły zbrojne są mniej więcej wyrównane i szukamy sposobów, by zyskać przewagę.$B$BCesarskie orły, które latają nad górami i drzewami w tej okolicy, byłyby dla nas doskonałymi zwiadowcami. Weź to srebrne pióro i użyj go, by związać mój wzrok z ich wzrokiem.$B$BMożliwość śledzenia ruchów wroga da nam przewagę strategiczną, której potrzebujemy. Mnóstwo orłów znajdziesz w górach na wschodzie.', 'Wieszczka wiatru Szary Róg chce, żebyś $gużył:użyła; Srebrnego pióra na 6 cesarskich orłach we Wzgórzach Grizli.', '', 'Wróć do wieszczki wiatru Szary Róg w Warowni Podboju we Wzgórzach Grizli.', 'Związany wzrok cesarskiego orła', '', '', '', 0),
(12468, 'koKR', 'Zadanie zdobywczyni', 'Horda to wspaniała machina wojenna, a ty jesteś w niej tylko trybikiem.$B$BOdpowiadam za zapewnienie tej machinie paliwa. Jeśli zawiodę, zawiedzie machina.$B$BDrewno, ruda, woda... wszystko tu jest i my tego chcemy. Przymierze również.$B$BZanim ruszymy przeciw ludzkiej hołocie, musimy umocnić naszą kontrolę nad zachodnią częścią regionu.$B$BPorozmawiaj z sierżantem Nazgrimem o wytępieniu wrykułów w Voldrune, a potem może – jeśli nie okażesz się $gkompletnym nieudacznikiem:kompletną nieudacznicą; – wyślemy cię na kolejne zadania.', 'Porozmawiaj z sierżantem Nazgrimem w Warowni Podboju.', '', '', '', '', '', '', 0),
(12483, 'koKR', 'Gulasz z lśniogrzybów', 'Słuchaj, skoro już tu jesteś, może pomożesz staremu Prigmonowi w drobnej robótce? Mam kumpla, co robi zabójczy gulasz – takiego jeszcze nie $gjadłeś:jadłaś;!$b$bPotrzebuje paru składników, co rosną w tych stronach. Są w ruinach na południowym zachodzie i w obozie tuż na północ stąd.$b$bCo ty na to, mon?', 'Prigmon w Granitowych Źródłach chce, żebyś $gzebrał:zebrała; 5 lśniących śniegogrzybów i 5 oczu lodowego węża w Ruinach Drak\'Zin oraz 5 słodkich korzeni w Zeb\'Halak.', '', 'Wróć do Prigmona w Granitowych Źródłach we Wzgórzach Grizli.', '', '', '', '', 0),
(12484, 'koKR', 'Szaszłyk z Plagi', 'Ech.$b$bOwijanie tych nieszczęsnych trolli łamie mi serce, ale jeszcze bardziej krzyż!$b$bPomóż staremu Prigmonowi i zanieś jedno z tych truchł do Macka.$b$bJak ich nie spalimy, w mig znowu zaczną chodzić.', 'Prigmon w Granitowych Źródłach chce, żebyś $gzaniósł:zaniosła; zmumifikowane truchło trolla Mackowi Fearsenowi i $gwrzucił:wrzuciła; je do ognia.', '', 'Wróć do Macka Fearsena w Granitowych Źródłach we Wzgórzach Grizli.', 'Spalone zmumifikowane truchło', '', '', '', 0),
(12763, 'koKR', 'Zmiana priorytetów', 'Choć nasze potrzeby tutaj są pilne, z krain na północy nadeszły wieści, których nie można zignorować.$b$bWłaśnie dostałem wiadomość od Krucjaty Argentu. Wygląda na to, że gromadzą się tam siły Plagi i grożą zalaniem Zul\'Draku.$b$bNie muszę chyba mówić, $N, że gdyby do tego doszło, nasza walka tutaj straciłaby sens. Musisz tam wyruszyć i pomóc krzyżowcom odeprzeć armie Króla Lisza.$b$bPorozmawiaj z Makki, kiedy będziesz $ggotów:gotowa; do drogi.', 'Zwiadowca Vor\'takh chce, żebyś $gudał:udała; się do Zul\'Draku i $gzameldował:zameldowała; się u sierżant Riannah w Wyłomie Światłości.$b$bMakki Zimowa Wichura w Obozie Oneqwah zapewni ci transport.', '', '', '', '', '', '', 0),
(12770, 'koKR', 'Przesunięcie sił', 'Słuchaj no, $N!$b$bTwoje dni tutaj są policzone. Choć potrzebujemy w szeregach zdolnych ludzi, na północy są kłopoty, przy których nasze problemy wyglądają jak letnia parada w Wichrogrodzie.$b$bOkazuje się, że Plaga skupia siły – szykuje wielkie natarcie, by opanować Zul\'Drak. Jeśli do tego dojdzie, równie dobrze możemy się zwijać.$b$bMożesz dokończyć tu swoje sprawy, ale potem ruszasz do Wyłomu Światłości. Porozmawiaj z Samuelem, jeśli potrzebujesz transportu.$b$bOdmaszerować.', 'Gryan Mocnopłaszcz chce, żebyś $gzameldował:zameldowała; się u sierżant Riannah w Wyłomie Światłości w Zul\'Draku.$b$bTransport do Wyłomu Światłości zapewni ci Samuel Clearbook.', '', '', '', '', '', '', 0),
(12802, 'koKR', 'Moje serce w twoich rękach', '<Głos Drakuru wypełnia twój umysł.>$b$bHej, mon! To oko proroków jest świetne! Obserwowałem cię przez nie i widzę, że masz już serce! Nieźle...$b$bTeraz musisz tylko zanieść je do mojej kadzielnicy w Przesmyku Drak\'atal, kawałek na wschód od ciebie.$b$bMusisz wypić mój eliksir przy piedestale, żeby mnie tam przywołać. Tym razem, żeby zadziałał, musisz do niego dodać trochę rozpaczliwego mojo od tamtejszych obrońców.', 'Drakuru chce, żebyś $gprzyniósł:przyniosła; mu Serce Pradawnych do Przesmyku Drak\'atal.$b$bAby użyć tam eliksiru, musisz zebrać 5 rozpaczliwych mojo.', '', '', '', '', '', '', 0),
(13129, 'koKR', 'Gierki z głową', 'Leniwi, że aż szkoda gadać... Czekaj! Wiem, jak ich nauczyć rozumu!$b$b<Kurzel oddziera długi pas materiału ze swojej bluzki i wręcza ci go.>$b$bMasz, weź to. Zanurz go w szczątkach tamtego wstrętnego lisza i zanieś Mackowi do obozu.$b$bKiedy chłopcy trochę się podręczą wyrzutami sumienia, pojawię się i dam im spokój.$b$bNauczą się, że nie pozwala się damie łazić samej!', 'Kurzel chce, żebyś $gużył:użyła; Skrawka bluzki Kurzel na zwłokach Novosa Przywoływacza, a potem $gzaniósł:zaniosła; Płótno poplamione posoką Mackowi.', '', 'Wróć do Macka Fearsena w Granitowych Źródłach we Wzgórzach Grizli.', '', '', '', '', 0),
(13524, 'koKR', 'Ucieczka ze Srebrnego Potoku', 'Ty... nie jesteś jednym z nich? Szybko! Wypuść mnie!$B$BMusimy natychmiast dotrzeć do Chaty Bursztynowej Sosny! Kiedy porucznik Dumont się dowie, kim naprawdę są ci ludzie, z tego miasteczka zostanie kupa gruzu!', 'Otwórz Drewnianą klatkę i pomóż uwolnionemu zwiadowcy Przymierza uciec ze Srebrnego Potoku. Gdy dotrzesz do Chaty Bursztynowej Sosny, zamelduj się u porucznika Dumonta.', '', '', 'Ucieczka ze Srebrnego Potoku', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(11981, 'koKR', '<Opowiadasz Kurunowi o wiadomości, którą przekazał ci poległy ziemny.>$B$BWalczą dzielnie, ale on ma rację. Bez pomocy nie pokonamy żelaznych krasnoludów z Thor Modan. Moje olbrzymy i ziemni od dawna zmagają się ze złem żelaza, ale nasze siły są zbyt nieliczne, by wygrać bitwę o Thor Modan. Pomożesz nam?', 0),
(11982, 'koKR', 'Żelazne krasnoludy odgruzowują rów równie szybko, jak my go zasypujemy. Sam atak z góry nie zdobędzie miasta. Musisz pomóc ziemnym, którzy walczą na placu w dole.', 0),
(11984, 'koKR', 'Świetna robota, $N. Wygląda na to, że Budd jeszcze trochę z nami zostanie.$b$bZaraz ktoś odbierze twoją klatkę. Oto twoja część nagrody.$b$bA, i witaj w obozie. Zostań trochę, na pewno znajdziemy dla ciebie jakieś zajęcie...', 0),
(11985, 'koKR', 'Dobra robota, $N. Utrata dowódcy żelaznych krasnoludów powinna złamać pozostałych obrońców. Ziemni powinni sobie poradzić z tymi, którzy przeżyli.', 0),
(11986, 'koKR', '$GZnalazłeś:Znalazłaś; dziennik Branna? Niesamowite! Liga od dawna nie dostała od niego żadnego raportu i zaczęliśmy się bać, że go pojmano albo zabito. Co odkrył w Thor Modan?', 0),
(11988, 'koKR', '<Torthen szybko składa przyniesione przez ciebie fragmenty.>$B$BNie jest kompletny, ale i tak powinien pozwolić nam odczytać z płyty większość informacji.', 0),
(11989, 'koKR', 'No!$b$bTeraz łączy nas krew, mon. Prawdziwa więź, co nie.$b$bSłuchaj Drakuru uważnie. Dużo jest do zrobienia.', 0),
(11990, 'koKR', '<Drakuru bierze składniki i zręcznie łączy je w fiolce.>$b$bTo powinno wystarczyć, mon. Teraz czas brać się do roboty.', 0),
(11991, 'koKR', 'Aaa, tak. Dobrze się $gspisałeś:spisałaś;, mon.$b$bStąd świetnie czytam te ściany...', 0),
(11993, 'koKR', '<Torthen słucha, jak opowiadasz o treści runicznych płyt.>$B$BNa młot Madorana, odkrył całe nowe miasto tytanów!$B$B„Kolebka kamienia i żelaza”.$B$B„Ulduar ukryty w burzy”.$B$BJak myślisz, co to znaczy? Czy to może stamtąd pochodzimy, po tylu latach?$B$BMusimy za nim pójść! Musimy go odnaleźć!', 0),
(11998, 'koKR', 'Niech no to sobie poukładam – nieznajomy przynosi mi baryłkę najlepszej gorzały w tym nędznym lesie. No dobrze, to o co ci chodzi?', 0),
(12002, 'koKR', '<Brugar wysłuchuje twojego raportu.>$B$BWygląda na to, że sytuacja trochę się tam uspokaja. Zaczniemy szukać wejść do systemu tuneli żelaznych krasnoludów.', 0),
(12003, 'koKR', '<Brugar wyrzuca z siebie potok plugawych krasnoludzkich słów.>$B$BŻadnych wejść? Ani jednego?$B$BNo tak, oczywiście, nie mogło być tak łatwo. Cóż, chyba nie unikniemy wypadu do samego miasta. Moi chłopcy nigdy nie wrócą do swojej prawdziwej roboty.', 0),
(12007, 'koKR', 'To jest to, mon!$b$bJeszcze cenniejsze, niż się spodziewałem. To na pewno da mojemu ludowi nadzieję w tych mrocznych czasach.$b$bNie ma czasu do stracenia. Zobaczmy, gdzie ukrywa się następny artefakt.', 0),
(12010, 'koKR', 'Szybkie oględziny ciała pokazują, że mierniczy nie żyje od jakiegoś czasu. Przeszukując jego plecak, natrafiasz na odręczne notatki Orlonda.', 0),
(12014, 'koKR', '<Brugar przegląda raport.>$B$BTo wcale nie wygląda dobrze. Nawet gdybyśmy odkopali tunele za zawałem, nie ma gwarancji, że nie zawalą się znowu. Wygląda na to, że części z nich nie używano od pokoleń. Będziemy musieli przekazać kapitanowi Gryanowi złe wieści.', 0),
(12026, 'koKR', 'Kim jest ten Brann Miedziobrody? Żelazne krasnoludy nie widziały powodu, by z nim pertraktować, ale nie mam pojęcia, czemu miałyby nas interesować jego zapiski.', 0),
(12027, 'koKR', 'Całe szczęście, że $gznalazłeś:znalazłaś; Emmy! Kiedy poszła beze mnie, bałem się, że się zgubi.$B$BCieszę się też, że Pan Kłapuś wrócił cały i zdrowy.', 0),
(12029, 'koKR', 'Dobra robota!$b$b<Mack przez chwilę śmieje się histerycznie.>$b$bNo weź, no. To było śmieszne...<hik>.', 0),
(12037, 'koKR', 'Wiedziałam!$B$BNawet moje zaginięcie nie wystarczyło, żeby te bezkręgowe łasice tu po mnie przyszły.$B$BNo cóż, przysłali ciebie. To chyba już coś...$B$BMasz, weź to. Wolę, żeby trafiło do ciebie niż do tych przygłupów w obozie.', 0),
(12038, 'koKR', 'Dobra robota!$B$B<Mack przez chwilę śmieje się histerycznie.>$B$BNo weź, no. To było śmieszne... hik.', 0),
(12042, 'koKR', 'Ten nieszczęsny goblin musiał wykopać Serce Pradawnych podczas swoich prac w tej okolicy.$b$bZ pewnością nie miał pojęcia, czym ono jest.$b$bDochodzisz do wniosku, że musiano je przeoczyć w chaosie, który ogarnął okolicę.', 0),
(12054, 'koKR', 'Dobra robota, $N. Przygotuję kadzidło, a potem zobaczymy, co dokładnie ten królewski krasnolud robił tak daleko od domu.', 0),
(12058, 'koKR', '<Mędrczyni Paluna słucha, jak przytaczasz tłumaczenia płyt.>$B$BWięc Brann uważa, że odkrył nowe miasto tytanów?$B$B„Kolebka kamienia i żelaza”.$B$B„Ulduar ukryty w burzy”.$B$BPoproszę wodza, by wysłał gońców na Burzowe Szczyty. Mój lud dobrze zna te ziemie i ma największe szanse na wytropienie tego krasnoluda włóczęgi.', 0),
(12068, 'koKR', 'Udało się, $N!$b$bMamy wszystkie składniki potrzebne do rytuału oczyszczenia.', 0),
(12070, 'koKR', '$GDałeś:Dałaś; naszym sojusznikom siłę do dalszej walki i masz za to moją wdzięczność. Mimo to musimy zacząć planować, jak zakończyć tę bitwę, zanim nas zaleją.', 0),
(12073, 'koKR', '<Zwiadowca Vor\'takh się uśmiecha.>$B$BWięc Thor Modan jest bliskie upadku?$B$BDobrze. Wkrótce zwrócimy uwagę na Dun Argol.', 0),
(12074, 'koKR', '<Przedstawiasz się Kurunowi.>$B$BWięc synowie żelaza to także twoi wrogowie?$B$BMoje siły zamknęły żelazne krasnoludy w ich mieście, ale przydałaby się pomoc w dalszym natarciu. Pomożesz nam?', 0),
(12081, 'koKR', 'Wiem, że Kurun cieszy się z twojej pomocy. Pokonanie Thor Modan będzie dla nas wielkim osiągnięciem, ale nie uwolni naszych braci.', 0),
(12082, 'koKR', 'No i co, $gprzeżyłeś:przeżyłaś; małą przygodę z naszym dobrym kumplem, co?$b$bTo już samo w sobie powinno być nagrodą, ale masz – mam dziś hojny dzień.', 0),
(12093, 'koKR', 'Dobrze. Teraz musimy działać szybko, zanim synowie żelaza zorientują się, że ich runy stały się nieszkodliwe.', 0),
(12094, 'koKR', 'Wyczuwam moc, którą $gnasyciłeś:nasyciłaś; odłamek, i mam nadzieję, że wystarczy, by złamać runiczną magię.', 0),
(12099, 'koKR', 'Więc to niepewna sprawa? Wolałbym, żeby nie zależało to od przypadku, ale przynajmniej jesteśmy na dobrej drodze. Bez twojej pomocy nigdy nie byłoby to możliwe. Jeśli dowiesz się czegoś więcej o knowaniach żelaznych krasnoludów i ich planach wobec dzieci kamienia, odszukaj nas, a wysłuchamy cię, $N.', 0),
(12105, 'koKR', 'Spodziewałem się, że kryje się za tym coś więcej niż tylko odosobnione wrogie miasteczko.$B$BMamy ludzi niedaleko Kopalni Wydrążonego Kamienia, może warto by było trochę to zbadać.', 0),
(12109, 'koKR', 'Dumont cię przysłał? Bardzo dobrze. Zobaczmy, co możesz dla nas zrobić.', 0),
(12113, 'koKR', 'Wyśmienicie!$b$bNic tak nie pasuje do kufla jak gorący kęs mięsa.', 0),
(12114, 'koKR', 'Dzięki, $N.$b$bJak znajdę chwilę, to wstanę i sam się rozejrzę.', 0),
(12116, 'koKR', 'Wnętrzności? Ciekawy wybór.$b$bKraz zobaczy, czego można się z nich dowiedzieć. Dziękuję, że $gstawiłeś:stawiłaś; czoła głębinom tego miejsca.', 0),
(12120, 'koKR', 'Jak dotąd dobrze ci idzie, $N, ale teraz nadchodzi prawdziwa próba.', 0),
(12121, 'koKR', 'Twoje przybycie zostało przepowiedziane, $gprzyjacielu:przyjaciółko;. Dobrze, że $gprzybyłeś:przybyłaś;.', 0),
(12128, 'koKR', 'Hmm... nie wyglądasz na asystenta badawczego, i dobrze. Żelazne krasnoludy chyba szykują się do wojny, a mój zespół badawczy nie wrócił. Przydałaby się nam tu pomoc.', 0),
(12129, 'koKR', 'Masz wszystkie? Wspaniale! Nie mogę się doczekać, jakie miny zrobią, kiedy golem będzie gotowy.', 0),
(12130, 'koKR', '<Raegar ociera czoło wierzchem dłoni.>$B$BO nie. To będzie trudniejsze, niż myślałem. Te rzeczy nie mają numerów seryjnych ani niczego takiego, co?$B$BNigdy nie ma gnoma pod ręką, kiedy jest potrzebny...', 0),
(12131, 'koKR', '<Raegar bierze od ciebie ogniwa.>$B$BŚwietnie! Powinniśmy być gotowi do drogi.', 0),
(12134, 'koKR', 'Zabijanie tych potworów nie przywróci mi ojca... ale nie o to teraz chodzi, prawda?', 0),
(12137, 'koKR', 'Dobrze się $gspisałeś:spisałaś;.$b$bProszę, usiądź i posłuchaj. Musimy omówić wiele spraw.', 0),
(12138, 'koKR', 'Nareszcie gotowy. Mam tylko nadzieję, że wytrzyma w jednym kawałku, dopóki nie zrobi swojego. Jeśli nie zlikwidujemy thana, który dowodzi Dun Argol, kapitana Gryana czeka paskudna niespodzianka.', 0),
(12152, 'koKR', 'Dokonało się.$b$bTwoja bezinteresowność dała wieczny spokój wielu duszom i zakończyła całe epoki cierpienia.$b$bNiech ten czyn ulży twojej duszy i zmniejszy twoje brzemię, bo widzę, że czeka cię jeszcze wiele niebezpieczeństw.$b$bŻegnaj, $N.', 0),
(12153, 'koKR', 'Udało się?$B$B<Raegar odchrząkuje.>$B$BZnaczy... oczywiście, że się udało! To niesamowite!$B$BZa wiele lat nowicjusze Ligi Odkrywców będą słuchać opowieści o tym, jak Raegar Łamibrew, $N i jakiś golem ze złomu pokonali thana Dun Argol!', 0),
(12154, 'koKR', '<Raegar kiwa głową z aprobatą.>$B$BNie znoszę, gdy materiały wybuchowe się marnują, a to na pewno cofnie naszych wrogów.', 0),
(12158, 'koKR', '$GPrzyszedłeś:Przyszłaś; mi pomóc, prawda?!', 0),
(12159, 'koKR', 'Spoczywajcie w pokoju, przyjaciele! Nie martwcie się – powiem wszystkim, że nigdy się nie poddaliśmy!', 0),
(12160, 'koKR', 'Niech to licho. Znajdujemy jedyną działającą kopalnię po tej stronie wzgórz, a ona jest pełna Plagi.$B$BBez urazy, $gprzyjacielu:przyjaciółko;. Ale ten ocalały, którego $gznalazłeś:znalazłaś;, jest chyba trochę straumatyzowany utratą przyjaciół. Arugal nie żyje od lat... Sam kiedyś widziałem jego grób.', 0),
(12161, 'koKR', 'Szukasz wiedzy poza swoim zasięgiem, więc $gprzyszedłeś:przyszłaś; do mnie. Muszę cię ostrzec, $gnieznajomy:nieznajoma;, odpowiedzi, których udzielę, mogą ci się nie spodobać.', 0),
(12164, 'koKR', 'Nieźle go załatwiliśmy, $N. Ale nie dość dobrze.$B$BJedno jest pewne... już nie zobaczymy go w tych stronach.', 0),
(12165, 'koKR', 'Więc Tormak jednak zrealizuje ten plan? Pewnie by cię nie przysłał, gdyby było inaczej.$B$BA niech to... Jak ja mam teraz wymyślić, jak to złożyć, pod taką presją?', 0),
(12170, 'koKR', 'Dobra robota, $N. Może jeszcze nie kontrolujemy w pełni obozu drwali, ale dzięki tobie jesteśmy o krok bliżej zmiażdżenia tych robaków z Przymierza.', 0),
(12175, 'koKR', 'Ratujesz mi życie, $Gbracie:siostro;. Jak chcesz więcej roboty, to jeszcze trochę się jej znajdzie.', 0),
(12176, 'koKR', 'Jestem twoim dłużnikiem, mon. Weź to jako zapłatę.', 0),
(12177, 'koKR', 'Miejmy nadzieję, że się uda, mon.', 0),
(12178, 'koKR', 'Za kogo ty mnie masz? Te skóry pachną mąką!$B$BTo jawna zniewaga dla Hordy!', 0),
(12180, 'koKR', '<Górski strażnik Kilian słucha, jak przekazujesz mu to, co powiedzieli ci uwięzieni poszukiwacze.>$B$BWspominali o Kronusie i wojnie z kamiennymi olbrzymami? Na pewno?$B$BWięc przeczucie Raegara było trafne. Musimy znaleźć sposób, żeby się tam dostać i dowiedzieć się więcej o ich planach.', 0),
(12183, 'koKR', '<Kilian bierze od ciebie mundur.>$B$BTo powinno wystarczyć. Nie zdążę naszyć ci naszywki z wyhaftowanym „$N” ani nic w tym stylu, ale kiedy z tobą skończymy, każdy, kto dobrze ci się przyjrzy, uzna, że jesteś nadzorcą.', 0),
(12184, 'koKR', 'Dobrze, te powinny wystarczyć. Teraz trzeba przygotować zestaw, dzięki któremu przekonująco udasz żelaznego krasnoluda.', 0),
(12185, 'koKR', 'Czyżby Kronus wcale nie przesadzał? Kamienni i żelaźni synowie tytanów walczący ze sobą o władzę nad starożytnym miastem Ulduar. To szaleństwo, $N, i może zniweczyć naszą jedyną szansę, by poznać prawdziwą historię krasnoludzkiego rodu!', 0),
(12190, 'koKR', 'No proszę! Stary dobry Prigmon cię przysłał, co?$b$bBędzie z tego wyśmienite żarcie. Brakuje tylko paru rzeczy...', 0),
(12195, 'koKR', 'Te powinny wystarczyć. Zobaczmy teraz, czy to zadziała.', 0),
(12196, 'koKR', '<Rokar ociera czoło wierzchem dłoni.>$B$BOch, dzięki Światłości. Groził, że nie da mi jeść, dopóki nie wrócisz. Przejrzyjmy ten stos części i zobaczmy, co da się z nich zrobić.', 0),
(12197, 'koKR', '<Rokar bierze od ciebie ogniwa.>$B$BSą słabo naładowane, ale wystarczą, żeby uruchomić golema. Do walki jednak jeszcze mu daleko.', 0),
(12198, 'koKR', 'No, teraz Tormak nie może już narzekać. To maleństwo jest tak gotowe, jak tylko mogłem je przygotować.$B$BGdy przedrzesz się nim przez Dun Argol, ta przerośnięta krowa będzie musiała mnie wypuścić.', 0),
(12199, 'koKR', 'Więc poszukiwacz dotrzymał obietnicy? Dobrze. Zaczynałem się zastanawiać, czy całe to wygrzebywanie kawałków metalu i kradzież materiałów budowlanych do czegoś doprowadzi.$B$BSzkoda, że już na nic nam się nie przyda.', 0),
(12201, 'koKR', 'To powinno się sprawdzić, ale zostaje jeszcze reszta twojego przebrania. Nawet te tępe metalowe krasnoludy rozpoznają oszusta w kradzionym ubraniu.', 0),
(12202, 'koKR', 'To powinno wystarczyć. Na Garosza, ale te stwory są brzydkie.', 0),
(12203, 'koKR', 'Więc chce wzniecić wojnę domową między frakcjami stworzonymi przez tytanów? Dlaczego to miasto tytanów, Ulduar, tak wiele dla niego znaczy? Pewnie właśnie temu Kurun i jego olbrzymy chcą zapobiec.$B$BCóż, wątpię, byśmy mogli powstrzymać olbrzymy przed walką między sobą, ale możemy znaleźć sposób, by obrócić to na naszą korzyść. Muszę natychmiast powiadomić naszych przywódców.', 0),
(12204, 'koKR', 'Więc to on stoi za żelaznymi krasnoludami? Musimy się dowiedzieć, co rozkazuje robić żelaznym krasnoludom z Dun Argol.', 0),
(12207, 'koKR', 'Ten szlam cuchnie ciemnością znacznie starszą, niż wskazywałyby na to jego doczesne formy. Sama ziemia pamięta to zło, odkąd tylko istnieje.$B$BMusimy dowiedzieć się więcej, $N.', 0),
(12208, 'koKR', '$GPrzyszedłeś:Przyszłaś; się załapać na nagrody, co?', 0),
(12210, 'koKR', '$GPrzyszedłeś:Przyszłaś; się załapać na nagrody, co?', 0),
(12212, 'koKR', 'To wyborne kawałki mięsa!', 0),
(12213, 'koKR', 'Ta kula... została skażona przez... czysto złą siłę.$B$BCzegokolwiek jeszcze dowiem się, badając tę energię, jedno jest pewne. Muszę jak najszybciej zniszczyć tę kulę. Jej plugawiąca moc jest po prostu zbyt silna.', 0),
(12215, 'koKR', 'Dobra robota, $N.$b$bTo powinno zapewnić, że tutejsza zwierzyna skończy tam, gdzie powinna – pieczona nad naszymi ogniskami.', 0),
(12216, 'koKR', 'Wyśmienicie!$b$bNasze zapasy są już prawie uzupełnione. $GZrobiłeś:Zrobiłaś; swoje, $N.', 0),
(12217, 'koKR', 'Ponure zadanie, wiem. Ale teraz możemy spać spokojniej, wiedząc, że wróg już nas nie obserwuje.', 0),
(12219, 'koKR', 'Ten szlam nie jest naturalny, $N. Sama jego natura jest splugawiona i... zła.$B$BMusimy dowiedzieć się więcej.', 0),
(12220, 'koKR', 'Energia w kuli jest... przytłaczająca...$B$BMroczna siła skaziła ziemię w pobliżu szczątków Vordrassila. Musimy zbadać to dokładniej.', 0),
(12222, 'koKR', 'Gdy masz talizmany, smokowiec nie będzie miał wyboru i będzie ci posłuszny. Nie mogę się doczekać miny thana, gdy się zorientuje, że $gprzejąłeś:przejęłaś; jego protosmokowca.', 0),
(12223, 'koKR', 'Dobra robota, $N. Teraz musimy pójść za ciosem i wykorzystać przewagę.', 0),
(12225, 'koKR', 'Co $gzrobiłeś:zrobiłaś;?!$b$bTo były bursztynowe nasiona! I to z całych zbiorów!$b$bTe magiczne nasiona mogły rozwiązać nasz kryzys żywnościowy. Wierz mi, $N, naprawisz to!', 0),
(12226, 'koKR', 'Te powinny się nadać...$b$b<Anderhol zręcznie skręca łodygi, zbierając ich śliski sok do maleńkiej fiolki.>$b$bNo, gotowe. Czas zabrać się do rzeczy.', 0),
(12227, 'koKR', 'No i jak, $N? Wszystko wyszło jak trzeba?$b$bHmm, wygląda na to, że zdążyliśmy w ostatniej chwili...', 0),
(12229, 'koKR', 'Ta krew nosi to samo skażenie co szlam, który $gzdobyłeś:zdobyłaś; wcześniej... To nie wróży nic dobrego, $N.', 0),
(12231, 'koKR', 'Dzieci Ursoca są mądre. Ich słowa wyjaśniają wiele z tego, co dotąd widzieliśmy.', 0),
(12236, 'koKR', '<Druidka jest blada, a jej oczy patrzą pustym wzrokiem gdzieś za ciebie. W oczekiwaniu na twój powrót zostawiła dla ciebie paczkę.>', 0),
(12238, 'koKR', 'Dokonaliśmy wielkiej rzeczy, mon! A to dopiero początek...$B$BOdszukaj mnie w Zul\'Draku, kiedy nadejdzie pora.$B$BJest wojna do wygrania, mon!', 0),
(12241, 'koKR', 'Niczego nie mogę obiecać, $N. Ale zrobię, co w mojej mocy, by je oczyścić.', 0),
(12242, 'koKR', 'Dziękuję, $N. Wezmę je od ciebie.$b$bMoc skażenia tych nasion jest niebezpieczna. Muszę je natychmiast zniszczyć.', 0),
(12244, 'koKR', '<Synipus gwiżdże.>$B$BAle ślicznotka! Doprowadzimy ją do porządku.$B$BJeśli nie masz co robić, pogadaj z Gordunem, niech cię podrzuci do Zatoki Gitgeszeft. Na pewno przyda im się pomoc.$B$BA, i skoro już tam będziesz, użyj tych kluczyków na odnowionym rozdrabniaczu. Zobaczysz, co te maleństwa potrafią, kiedy się je wyczyści!', 0),
(12246, 'koKR', 'Skażenie w tej krwi jest takie samo jak w szlamie. Mam co do tego złe przeczucia.', 0),
(12247, 'koKR', 'Dzieci Ursoca są mądre. Ich słowa wyjaśniają wiele z tego, co dotąd widzieliśmy.', 0),
(12248, 'koKR', 'Tak! Magia Vordrassila wciąż tkwi w tych popiołach. Może jest jeszcze nadzieja dla Ursoca.', 0),
(12249, 'koKR', '<Druidka jest blada, a jej oczy patrzą pustym wzrokiem gdzieś za ciebie. W oczekiwaniu na twój powrót zostawiła dla ciebie paczkę.>', 0),
(12250, 'koKR', 'Dziękuję, $N. Wezmę je od ciebie.$B$BMoc skażenia tych nasion jest niebezpieczna. Muszę je natychmiast zniszczyć.', 0),
(12255, 'koKR', 'Dobra robota, $N. Wątpię, żeby któryś z drwali miał ochotę zmierzyć się z protosmokowcem, ale nie mogliśmy pozwolić, by Smokołupcy zbudowali sobie ośrodek władzy we Wzgórzach Grizli. Gdyby tylko z Hordą szło tak łatwo...', 0),
(12256, 'koKR', 'Dzięki mocy talizmanów smok nie ma wyboru i musi słuchać twoich rozkazów. Los thana jest przesądzony.', 0),
(12257, 'koKR', '$GZrobiłeś:Zrobiłaś; dokładnie to, o co prosiłem. Zepchnęliśmy Smokołupców do obrony i wkrótce przyjdzie czas, by rozprawić się z ich przywódcą.', 0),
(12259, 'koKR', 'Po twojej walce z thanem tych kilku pozostałych Smokołupców nie ośmieli się nam rzucić wyzwania. Nie okazuj litości naszym wrogom – taka jest droga Hordy.', 0),
(12268, 'koKR', 'O tak. Te powinny załatwić sprawę...$B$BGotowe. Jeszcze jeden rozdrabniacz gotowy do walki. Dzięki, $N.', 0),
(12270, 'koKR', 'Dobra robota, żołnierzu!$B$BA teraz weź ten kluczyk i ruszaj do Zatoki Gitgeszeft. Pozwoli ci użyć jednego z odnowionych rozdrabniaczy, żeby siać chaos wśród naszych wrogów.$B$BA, i pogadaj z Darrokiem, jeśli chcesz pójść na skróty!', 0),
(12279, 'koKR', 'Ty! Ty nie jesteś Kulawym Joe!', 0),
(12280, 'koKR', 'Dzięki, $N. To mi wystarczy – przynajmniej do jutra...$B$BOto obiecana forsa.', 0),
(12284, 'koKR', 'Piętnastu mniej, co? Dobrze to słyszeć, $N.$B$BJeśli nic innego, to przynajmniej $gzyskałeś:zyskałaś; nam trochę czasu – z moich rachunków wychodzi, że co najmniej dzień.$B$BOto twoja zapłata.', 0),
(12288, 'koKR', 'Och, dziękuję, dziękuję.$B$BDzięki tobie przeżyliśmy kolejny dzień. Może jest jeszcze nadzieja.', 0),
(12289, 'koKR', 'Dobra robota, $N.$B$B$GZyskałeś:Zyskałaś; nam tu trochę czasu, choć pewnie nie więcej niż dzień. Mimo to Przymierze jest ci wdzięczne za twoje wysiłki.', 0),
(12292, 'koKR', 'Zamknięta, co? Wygląda całkiem zwyczajnie.$B$B<Porucznik Dumont potrząsa skrzynią, w której coś drewnianie grzechocze.>$B$BZresztą nieważne. Jeśli to da nam przewagę nad Hordą, to nie obchodzi mnie, czy jest tam choćby lek na zarazę.', 0),
(12293, 'koKR', 'Udało się! $GOdzyskałeś:Odzyskałaś; Ko... $godzyskałeś:odzyskałaś; skrzynię, którą ukradła nam Horda. Dziękujemy ci, $N.', 0),
(12294, 'koKR', 'Świetne wieści, $N. Z pomocą miejscowych będziemy mieli wsparcie logistyczne, którego potrzebujemy, by wymanewrować Hordę w tym regionie.$B$BJeśli chcesz, mam dla ciebie kolejne zadania.', 0),
(12295, 'koKR', 'Miło cię wreszcie poznać, $N! Słyszeliśmy tu o tobie. Witaj w Srebrnym Potoku.$B$BCi traperzy to wspaniała banda chłopaków i dziewczyn. Twardzi ludzie i świetnie znają okolicę. Przekonasz się, że to wielka rzecz, że w końcu przeciągnęliśmy ich na naszą stronę.', 0),
(12296, 'koKR', 'Wspaniale!$B$BPrzymierze doczeka kolejnego dnia, po części dzięki twojej sumienności.$B$BPrzyjmij, proszę, moje podziękowania, $gprzyjacielu:przyjaciółko;.', 0),
(12299, 'koKR', 'Nieźle, nieźle. Może nie jesteś $gtaki miękki:taka miękka; jak niektórzy inni.', 0),
(12300, 'koKR', 'Nie rób tego, $N. Ludzie, którzy cię tu przysłali... nie $gpowinieneś:powinnaś; im ufać.', 0),
(12302, 'koKR', 'Kto tam? $GPrzyszedłeś:Przyszłaś; mnie zabić?$B$BProszę! Nie musisz tego robić!', 0),
(12307, 'koKR', '<Katja nerwowo się od ciebie odsuwa.>$B$BDziękuję, $N. Nie $gubrudziłeś:ubrudziłaś; się tojadem, prawda? Mam taką... alergię, która od czasu do czasu daje o sobie znać.', 0),
(12308, 'koKR', 'Worgeny. Przeklęte, porzucone przez Światłość, zapchlone worgeny.$B$BCzas pokazać miejscowym, co my, cywilizowani ludzie, robimy z takimi bestiami.', 0),
(12310, 'koKR', 'Szkoda, że ci traperzy okazali się... dotknięci. Przydałoby się nam jeszcze paru ludzi do walki.$B$BNiech te biedne dusze spoczywają w pokoju.', 0),
(12314, 'koKR', 'Dobra robota, $N! Bez przywódcy Horda jest słaba i zdezorganizowana. Każę naszym ludziom ruszać naprzód.', 0),
(12315, 'koKR', 'Jesteś prawdziwym żołnierzem Hordy, $N. Twoja odwaga poprowadzi moich ludzi do zwycięstwa!', 0),
(12316, 'koKR', 'Twoja odwaga natchnęła ludzi z Brygady Zachodniego Skraju. Nawet teraz walczą z większą zaciekłością. Port wkrótce będzie nasz.', 0),
(12317, 'koKR', 'Port wkrótce padnie. Dobrze się dziś $gspisałeś:spisałaś;, $N.', 0),
(12323, 'koKR', 'Dobra robota, żołnierzu! Teraz reszta ludzi może skupić się na Hordzie.', 0),
(12324, 'koKR', 'Generał będzie zadowolony, że $grozwiązałeś:rozwiązałaś; problem spółki Gitgeszeft. Teraz ludzie mogą skupić się na odpieraniu Przymierza.', 0),
(12327, 'koKR', 'Czy wizja czegoś cię nauczyła? W transie $gwspomniałeś:wspomniałaś; o Wiosce Przesilenia – to już drugi raz dzisiaj, gdy ktoś wymawia nazwę tego miejsca.', 0),
(12328, 'koKR', 'Dobrze. Te w zupełności wystarczą.$B$BMikstura będzie dla ciebie gotowa w mgnieniu oka.', 0),
(12329, 'koKR', 'Zastanawiałam się, kiedy się zjawisz. Pomożesz mi tutaj?', 0),
(12330, 'koKR', 'To... to było o włos.$B$BMusimy uratować Anyę. Już!', 0),
(12411, 'koKR', 'Nie chcę już tu być. Ci wilkoludzie są niedobrzy.', 0),
(12412, 'koKR', '$GWróciłeś:Wróciłaś;. I to $gżywy:żywa;.$b$bA co to za bzdury o worgenach?', 0),
(12413, 'koKR', 'Nieźle, $N. Może się okazać, że jesteś odrobinę bardziej $gprzydatny:przydatna;, niż początkowo sądziłam.', 0),
(12414, 'koKR', 'Rany! Ale z nich dobre konie! Chyba kapitan będzie bardzo zadowolony z naszej roboty.', 0),
(12415, 'koKR', '<Soulok kiwa głową z aprobatą.>$b$bDobra robota, $N. Nie możemy pozwolić, by Przymierze zyskało jakąkolwiek przewagę.', 0),
(12422, 'koKR', 'Wypuszczasz mnie... tak po prostu? Słuchaj, nie chcę z tobą kłopotów... te potwory zabiły mi ojca i porwały siostrę. Mam teraz inne rzeczy na głowie.', 0),
(12423, 'koKR', 'Ha! To jakiś żart?$B$BLedwo mi się przydają książki, które w ogóle rozumiem.', 0),
(12424, 'koKR', 'Czy to możliwe? Człowiek, który napisał ten dziennik, bał się o życie swoich córek, więc odesłał je ze Srebrnego Potoku.$B$BWłaśnie pojmaliśmy na obrzeżach miasteczka wygnankę mniej więcej w wieku najstarszej córki.$B$BSłuchaj, $N. Dzieje się tu więcej, niż widać na pierwszy rzut oka... nie możemy tak po prostu spalić tego dziennika.', 0),
(12425, 'koKR', 'Szukasz wiedzy, która jest poza twoim zasięgiem, więc $gprzyszedłeś:przyszłaś; do mnie. Muszę cię ostrzec, $gnieznajomy:nieznajoma;: odpowiedzi, których udzielam, mogą ci się nie spodobać.', 0),
(12427, 'koKR', 'Niezła robota, mon! Oto twoja działka.', 0),
(12428, 'koKR', 'Ale $gmiałeś:miałaś; ruchy, $gprzyjacielu:przyjaciółko;! Dużo zakładów przeciwko tobie, a to dobra wiadomość dla kasy!', 0),
(12429, 'koKR', 'Aż mi serce stanęło! Myślałem, że ta kupa żelastwa cię dopadnie, mon!', 0),
(12430, 'koKR', 'Ale praca nóg, ale praca nóg. Naprawdę szybko $gprzerobiłeś:przerobiłaś; tego szalonego orka, $gprzyjacielu:przyjaciółko;.$B$BKursy były przeciwko tobie, siedem do jednego – nieźle na tym zarobiłem!', 0),
(12431, 'koKR', 'To, co się dziś stało... musiało się stać. Nie znaczy to, że muszę się z tego cieszyć.$B$BUwolniłam mój lud od tyranki, ale straciłam też siostrę. Dziękuję ci za pomoc, $N. Chcę teraz zostać sama.', 0),
(12432, 'koKR', 'Ha, ha! Ale jazda, co, $N?$B$BSkoro my nie możemy kontrolować tutejszych surowców, to nikt nie będzie!$B$BKiedy te marne szkodniki z Przymierza wreszcie zrozumieją, że nie mają szans z potęgą Hordy?', 0),
(12433, 'koKR', 'O tak. To mi oszczędzi całe godziny.$B$BWeź to za fatygę, $gprzyjacielu:przyjaciółko;. I rozglądaj się za pierwiastkiem 115. Wezmę każdą ilość, jaką znajdziesz.', 0),
(12436, 'koKR', 'Dobra robota, $N. Każdy z nich wykarmi dwóch albo trzech siepaczy. Nieźle.', 0),
(12437, 'koKR', 'Dobrze widzieć, że $gprzeżyłeś:przeżyłaś; to zderzenie. Niezły wybuch!$B$BNie możemy pozwolić, żeby Horda zwiała z całym tym drewnem.$B$BDobra robota, $N.', 0),
(12443, 'koKR', 'O tak. To mi oszczędzi całe godziny.$B$BWeź to za fatygę, $gprzyjacielu:przyjaciółko;. I rozglądaj się za pierwiastkiem 115. Wezmę każdą ilość, jaką znajdziesz.', 0),
(12444, 'koKR', 'Dobra robota, $N. Przydałoby się tu kilku więcej takich jak ty. Naprawdę pokazalibyśmy Hordzie, że z nami się nie zadziera.', 0),
(12451, 'koKR', '<Krótko się przedstawiasz i wyjaśniasz, że przysłał cię sierżant Nazgrim.>$B$BAch, więc jesteś czymś w rodzaju posiłków. Dobrze.$B$BTormak i jego ludzie potrzebują twojego ostrza.', 0),
(12453, 'koKR', 'Dziękuję ci, $N. Doceniam twoją pomoc.', 0),
(12468, 'koKR', 'Więc Krenna przysłała cię do mnie? $GMusiałeś:Musiałaś; jej się nie spodobać, ale z drugiej strony, kogo ona w ogóle lubi?$B$BRozbicie tej placówki wrykułów to będzie ciężka, bardzo ciężka robota.', 0),
(12483, 'koKR', 'Och, mon – gulasz z lśniogrzybów! Już prawie czuję jego smak...', 0),
(12484, 'koKR', 'Nie ma nic lepszego niż patrzeć, jak ta Plaga płonie... <hik>.$b$bNapisałem o tym taką piosnkę. Chcesz poszłuchać? No to jazda...', 0),
(12763, 'koKR', 'Światłość zwycięży!', 0),
(12770, 'koKR', 'Światłość zwycięży!', 0),
(12802, 'koKR', 'Imponujące, mon! Los był łaskawy, że nas połączył.$b$bWkrótce pomszczę moich braci, oczyszczając Drak\'Tharon, a ty w nagrodę dostaniesz największy skarb Drak\'Tharon.', 0),
(13129, 'koKR', '<Mack patrzy na ciebie i nie może przestać się śmiać.>$b$bOch nieee... Czemu musiała szobie pójść i dać się zabić?$b$bWiesz, powinienem napisać o niej jakąś piosnkę. To mnie pocieszy!$b$b<hik>', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(11982, 'koKR', 'Co masz do zameldowania?', 0),
