(12007, 'koKR', 'Masz Oko Proroków, mon?', 0),
(12014, 'koKR', 'Czego się $gdowiedziałeś:dowiedziałaś;?', 0),
(12026, 'koKR', 'Co tam masz?', 0),
(12029, 'koKR', 'Zrobione, $N?', 0),
(12038, 'koKR', 'Zrobione, $N?', 0),
(12054, 'koKR', '$GPrzyniosłeś:Przyniosłaś; wystarczająco dużo ziela?', 0),
(12058, 'koKR', '$GOdkryłeś:Odkryłaś; sekrety Thor Modan?', 0),
(12068, 'koKR', 'Dobrze cię widzieć, $n.$b$bMasz tablice?', 0),
(12070, 'koKR', '$GPrzekazałeś:Przekazałaś; olbrzymom moje błogosławieństwo?', 0),
(12073, 'koKR', '$GUderzyłeś:Uderzyłaś; na żelazne krasnoludy, tak jak prosiłem?', 0),
(12093, 'koKR', 'Czy runy na wybrzeżu są już unieszkodliwione?', 0),
(12094, 'koKR', 'Udało ci się znaleźć pradawne kamienie?', 0),
(12099, 'koKR', 'Udało ci się uwolnić któregoś z moich braci?', 0),
(12105, 'koKR', 'Co tam masz?', 0),
(12113, 'koKR', 'Burczy mi w brzuchu. Udało ci się nazbierać trochę jedzenia?', 0),
(12114, 'koKR', 'Jak idą łowy na trolle?', 0),
(12116, 'koKR', 'Co $gznalazłeś:znalazłaś; w krypcie dla Kraza, $N?', 0),
(12120, 'koKR', '$GZnalazłeś:Znalazłaś; pałkę, $n?', 0),
(12129, 'koKR', 'Udało ci się zdobyć te plany od kowali run?', 0),
(12130, 'koKR', 'Widzę, że $gwyszedłeś:wyszłaś; z tego w jednym kawałku. Masz części?', 0),
(12131, 'koKR', 'No i jak, masz te ogniwa zasilające?', 0),
(12134, 'koKR', '$GZająłeś:Zajęłaś; się już łowcami w wiosce, $N?', 0),
(12137, 'koKR', '$GWykonałeś:Wykonałaś; swoje zadanie w krypcie, $N?', 0),
(12152, 'koKR', 'Czy Jin\'arrak został pokonany, $N?', 0),
(12153, 'koKR', 'Udało ci się przełamać obronę żelaznego thana?', 0),
(12154, 'koKR', '$GUnieszkodliwiłeś:Unieszkodliwiłaś; źródło mocy ich kuźni run?', 0),
(12159, 'koKR', '$GDałeś:Dałaś; już spokój moim przyjaciołom, $N?', 0),
(12164, 'koKR', 'Dobrze cię widzieć, $N.', 0),
(12165, 'koKR', 'Czy... czy masz te plany, o które prosiłem?', 0),
(12170, 'koKR', '$GZabiłeś:Zabiłaś; te psy Przymierza? Zwycięstwo musi być nasze!', 0),
(12175, 'koKR', 'Masz te skóry, mon?', 0),
(12176, 'koKR', 'Masz te skóry, mon?', 0),
(12177, 'koKR', 'Masz te rzeczy, mon?', 0),
(12178, 'koKR', 'Czy ty w ogóle wiesz, z kim rozmawiasz?', 0),
(12180, 'koKR', 'Udało ci się odnaleźć zaginionych poszukiwaczy?', 0),
(12183, 'koKR', 'Masz mundur?', 0),
(12184, 'koKR', 'Masz te zdjęcia?', 0),
(12185, 'koKR', 'Przebranie zadziałało?', 0),
(12190, 'koKR', 'Co mogę dla ciebie zrobić?', 0),
(12195, 'koKR', '$GPrzyniosłeś:Przyniosłaś; poroża?', 0),
(12196, 'koKR', 'C-czy $gp-p-przyniosłeś:p-p-przyniosłaś; te części golema?', 0),
(12197, 'koKR', 'Masz te ogniwa zasilające?', 0),
(12199, 'koKR', 'Proszę, powiedz, że się udało...', 0),
(12201, 'koKR', 'Masz mundur?', 0),
(12202, 'koKR', 'Masz te zdjęcia?', 0),
(12203, 'koKR', 'Czego się $gdowiedziałeś:dowiedziałaś; o Lokenie?', 0),
(12204, 'koKR', 'Czego się $gdowiedziałeś:dowiedziałaś;?', 0),
(12207, 'koKR', 'Masz próbki, $N?', 0),
(12212, 'koKR', 'Jak idą łowy?', 0),
(12215, 'koKR', 'Mam nadzieję, że w tych lasach poluje teraz kilka worgów mniej?', 0),
(12216, 'koKR', '$GPotężny:Potężna; $N $gpowrócił:powróciła;!', 0),
(12217, 'koKR', '$GWykonałeś:Wykonałaś; swoje zadanie, $N?', 0),
(12219, 'koKR', '$GZebrałeś:Zebrałaś; próbki, $N?', 0),
(12220, 'koKR', '$GZrobiłeś:Zrobiłaś; to, o co cię prosiłam, $N?', 0),
(12222, 'koKR', 'Masz te talizmany?', 0),
(12223, 'koKR', 'Zrobione?', 0),
(12226, 'koKR', '$GZnalazłeś:Znalazłaś; czarny korzeń?', 0),
(12227, 'koKR', 'Masz już dla mnie te nasiona?', 0),
(12229, 'koKR', '$GZdobyłeś:Zdobyłaś; próbki krwi, $N?', 0),
(12231, 'koKR', '$GRozmawiałeś:Rozmawiałaś; już z dziećmi Ursoca, $N?', 0),
(12236, 'koKR', '$GWróciłeś:Wróciłaś;. Udało się?', 0),
(12241, 'koKR', '$GPrzyniosłeś:Przyniosłaś; mi popioły, $N?', 0),
(12242, 'koKR', '$GZdobyłeś:Zdobyłaś; już nasiona Vordrassila, $N?', 0),
(12244, 'koKR', 'Nie ma czasu na pogawędki. Te rozdrabniacze mogą przechylić szalę na korzyść Przymierza!', 0),
(12246, 'koKR', '$GZdobyłeś:Zdobyłaś; próbki krwi, $N?', 0),
(12247, 'koKR', '$GRozmawiałeś:Rozmawiałaś; już z Orsonnem i Kodianem?', 0),
(12248, 'koKR', '$GPrzyniosłeś:Przyniosłaś; mi popioły, $N?', 0),
(12249, 'koKR', '$GWróciłeś:Wróciłaś;. Udało się?', 0),
(12250, 'koKR', 'Masz nasiona, $N?', 0),
(12255, 'koKR', '$GPokonałeś:Pokonałaś; thana? Nie możemy ryzykować, że zostanie u władzy.', 0),
(12256, 'koKR', 'Masz te talizmany?', 0),
(12257, 'koKR', 'Zrobione?', 0),
(12259, 'koKR', '$GPokonałeś:Pokonałaś; thana?', 0),
(12268, 'koKR', 'Masz dla mnie te części, $N?', 0),
(12270, 'koKR', '$GZdobyłeś:Zdobyłaś; już te rozdrabniacze, $N?', 0),
(12279, 'koKR', 'Jak się nie pospieszysz, to nie tylko jej brzuch zacznie warczeć...', 0),
(12280, 'koKR', '$GPrzyniosłeś:Przyniosłaś; mi już te części?', 0),
(12284, 'koKR', 'Czy to krew Przymierza na twojej broni?', 0),
(12288, 'koKR', '$GWyleczyłeś:Wyleczyłaś; już naszych rannych, $N?', 0),
(12289, 'koKR', 'Jak idzie walka, $N?', 0),
(12292, 'koKR', '$GPrzyniosłeś:Przyniosłaś; mi tę skrzynkę, $N?', 0),
(12293, 'koKR', '$GPrzyniosłeś:Przyniosłaś; nam coś?', 0),
(12299, 'koKR', '$GSkończyłeś:Skończyłaś; już z tymi hordziackimi kretynami?', 0),
(12300, 'koKR', 'Ludzie w Srebrnym Potoku... nie są tym, na kogo wyglądają.', 0),
(12307, 'koKR', 'Tak, $N?', 0),
(12308, 'koKR', '$GWróciłeś:Wróciłaś;. Martwiłem się o ciebie, $N.', 0),
(12310, 'koKR', 'Zrobione, %N?', 0),
(12314, 'koKR', '$GZabiłeś:Zabiłaś; kapitan Zornę?', 0),
(12315, 'koKR', '$GZlikwidowałeś:Zlikwidowałaś; wrogiego kapitana?', 0),
(12316, 'koKR', 'Co masz do zameldowania?', 0),
(12317, 'koKR', '$GWykonałeś:Wykonałaś; rozkaz?', 0),
(12323, 'koKR', '$GWykurzyłeś:Wykurzyłaś; już ostatnich ludzi ze spółki Gitgeszeft?', 0),
(12324, 'koKR', '$GWykurzyłeś:Wykurzyłaś; już ostatnie robactwo ze spółki Gitgeszeft?', 0),
(12328, 'koKR', '$GZdobyłeś:Zdobyłaś; pył, $N?', 0),
(12330, 'koKR', 'Dobrze widzieć cię w jednym kawałku.', 0),
(12412, 'koKR', '$GWykonałeś:Wykonałaś; zadanie? Jeśli nie, to co tu robisz?', 0),
(12414, 'koKR', 'Masz już wszystkie mustangi, których potrzebujemy?', 0),
(12422, 'koKR', '$GPrzyszedłeś:Przyszłaś; mnie zabić?', 0),
(12423, 'koKR', 'Co tam masz?', 0),
(12427, 'koKR', 'To się nie skończy, dopóki ty albo niedźwiedź nie padniecie, $gprzyjacielu:przyjaciółko;!', 0),
(12432, 'koKR', 'Czy to drewno Przymierza już spłonęło, $N?', 0),
(12433, 'koKR', 'Masz trochę tego pierwiastka 115, $N?', 0),
(12436, 'koKR', '$GZdobyłeś:Zdobyłaś; już tę dziczyznę, $N?', 0),
(12437, 'koKR', 'Czy ten statek Hordy z drewnem już spłonął, $N?', 0),
(12443, 'koKR', 'Masz trochę tego pierwiastka 115, $N?', 0),
(12444, 'koKR', 'Jak idą łowy?', 0),
(12483, 'koKR', 'Masz te składniki dla starego Prigmona, $N?', 0),
(12484, 'koKR', 'Co tam masz?', 0),
(13129, 'koKR', '<hik>$b$bCo tam masz, kolego?', 0);
