(43215, 'koKR', 'Płótno poplamione posoką', 'Płótno jest przesiąknięte posoką potężnego lisza.', 0),
(44366, 'koKR', 'Haniebne mankiety', '', 0),
(44367, 'koKR', 'Wzgardzone opaski', '', 0),
(44368, 'koKR', 'Oskarżone osłony nadgarstków', '', 0),
(44369, 'koKR', 'Wyparte karwasze', '', 0),
(44674, 'koKR', 'Owijacze poplamione posoką', '', 0),
(44675, 'koKR', 'Osłona na mały palec skalnego olbrzyma', '', 0),
(44676, 'koKR', 'Nogawice Syreian', '', 0),
(44921, 'koKR', 'Jajo raptora z Gundraku', 'Coś się tam w środku rusza!', 0),
(51958, 'koKR', 'Nieskazitelne futro jarzącego się niedźwiedzia', '', 0);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(3544, 'koKR', 'Znajdujesz szczątki tajemniczego obiektu. Za płomieniami udaje ci się dostrzec insygnia z oznaczeniem „M:1815212085”. Zastanawiasz się, z jakiego świata może pochodzić ten obiekt...', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(13157, 'koKR', '', 'Dziękuję, że mnie $guwolniłeś:uwolniłaś;.$b$bWciąż trochę kręci mi się w głowie od jadu. Chyba zostanę tu, dopóki nie wrócą mi siły.', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(26588, 9, 0, 'koKR', 'Pan Kłapuś odżywa'),
(26588, 10, 0, 'koKR', 'Wygłodniały worg chwyta zębami Pana Kłapusia');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(11349, 'koKR', 'Na szyi renifera wisi plakietka z logo Wędzonych Pastwisk i imieniem – „Metzen”.$B$BMetzen patrzy na ciebie smutnymi, opuszczonymi oczami. Wygląda to prawie tak, jakby renifera unieruchomiła jakaś niewidzialna siła.', '', 0),
(23383, 'koKR', '', 'Aaach, nareszcie!', 0),
(23384, 'koKR', '', 'Słuchaj, znalazłam ten amulet tuż przed tym, jak mnie złapali. Może ci się tu przyda...', 0),
(23385, 'koKR', '', 'Mam nadzieję, że pomoże. Te plugawe bestie po prostu trzeba powstrzymać!', 0),
(23386, 'koKR', '', 'Powodzenia!', 0),
(25483, 'koKR', 'Konstrukty, brońcie stolicy za wszelką cenę!', '', 0),
(25484, 'koKR', 'Do boju, moje dzieci! Nie okazujcie wrogowi litości!', '', 0),
(25486, 'koKR', 'Za thana! Za Lokena!', '', 0),
(25487, 'koKR', 'Zmiażdżcie dzieci kamienia, moi żelaźni bracia!', '', 0),
(25567, 'koKR', 'Witaj w naszym obozie. Jeśli chcesz, możesz tu odpocząć.', 'Witaj w naszym obozie. Jeśli chcesz, możesz tu odpocząć.', 0),
(25644, 'koKR', '<Budd zamiera w bezruchu, udając, że cię nie słyszy. Gdy przyglądasz mu się uważnie, widzisz, jak spod maski cieknie mu odrobina śliny.>', '', 0),
(25645, 'koKR', '<Budd kiwa się w przód i w tył na zadzie, mamrocząc coś, co brzmi jak mowa trolli.>', '', 0),
(25646, 'koKR', 'Idź sobie, mon.', '', 0),
(25647, 'koKR', 'Nie ma czasu na gadanie, mon. Muszę teraz odpocząć...', '', 0),
(25656, 'koKR', 'No chodź, Budd. Czas pobawić się z lodowymi trollami!', 'No chodź, Budd. Czas pobawić się z lodowymi trollami!', 0),
(25679, 'koKR', 'Trollowa moc, mon!', '', 0),
(25680, 'koKR', 'Co z tobą nie tak, mon? Nigdy nie $gwidziałeś:widziałaś; trolla?', '', 0),
(25700, 'koKR', 'Obudź się, Griseldo. Chodź tu, maleńka.', '', 0),
(25701, 'koKR', 'Tu nas nigdy nie znajdą, prawda? Nie damy się złapać tak jak Kulawy Joe i Flanelowy McGee!', '', 0),
(25702, 'koKR', 'Nie, uciekliśmy przed tymi potworami! Nie jesteśmy tacy jak oni, Griseldo.', '', 0),
(25703, 'koKR', 'Jesteśmy myśliwymi, ty i ja. Żadnych wilkołaków tutaj, co to, to nie.', '', 0),
(25704, 'koKR', 'Wypatruj ich, maleńka! Nie pozwól, żeby nas dopadli!', '', 0),
(25802, 'koKR', '', 'Gotowy, Panie Kłapusiu? Trzymaj się blisko mnie i uważaj na te wilki!', 0),
(25803, 'koKR', '', 'Eee... chyba jeden z tych wilków wrócił...', 0),
(25804, 'koKR', '', 'On chce dopaść Pana Kłapusia!', 0),
(25805, 'koKR', '', 'Uciekajmy stąd, zanim znajdzie nas więcej wilków!', 0),
(25806, 'koKR', '', 'O nie! Patrz, to kolejny wilk, i to taaaaaaki wielki!', 0),
(25809, 'koKR', '', 'Nie idź w stronę światła, Panie Kłapusiu!', 0),
(25810, 'koKR', '', 'Panie Kłapusiu, nic ci nie jest! Bardzo dziękuję za uratowanie Pana Kłapusia!', 0),
(25820, 'koKR', 'Dzień dobry, kolego! Siadaj i łyknij sobie, co?', '', 0),
(25821, 'koKR', 'Potrzebuję jeszcze trochę twojego wybornego grogu, Mack.', 'Potrzebuję jeszcze trochę twojego wybornego grogu, Mack.', 0),
(25853, 'koKR', 'Plaga jest wszędzie, mon!', '', 0),
(25855, 'koKR', 'Każdy troll ratuje własną skórę, mon!', '', 0),
(25857, 'koKR', 'Drak\'Tharon stracone, mon!', '', 0),
(25859, 'koKR', 'Uciekaaać!', '', 0),
(25874, 'koKR', 'Stojąc przed tym starożytnym bożkiem, wyczuwasz dziwną obecność.', '', 0),
(25875, 'koKR', 'Tam, gdzie przez tysiąclecia spoczywało Oko Proroków, została tylko pusta nisza.', '', 0),
(25876, 'koKR', 'Wyjmij Oko Proroków z twarzy bożka.', 'Wyjmij Oko Proroków z twarzy bożka.', 0),
(25877, 'koKR', 'Będę na ciebie czekał, mon.', '', 0),
(25967, 'koKR', 'Żelaźni panowie, pomóżcie mi w tej bitwie!', '', 0),
(25979, 'koKR', 'Zmiażdżyć małego!', '', 0),
(25980, 'koKR', 'Zniszczymy cię, nędzna istoto!', '', 0),
(25981, 'koKR', 'Dzieci żelaza, użyczcie mi swoich ostrzy!', '', 0),
(25982, 'koKR', 'Wróg rośnie w siłę! Pomóżcie mi!', '', 0),
(25983, 'koKR', 'Nikt nie powstrzyma nas przed naszym przeznaczeniem!', '', 0),
(25984, 'koKR', 'Na chwałę Lokena!', '', 0),
(25985, 'koKR', 'Zapłacisz za to wtrącanie się!', '', 0),
(25986, 'koKR', 'Głupiec z ciebie, skoro walczysz w beznadziejnej bitwie Kuruna!', '', 0),
(25987, 'koKR', 'Twoje życie jest stracone, sojuszniku kamienia!', '', 0),
(26009, 'koKR', 'Lepiej się stąd wynoś, chyba że chcesz wylądować w jednej z tych klatek...', '', 0),
(26027, 'koKR', 'Dobra, $gmały:mała;. Trzymaj się za mną, a nic ci nie będzie.', '', 0),
(26028, 'koKR', 'Ich komnata ceremonialna, gdzie miałem zostać złożony w ofierze...', '', 0),
(26029, 'koKR', 'Czas z tym wszystkim skończyć!', '', 0),
(26030, 'koKR', 'Dziwne. Zwykle to działa.', '', 0),
(26036, 'koKR', 'Co to?', '', 0),
(26037, 'koKR', 'O nie, tylko nie wąż!', '', 0),
(26048, 'koKR', 'Dziękuję ci, $gmaleńki:maleńka;.', '', 0),
(26049, 'koKR', 'Masz moją wdzięczność.', '', 0),
(26050, 'koKR', 'Nie sądziłem, że kiedyś uwolnię się od tego strasznego zaklęcia!', '', 0),
(26051, 'koKR', 'Myślałem, że jestem zgubiony. Dziękuję, że mnie $guwolniłeś:uwolniłaś;.', '', 0),
(26053, 'koKR', 'Tym lepiej, mam już dość tego miejsca.', '', 0),
(26057, 'koKR', 'Może pani iść.', '', 0),
(26065, 'koKR', 'Słuchaj, $gmały:mała;. Poradzę sobie z tym czymś. Ty tylko pilnuj moich pleców!', '', 0),
(26066, 'koKR', 'Do zobaczenia, $gmały:mała;!', '', 0),
(26085, 'koKR', 'Ty bierzesz moje serce, to ja biorę twoje!', '', 0),
(26086, 'koKR', 'Czemu grzebiesz mi we flakach, mon?', '', 0),
(26087, 'koKR', 'Ściskasz mi wątrobę, mon!', '', 0),
(26088, 'koKR', 'Wracaj tu z moimi bebechami!', '', 0),
(26089, 'koKR', 'Co ty wyprawiasz?', '', 0),
(26090, 'koKR', 'Zapłacisz za to!', '', 0),
(26091, 'koKR', 'Głupcze! Nie ujdzie ci to na sucho!', '', 0),
(26092, 'koKR', 'Śmiesz sprzeciwiać się synom żelaza?', '', 0),
(26098, 'koKR', 'Jak śmiesz przywoływać mnie bez ofiary!', '', 0),
(26106, 'koKR', 'Nie ujdzie ci to na sucho, wiesz? Jesteś tylko dzieciakiem.', '', 0),
(26107, 'koKR', 'Ile masz lat, dziewczyno?', '', 0),
(26108, 'koKR', 'Wszyscy skończymy na służbie u Króla Lisza, mała. Lepiej tak, niż zostać gnijącym trupem.', '', 0),
(26109, 'koKR', 'Twój ojciec był słaby, Sasho... nie miał odwagi zrobić tego, co trzeba było zrobić.', '', 0),
(26110, 'koKR', '', 'Jestem dość dorosła, żeby trafić takie bestie jak ty prosto między oczy... z dwa razy większej odległości.', 0),
(26112, 'koKR', '', 'Wolę umrzeć, niż stać się jedną z was! Myślicie, że wciąż jesteście ludźmi? Jesteście... zwierzętami!', 0),
(26113, 'koKR', '', 'Nie waż się mówić o moim ojcu, potworze. Był dwa razy więcej wart, niż ty kiedykolwiek będziesz.', 0),
(26148, 'koKR', 'Nareszcie wolny, mon.', '', 0),
(26149, 'koKR', 'Mógłbym spać wiecznie, mon...', '', 0),
(26150, 'koKR', 'Gdzie moja mumia?', '', 0),
(26151, 'koKR', 'Nareszcie mogę odpocząć...', '', 0),
(26153, 'koKR', 'Rozpoczęcie zbierania energii.', '', 0),
(26154, 'koKR', 'Zbieranie energii zakończone.', '', 0),
(26177, 'koKR', 'Może i nie ma tu śniegu, ale noce potrafią tu odmrozić nos. Prycze są z tyłu – tylko się nie naprzykrzaj.', '', 0),
(26189, 'koKR', 'Dziękuję za ratunek, ale pozostali wciąż są uwięzieni na wyższych poziomach!', '', 0),
(26190, 'koKR', 'Dzięki niebiosom! Bałem się, że wcielą mnie do służby w wojnie z kamiennymi olbrzymami!', '', 0),
(26191, 'koKR', '', 'Ci żelaźni to wariaci! Ciągle gadają o służbie „panu Lokenowi”, ale z tego, co widzę, rozkazy od niego dostaje tylko kilku z nich.', 0),
(26212, 'koKR', 'Aaach! Co się ze mną dzieje, mon?', '', 0),
(26228, 'koKR', 'Natychmiast, pani!', '', 0),
(26232, 'koKR', 'Spóźniłeś się, nadzorco.', '', 0),
(26233, 'koKR', 'Przeznaczenie nie będzie czekać. Twoi rzemieślnicy muszą zwiększyć produkcję golemów bojowych, zanim przywódca kamiennych olbrzymów i jego armia dotrą do Ulduaru.', '', 0),
(26234, 'koKR', 'Powiedz swoim kowalom run, by dalej przemieniali tylu kamiennych olbrzymów, ilu zdołają. Tych, którzy się nie podporządkują, trzeba zniszczyć.', '', 0),
(26235, 'koKR', 'Jeśli kamienne olbrzymy przeszkodzą w naszej pracy w Ulduarze, pociągnę do odpowiedzialności ciebie i twojego thana. Nie wolno dopuścić, by śmiertelnicy przyszli olbrzymom z pomocą.', '', 0),
(26236, 'koKR', 'Wracaj do swoich obowiązków, nadzorco. Dopilnuj, by twoi robotnicy pojęli, jak pilne są ich zadania.', '', 0),
(26239, 'koKR', 'Zobaczmy, czy to działa.', '', 0),
(26251, 'koKR', 'Jesteś wśród taunka z Obozu Oneqwah, krasnoludzie.', '', 0),
(26252, 'koKR', 'Jeśli zgodzisz się pomóc nam przeciw naszemu wspólnemu wrogowi, nie stanie ci się tu krzywda.', '', 0),
(26253, 'koKR', 'Przemyśl to, poszukiwaczu, ale zdecyduj się szybko. Musimy wkrótce działać.', '', 0),
(26261, 'koKR', 'Kulawy Joe, to ty. To naprawdę ty!', '', 0),
(26262, 'koKR', 'Uspokój się. Chcę cię zapytać o żelazne krasnoludy i Lokena.', 'Uspokój się. Chcę cię zapytać o żelazne krasnoludy i Lokena.', 0),
(26263, 'koKR', 'Co cię tu sprowadza, maleńki?', '', 0),
(26264, 'koKR', 'Co możesz mi powiedzieć o Lokenie i żelaznych krasnoludach?', 'Co możesz mi powiedzieć o Lokenie i żelaznych krasnoludach?', 0),
(26265, 'koKR', 'Kulawy Joe nie zadałby takiego pytania! Ale tak, znam Lokena.', '', 0),
(26266, 'koKR', 'On też chce mnie dopaść! Na twoim miejscu uważałbym tutaj, wędrowcze. Nigdy nie wiadomo, za którym drzewem się chowa!', '', 0),
(26267, 'koKR', 'Ach, tak. Dobrze znam Lokena.', '', 0),
(26268, 'koKR', 'To on dowodzi synami żelaza w ich wojnie przeciw nam.', '', 0),
(26269, 'koKR', 'Ze swojej kryjówki nadzoruje ich przygotowania do wojny, której celem jest wytępienie kamiennych olbrzymów!', '', 0),
(26323, 'koKR', '', 'Naturalne piękno tych wzgórz skrywa pod sobą wielką ciemność. Stąpaj ostrożnie, $gprzyjacielu:przyjaciółko;.', 0),
(26324, 'koKR', 'Wychodek wygląda na zajęty.', '', 0),
(26331, 'koKR', 'Na szczęście wychodek jest akurat wolny.', '', 0),
(26332, 'koKR', 'Skorzystaj z wychodka.', 'Skorzystaj z wychodka.', 0),
(26350, 'koKR', 'Dobra, Ben. Znowu odzyskaliśmy bursztynowe nasiona. Wiesz, co robić.', '', 0),
(26351, 'koKR', 'Wiem, wiem. Z powrotem do wiadra...', '', 0),
(26361, 'koKR', 'Gdy dowiedziałem się o moich krewnych tu, na północy, przybyłem, by dowiedzieć się więcej. Zastałem wojujące plemiona, które działają wbrew samej naszej naturze.$B$BNie mam już żadnej nadziei. Nawet wielkiego Ursoca skaziło to przeklęte miejsce.$B$BStraciłem wszelką nadzieję.', '', 0),
(26373, 'koKR', 'Trzymaj się za mną. Zrobię, co w mojej mocy, by cię chronić.', '', 0),
(26374, 'koKR', 'Moja wolność nic nie znaczy, jeśli nie zdołamy ocalić Ursoca. Pospiesz się, $N.', '', 0),
(26375, 'koKR', 'Będę czuwał nad tobą i twoimi sojusznikami.', '', 0),
(26376, 'koKR', 'Przybierz swoją druidzką postać niedźwiedzia, Tur.', 'Przybierz swoją druidzką postać niedźwiedzia, Tur.', 0),
(26377, 'koKR', 'Pomóż nam go obezwładnić.', 'Pomóż nam go obezwładnić.', 0),
(26378, 'koKR', 'Przydałby się nam uzdrowiciel.', 'Przydałby się nam uzdrowiciel.', 0),
(26379, 'koKR', 'Mamy oczyszczone popioły sadzonki Vordrassila. Jeśli zdołamy obezwładnić Ursoca, może uda nam się uleczyć jego duszę.', 'Mamy oczyszczone popioły sadzonki Vordrassila. Jeśli zdołamy obezwładnić Ursoca, może uda nam się uleczyć jego duszę.', 0),
(26380, 'koKR', 'Tak... Wyczuwam magię Vordrassila... wolną od jakiegokolwiek dostrzegalnego skażenia.$B$BProszę! Musisz mi pozwolić sobie pomóc. Los mnie tu sprowadził, może jeszcze do czegoś się przydam!', '', 0),
(26407, 'koKR', 'Niegdyś przemierzałem Wzgórza Grizli jako syn wielkiego Ursoca, który władał tą krainą.$B$BAle teraz... teraz jestem skazany na spędzenie reszty życia w tej jaskini.', '', 0),
(26408, 'koKR', 'Możesz odejść, Orsonnie, ale najpierw powiedz mi, co się dzieje z furbolgami.', 'Możesz odejść, Orsonnie, ale najpierw powiedz mi, co się dzieje z furbolgami.', 0),
(26409, 'koKR', 'Nie rozumiesz. Gdybym chciał, mógłbym wywalczyć sobie drogę z tej jaskini.$B$BChodzi o mojego ojca, Ursoca. Powrócił z martwych... ale nie jest już taki sam.$B$BOddał życie podczas Wojny Starożytnych tysiące lat temu. Przez stulecia furbolgi, które go czciły, próbowały znaleźć sposób, by go wskrzesić.$B$BW końcu postanowiły spróbować odhodować nieudane drzewo świata, Vordrassil, i użyć jego magii, by przywrócić mojego ojca.', '', 0),
(26412, 'koKR', 'Sadzonka, którą wyhodowały, wydała owoc. Z początku wydawało się, że to działa. Ursoc naprawdę powrócił, a mnie na krótką chwilę wypełniła radość.$B$BGdy dochodził do siebie, stało się jasne, że nie jest już taki sam. Furbolgi również.$B$BJakiekolwiek zło skłoniło dawnych druidów do ścięcia Vordrassila, objawiło się w nowym drzewie i zamieniło ich wszystkich w potwory pełne żądzy krwi.$B$BTo, co teraz chodzi po Wzgórzach Grizli, nie jest moim ojcem i trzeba temu dać wieczny spoczynek.', '', 0),
(26413, 'koKR', 'Dziękuję, synu Ursoca. Zobaczę, co da się zrobić.', 'Dziękuję, synu Ursoca. Zobaczę, co da się zrobić.', 0),
(26414, 'koKR', 'Jestem Kodian, córka Ursoca. Czuwam nad tą niegdyś świętą kaplicą.$B$BOd dawna nie widziałam, by przybył tu jakiś obcy.', '', 0),
(26415, 'koKR', 'Kim był ten obcy?', 'Kim był ten obcy?', 0),
(26416, 'koKR', 'Furbolg imieniem Tur Wściekłołap. Nie jeden z naszych.$B$BPrzybył z krain na południu. Należał do plemienia Pyskodrzewnych.$B$BChciał zobaczyć Ursoca. Najwyraźniej sądził, że skażenie Vordrassila można oczyścić i użyć go do ocalenia mojego ojca.$B$BŻywienie takich nadziei to głupota. Przyznasz mi rację, gdy zobaczysz ciemność, która go dotknęła, tak jak ja ją widziałam.', '', 0),
(26417, 'koKR', 'Dziękuję, Kodian. Zrobię, co w mojej mocy.', 'Dziękuję, Kodian. Zrobię, co w mojej mocy.', 0),
(26425, 'koKR', 'Nareszcie godna ofiara!', '', 0),
(26427, 'koKR', 'Ursocu, bracie Ursola i strażniku plemion furbolgów... pokaż się!', '', 0),
(26461, 'koKR', 'Tu przykuto łańcuchami kapryśnego protosmokowca thana Torvalda Erikssona.', '', 0),
(26462, 'koKR', 'Rozkuj Płomieniodzierżcę i przejmij nad nim kontrolę.', 'Rozkuj Płomieniodzierżcę i przejmij nad nim kontrolę.', 0),
(26519, 'koKR', 'Krenna musi wątpić w moje umiejętności. Podczas gdy nasi elitarni wojownicy wyruszają, by stawić czoła Przymierzu i jego sojusznikom traperom albo siać spustoszenie wśród trolli, mnie przydzielono do wymiatania tych natrętnych wrykułów Smokołupców.$B$BMoże jeśli połączymy siły, zdołamy dowieść swojej wartości w oczach zdobywczyni.', '', 0),
(26520, 'koKR', 'Witaj w Chacie Bursztynowej Sosny.', '', 0),
(26569, 'koKR', 'Pozdrowienia.$b$bChcesz, żeby Darrok wysłał cię do Zatoki Gitgeszeft?', '', 0),
(26604, 'koKR', 'Siema!$b$b$gGotów:Gotowa; ruszyć do Zatoki Gitgeszeft i porozbijać trochę hordziackich czerepów?', '', 0),
(26605, 'koKR', 'Tak, ruszajmy do Zatoki Gitgeszeft!', 'Tak, ruszajmy do Zatoki Gitgeszeft!', 0),
(26639, 'koKR', 'Na Światłość, $gzabiłeś:zabiłaś; Kulawego Joe i $gzabrałeś:zabrałaś; mięso! Skąd $gwiedziałeś:wiedziałaś;, gdzie nas szukać?', '', 0),
(26642, 'koKR', 'No cóż, jeśli $gprzyszedłeś:przyszłaś; zabić i mnie, to czy możesz chociaż poczekać, aż nakarmię Griseldę? Biedaczka nie jadła od kilku dni.', '', 0),
(26643, 'koKR', 'Chodź tu, maleńka. Mam dla ciebie ostatni posiłek, zanim wykończy nas zabójca Kulawego Joe!', '', 0),
(26645, 'koKR', 'Jak $gmogłeś:mogłaś; zabić biednego, bezbronnego, starego Joe? I czemu $gprzyniosłeś:przyniosłaś; mięso z powrotem?', '', 0),
(26646, 'koKR', 'Jesteś zagadką, ot co... A powiem ci, że z zagadkami się nie dogaduję...', '', 0),
(26647, 'koKR', 'Chyba lepiej już idź, zanim Griselda uzna, że ma ochotę na deser.', '', 0),
(26656, 'koKR', 'Dziękuję ci.', '', 0),
(26657, 'koKR', 'Aaach... lepiej.', '', 0),
(26659, 'koKR', 'Uff – prawie tam umarłem. Dziękuję!', '', 0),
(26682, 'koKR', 'Niech cię Światłość błogosławi, $gprzyjacielu:przyjaciółko;. Prawie wyzionąłem ducha...', '', 0),
(26683, 'koKR', 'Dziękuję!', '', 0),
(26684, 'koKR', 'Prawie się poddałem. $GDałeś:Dałaś; mi nowe życie!', '', 0),
(26685, 'koKR', 'Bez twojej pomocy na pewno bym umarł...', '', 0),
(26686, 'koKR', 'NIEEEEE! Mamo! Pomścimy cię!', '', 0),
(26698, 'koKR', 'Siemasz!$b$bJeśli szukasz rozdrabniacza do jazdy, musisz się wybrać na wzgórza.$b$bTen jest nieczynny.', '', 0),
(26704, 'koKR', 'No cóż, zanim wybuchły tu walki, naprawialiśmy je do wyrębu tutejszych drzew.$b$bOstatnio jednak musiały pójść na służbę przeciw Hordzie. Okazuje się, że z nich całkiem niezłe machiny bojowe. Jeśli masz kluczyk, głupotą byłoby go nie użyć!', '', 0),
(26708, 'koKR', 'Mój brat, Synipus, ma ich mnóstwo. Idź na północ, do Tartaku „Błękitne Niebo”, i z nim pogadaj.', '', 0),
(26847, 'koKR', 'Muszę się stąd wydostać!', '', 0),
(26848, 'koKR', 'Wszyscy zginiemy!', '', 0),
(26849, 'koKR', 'Nie na to się pisałem!', '', 0),
(26850, 'koKR', 'Mam to gdzieś! Wracam do domu!', '', 0),
(26851, 'koKR', 'Nie ma mowy, żebym tu został!', '', 0),
(26868, 'koKR', 'Hej, $gwidziałeś:widziałaś; to? Tam, kręci się tuż przy powierzchni wody...$b$bTy też to $gwidziałeś:widziałaś;, co?', '', 0),
(26869, 'koKR', 'Chodzi ci o górę lodową?', 'Chodzi ci o górę lodową?', 0),
(26870, 'koKR', 'O co??$b$bCóż, ja je nazywam niezidentyfikowanymi obiektami pływającymi. A tam, skąd pochodzę, większość w ogóle zaprzecza ich istnieniu.$b$bAle ja wiem swoje! Widziałem je nawet z bliska! Ostatnie lata spędziłem na budowie tego statku, żeby je namierzać, śledzić, dokumentować, a w razie potrzeby niszczyć!', '', 0),
(26871, 'koKR', 'Przyznam, krasnoludzie, że byłem mile zaskoczony, gdy twój plan się powiódł.', '', 0),
(26872, 'koKR', 'Cały ten sprzęt tylko po to, żeby badać lód?', 'Cały ten sprzęt tylko po to, żeby badać lód?', 0),
(26873, 'koKR', 'Nie możemy po prostu pozwolić ci wrócić do towarzyszy, a nie możemy też zabrać cię ze sobą...', '', 0),
(26874, 'koKR', 'Chwileczkę! Obiecaliście mnie oszczędzić, jeśli wam pomogę. Dotrzymałem swojej części umowy!', '', 0),
(26875, 'koKR', 'Wstrzymaj ostrze, wodzu. On może być jeszcze dla nas cenny.', '', 0),
(26876, 'koKR', 'Nie daj się zwieść. Są bardzo nieuchwytne. W jednej chwili są, w następnej już ich nie ma – praktycznie nie do wyjaśnienia!$b$bMiędzy nami mówiąc, raz nawet trzymałem kawałek jednego z nich w ręce! Niestety, zanim zdążyłem przeprowadzić jakiekolwiek pomiary, zniknął! Po prostu przepadł...', '', 0),
(26877, 'koKR', 'To tylko lód. Po co to całe zamieszanie?', 'To tylko lód. Po co to całe zamieszanie?', 0),
(26878, 'koKR', 'Pamiętasz ten krasnoludzki dziennik, który znaleziono? Otóż ten krasnolud może być dokładnie tym, czego potrzebujemy, by wytropić i pojmać Branna Miedziobrodego.', '', 0),
(26879, 'koKR', 'Na Światłość, Brann żyje? Nigdy nie pomogę wam go pojmać!', '', 0),
(26880, 'koKR', 'Pomożesz, jeśli chcesz zachować głowę na karku.', '', 0),
(26881, 'koKR', 'Czy to cię zadowala, Tormaku?', '', 0),
(26882, 'koKR', 'Będzie żył, dopóki okaże się przydatny. Na twoim miejscu bym uważał, krasnoludzie.', '', 0),
(26883, 'koKR', 'Dużo ty wiesz...$b$bJedni mówią, że tylko obserwują, inni myślą, że zmieniają nasze życie morskie, a jeszcze inni, że przybyły tu, by przejąć Azeroth!$b$bKiedy zestrzelę jednego moimi głowicami z napędem rakietowym, poznam odpowiedzi. Możesz mi wierzyć!', '', 0),
(26884, 'koKR', '', 'Niespodzianka, szumowino! Powiesz mi, gdzie jest moja siostra, albo wpakuję twojej żonie w serce całe wiadro kul z prawdziwego srebra.', 0),
(26885, 'koKR', 'Stój! Nie strzelaj! Nie krzywdź Tatjany!', '', 0),
(26886, 'koKR', 'Bachora trzymają w wilczej norze po drugiej stronie góry. Miała trafić do Arugala. Możemy już iść?', '', 0),
(26887, 'koKR', 'Wybacz mi, Tatjano...', '', 0),
(26888, 'koKR', 'Nic, co możesz nam zrobić, nie da się porównać z tym, co może nam zrobić Arugal! Sam cię rozszarpię!', '', 0),
(26889, 'koKR', '', 'Gdzie jest Anya?', 0),
(26890, 'koKR', '', 'Jeszcze jedno. Muszę wiedzieć, gdzie jest Arugal.', 0),
(26891, 'koKR', '', 'Dziękuję, że $gpomogłeś:pomogłaś; mi wrócić do obozu. Idź powiedz Walterowi, że jestem już bezpieczna!', 0),
(26892, 'koKR', '', 'On zje Pana Kłapusia! Musisz pomóc Panu Kłapusiowi! Po prostu musisz!', 0),
(26893, 'koKR', '', 'Jakiś wielki niedobry atakuje Pana Kłapusia! Pomocy!', 0),
(26894, 'koKR', '', 'Chyba widzę obóz! Już prawie jesteśmy w domu, Panie Kłapusiu! Chodźmy!', 0),
(26914, 'koKR', '', 'Nie zjesz mnie, prawda?', 0),
(26915, 'koKR', '', 'Anya!! Nic ci nie jest!', 0),
(26916, 'koKR', '', 'Złego Księżyca? Chodzi ci o Krwawego Księżyca?', 0),
(26917, 'koKR', '', 'Nie bój się, siostrzyczko... nikt cię już nie skrzywdzi.', 0),
(26918, 'koKR', '', 'Siostro! Źli panowie chcieli mnie zabrać na Wyspę Złego Księżyca. Chcieli, żebym była taka jak oni.', 0),
(26919, 'koKR', '', 'Przecież tak powiedziałam! Złego Księżyca! Sasha... nigdy więcej mnie nie zostawiaj! Najpierw zabrali tatę, potem ciebie... Nie chcę być z nimi sama!', 0),
(26934, 'koKR', 'Dzień dobry. Giermek Walter i ja opiekujemy się tu Starą Siwką i resztą wierzchowców.', '', 0),
(26945, 'koKR', 'Witaj w Obozie Oneqwah.', '', 0),
(26946, 'koKR', 'Chcę skorzystać ze stajni.', 'Chcę skorzystać ze stajni.', 0),
(27014, 'koKR', 'Panie i panowie... zbierzcie się wokół dołu!', '', 0),
(27015, 'koKR', 'W jednym narożniku mamy... $N, prawdziwa światowa klasa! $GPogromca:Pogromczyni; gadów, ssaków, mechanicznych konstruktów i od czasu do czasu jakiegoś smoka... no, smokowca. Drugiej takiej osoby jak $gon:ona; jeszcze nie widzieliście.', '', 0),
(27016, 'koKR', 'W drugim narożniku seryjny morderca, masowy wyrzucacz przez okna, wielokrotnie skazany na śmierć przez powieszenie i przez tępe narzędzie! Horgrenn... Piekłorąb! Panie i panowie... obstawiajcie zakłady!', '', 0),
(27017, 'koKR', 'Panie i panowie, zbierzcie się wokół Dołu Podboju! Zobaczcie walkę śmiałka z niedźwiedziem i śmiało obstawiajcie zakłady!', '', 0),
(27018, 'koKR', 'Kiedy już myślicie, że widzieliście wszystko! $N zmierzy się z prawdziwym obłąkanym furbolgiem ze Wzgórz Grizli na waszych oczach, tu, w Dole Podboju! Obstawiajcie zakłady, ludzie!', '', 0),
(27019, 'koKR', 'Podejdźcie, ludzie! Weźcie coś ciepłego do picia i znajdźcie dobre miejsce, bo zaraz zobaczycie starcie istoty z krwi i kości z maszyną!', '', 0),
(27020, 'koKR', 'Prosto z Thor Modan, zrobiony w stu procentach z autentycznego... metalu... oto Rdzawokrwisty, żelazny golem zasilany błyskawicami!', '', 0),
(27026, 'koKR', '', 'Nie musi się to tak skończyć, wiesz?', 0),
(27027, 'koKR', '', 'Kierowałam się rozsądkiem, gdy ty nie okazałaś go wcale. Nie chcę patrzeć, jak prowadzisz nas do zguby, Krenno!', 0),
(27032, 'koKR', 'Panie i panowie! No cóż... powiedzmy, że tego nie możecie przegapić!', '', 0),
(27033, 'koKR', '', 'Czemu... czemu, siostro? Czemu musiało do tego dojść?', 0),
(27036, 'koKR', 'Głowice z napędem rakietowym? Czy to nie trochę zbyt agresywne?', 'Głowice z napędem rakietowym? Czy to nie trochę zbyt agresywne?', 0),
(27037, 'koKR', 'Słuchaj no. Kiedy szukasz odpowiedzi, nic nie przebije dobrego wybuchu – im większego, tym lepiej!$b$bAle na razie chyba wystarczy tych pytań.$b$bMoje głowice to materiały tajne, a pierwiastek 115, który stworzyłem, żeby je zasilać, jest jeszcze bardziej tajny!$b$bWłaściwie najlepiej będzie, jeśli po prostu wrócisz do swojego codziennego życia i będziesz udawać, że nigdy się nie spotkaliśmy.', '', 0),
(27067, 'koKR', 'Słuchaj.$b$bJeśli szukasz rozdrabniacza do jazdy, musisz się wybrać na wzgórza tuż na północy.$b$bTen jest nieczynny.', '', 0),
(27068, 'koKR', 'A po co $gmiałbym:miałabym; jeździć na rozdrabniaczu?', 'A po co $gmiałbym:miałabym; jeździć na rozdrabniaczu?', 0),
(27069, 'koKR', 'Z początku naprawialiśmy je do wyrębu tutejszych lasów, ale odkąd przybyło Przymierze i wybuchły walki, używamy ich jako machin wojennych.$b$bWierz mi, jeśli masz kluczyk, to szaleństwem byłoby go nie użyć.', '', 0),
(27071, 'koKR', 'Skąd mogę wziąć Odnowiony klucz rozdrabniacza?', 'Skąd mogę wziąć Odnowiony klucz rozdrabniacza?', 0),
(27072, 'koKR', 'Ma je Grekk.$b$bMoże ci jeden da, jeśli mu pomożesz. Następnym razem, gdy będziesz na północy w Tartaku „Błękitne Niebo”, koniecznie z nim pogadaj.', '', 0),
(27099, 'koKR', 'Pokaż mi, co masz na sprzedaż, traperze.', 'Pokaż mi, co masz na sprzedaż, traperze.', 0),
(27108, 'koKR', '', 'Pozwól, że ja się tym zajmę, siostro.', 0),
(27109, 'koKR', '', 'Co ty sobie myślałeś, żeby ją tak prowokować?', 0),
(27110, 'koKR', '', 'Ty... półgłówku! Tym razem naprawdę przesadziłeś. Będę musiała upozorować, że masz złamaną nogę.', 0),
(27111, 'koKR', '', 'A teraz się nie ruszaj, jeśli chcesz jeszcze kiedyś chodzić!', 0),
(27112, 'koKR', 'Nie, proszę! Nie rób tego!', '', 0),
(27124, 'koKR', 'Witaj w Granitowych Źródłach, $gprzyjacielu:przyjaciółko;.$b$bJeśli uda ci się złapać żywcem któregoś z tych lodowych trolli, koniecznie daj mi znać. Dobrze za nie płacimy.', '', 0),
(27282, 'koKR', '<Drakuru wyciąga przez klatkę krwawiącą dłoń i patrzy na ciebie wyczekująco.>', '', 0),
(27283, 'koKR', 'Uściśnij wyciągniętą dłoń Drakuru.', 'Uściśnij wyciągniętą dłoń Drakuru.', 0),
(27284, 'koKR', 'Były czasy, że wyrwałbym ci serce, tylko żeby zobaczyć twoją minę...', '', 0),
(27285, 'koKR', 'Ej, mon!$b$bDobrze cię znowu widzieć... $N, tak? Tak, tak, oczywiście.$b$bTy i ja będziemy naprawdę dobrymi przyjaciółmi. Drakuru wie takie rzeczy.$b$b<Na pomalowanej twarzy trolla powoli pojawia się uśmiech.>', '', 0),
(27286, 'koKR', 'Potrzebuję kolejnego twojego eliksiru, Drakuru.', 'Potrzebuję kolejnego twojego eliksiru, Drakuru.', 0),
(27290, 'koKR', 'Trolle z Plagi szkwarczą szobie...', '', 0),
(27291, 'koKR', '...nad ogniszkiem wesołym...', '', 0),
(27292, 'koKR', 'No i tyle! Dalej nie doszedłem... Co ty na to?', '', 0),
(27309, 'koKR', 'Ej, mon!$b$bTo nie jest to, na co wygląda. No, może...$b$bTo skomplikowane.', '', 0),
(27331, 'koKR', 'Za Drak\'Tharon!', '', 0),
(27332, 'koKR', 'Zim\'bo musi przeżyć, żeby zabić naszego zdrajcę!', '', 0),
(27333, 'koKR', 'Zim\'bo nie da się powstrzymać! Twierdzę trzeba wyzwolić!', '', 0),
(27334, 'koKR', 'Zginiesz razem z całą tą Plagą!', '', 0),
(27335, 'koKR', 'Zdradził nas jeden z naszych. Hańba...', '', 0),
(27336, 'koKR', 'Ach, kolejna esencja do schwytania...', '', 0),
(27343, 'koKR', 'Witaj w moim obozie.$b$bMoże nie wygląda na wiele, ale na razie to mój dom.', '', 0),
(27347, 'koKR', '', 'Pan Kłapuś i ja poszliśmy na spacer, ale potem się zgubiliśmy i strasznie się bałam, bo były tam te wilki, wie $gpan:pani;, i nas goniły, ale potem zobaczyłam tę wieżę i Pan Kłapuś i ja schowaliśmy się tutaj, i wilki w końcu po jakimś czasie sobie poszły, i to było okropne, i teraz nie wiemy, jak wrócić do domu.', 0),
(27348, 'koKR', '', 'Chyba $gpowinien pan:powinna pani; już iść. $GStraszy pan:Straszy pani; Pana Kłapusia.', 0),
(27383, 'koKR', 'Pozdrowienia!$b$bMam nadzieję, że nie boisz się ciężkiej pracy. Przydałaby się nam tu pomoc.', '', 0),
(27384, 'koKR', '', 'Wiatr i drzewa szepczą o niewidocznych kłopotach. Kraina wygląda na zdrową, ale dzieje się tu więcej, niż widać na pierwszy rzut oka.', 0),
(27385, 'koKR', '', '<Thayreen patrzy pustym wzrokiem. Oczyszczenie Vordrassila ze skażenia odbiło się na druidce.>', 0),
(27386, 'koKR', 'Skóry dla Hordy, mon! Tylko najlepsze dla naszych żołnierzy!', '', 0),
(27387, 'koKR', 'Trochę zapasów na drogę? A może coś orzeźwiającego do popijania podczas oglądania walk?', '', 0),
(27933, 'koKR', 'Ach, nareszcie z powrotem w Drak\'Tharon!', '', 0),
(27934, 'koKR', 'Drakuru spogląda z góry na Twierdzę Drak\'Tharon.', '', 0),
(27935, 'koKR', 'Dobrze się $gspisałeś:spisałaś;, mon...', '', 0),
(27954, 'koKR', '$GPrzeszedłeś:Przeszłaś; moje najśmielsze oczekiwania.', '', 0),
(28118, 'koKR', 'Za twoje wysiłki dostaniesz największą z nagród...', '', 0),
(28119, 'koKR', 'Objawienie!', '', 0),
(28120, 'koKR', 'Stój spokojnie, $gprzyjacielu:przyjaciółko;, i ujrzyj prawdę!', '', 0),
(28125, 'koKR', 'Panie, moja misja wykonana.', '', 0),
(28127, 'koKR', 'Z pomocą tych śmiertelników ten region został oczyszczony ze wszystkich, którzy nam się sprzeciwiają.', '', 0),
(28251, 'koKR', 'Witaj w obozie.', '', 0),
(28419, 'koKR', 'Jak sobie życzysz, panie.', '', 0),
(28420, 'koKR', 'Wybacz mi to oszustwo, mon. Wszystko było dla twojego dobra.', '', 0),
(28421, 'koKR', '$GMusiałeś:Musiałaś; dowieść, że jesteś $ggodny:godna;...', '', 0),
(28422, 'koKR', 'Potrzebuję w Zul\'Draku godnych podwładnych, mon. Takich, którzy są gotowi władać prawdziwą mocą.', '', 0),
(28423, 'koKR', 'Teraz widzisz na własne oczy. Król Lisz jest hojny dla tych, którzy są mu posłuszni.', '', 0),
(28424, 'koKR', 'Podążaj tą ścieżką, mon, a wkrótce zasmakujesz nieśmiertelności!', '', 0),
(28425, 'koKR', 'Zastanów się nad tym, czego $gbyłeś:byłaś; dziś świadkiem, $N.$b$bPrzyszłość jest już zapisana. Pozostaje tylko zdecydować, jaka będzie w niej twoja rola, mon.', '', 0),
(28896, 'koKR', 'Silniejsi, niż myślałem, mon, atakować ich!', '', 0),
(28897, 'koKR', 'Czekać na moje rozkazy, sam to załatwię!', '', 0),
(29447, 'koKR', '', 'Te potwory zabiły mi ojca i porwały siostrę. Zapłacą za to!', 0),
(29525, 'koKR', 'Chcę się udać do Wyłomu Światłości.', 'Chcę się udać do Wyłomu Światłości.', 0),
(29862, 'koKR', 'Nasze magazyny opustoszały. Nie mam nic na sprzedaż, dopóki nie dostaniemy nowych zapasów.', '', 0),
(29863, 'koKR', 'Dzięki temu, że $guzupełniłeś:uzupełniłaś; część naszych zapasów, mogę wrócić do gotowania. No więc, co mogę dla ciebie zrobić?', '', 0),
(29909, 'koKR', 'Dzięki błogosławieństwu Światłości i twojej pomocy, $N, Nieskorni nie są już zagrożeniem.$B$BAle tu na górze jesteśmy daleko od Zachodniego Skraju, a jeśli nie wygramy tej bitwy, może nie być domu, do którego da się wrócić.', '', 0),
(29967, 'koKR', 'Pozdrowienia, $gprzyjacielu:przyjaciółko;.', '', 0),
(31166, 'koKR', 'Co się stało potem?', 'Co się stało potem?', 0),
(33070, 'koKR', 'Nareszcie!$b$bPrzybył ten, kogo zapowiadały przepowiednie!', '', 0),
(33071, 'koKR', 'Jestem $ggotów:gotowa; wrócić do świata żywych.', 'Jestem $ggotów:gotowa; wrócić do świata żywych.', 0),
(33138, 'koKR', 'Z pomocą naszych nowych sojuszników taunka Północna Grań będzie należeć do Hordy.', '', 0),
(33362, 'koKR', '', 'Myślałam, że nigdy nie uwolnię się od tej strasznej klątwy. Masz moją wdzięczność, $gnieznajomy:nieznajoma;.', 0),
(33363, 'koKR', 'Cała przyjemność po mojej stronie, pani. $GSłyszałem:Słyszałam;, że niegdyś strzegłaś legendarnego miecza. Wiesz, gdzie mogę go znaleźć?', 'Cała przyjemność po mojej stronie, pani. $GSłyszałem:Słyszałam;, że niegdyś strzegłaś legendarnego miecza. Wiesz, gdzie mogę go znaleźć?', 0),
(33364, 'koKR', '', 'Weź go w podzięce.', 0),
(37237, 'koKR', 'Dziękuję!', 'Dziękuję!', 0);
